MattiasCRTEffect.prototype = {
  getName: function() {
    return "CRT (Mattias)";
  },

  getParams: function() {
    return this.params;
  },

  setParamValue: function(param, value) {
    switch(param) {
      case 'Curve':
        this.curve = (value == "On") ? 1 : 0;
        this.crtPass.uniforms['curve'].value = this.curve;
        break;
      case 'Frame':
        this.frame = (value == "On") ? 1 : 0;
        this.crtPass.uniforms['frame'].value = this.frame;
        break;
        case 'Pixel Shape':
        switch(value) {
          case "Square":
            this.pixelRatio = 0;
            break;
          case "Tall":
            this.pixelRatio = 1;
            break;
          case "TV":
            this.pixelRatio = 2;
            break;
        }
        this.crtPass.uniforms['pixelRatio'].value = this.pixelRatio;
        break;
      case 'Colour Bleed':
        this.colorBleed = value / 50;
        this.crtPass.uniforms['colorBleed'].value = this.colorBleed;
        break;
      case 'Ghosting':
        this.ghosting = value / 25;
        this.crtPass.uniforms['ghosting'].value = this.ghosting;
        break;
    
      case 'Scanline Intensity':
        this.scanlineIntensity = value / 100;
        this.crtPass.uniforms['scanlineAmount'].value = this.scanlineIntensity;
        break;
      case 'Vertical Line Intensity':
        this.verticalLineIntensity = value / 100;
        this.crtPass.uniforms['verticalLineAmount'].value = this.verticalLineIntensity;
        break;

      case 'Blur':
        //console.log('set blur to ' + value);
        this.blurValue = value / 100;
        this.blurPass.uniforms['amount'].value = this.blurValue;

        break;
      case 'Glow':
        this.glowValue = value / 50;
        this.bloomPass.copyUniforms["opacity"].value = this.glowValue;
        break;
    }
  },
  
  
  setupComposer: function(composer, width, height) {

    // BLUR
    this.blurPass = new THREE.ShaderPass( BlurShader );  
    this.blurPass.uniforms['resolution'].value = new THREE.Vector2( width, height );
    this.blurPass.uniforms['amount'].value = this.blurValue;
    composer.addPass( this.blurPass );

    var effectCopy = new THREE.ShaderPass( THREE.CopyShader );    
    composer.addPass(effectCopy);

    
    // CRT
    this.crtPass = new THREE.ShaderPass( MattiasCRTShader );

    this.crtPass.uniforms['resolution'].value = new THREE.Vector2( width, height );
    this.crtPass.uniforms['curve'].value = this.curve;
    this.crtPass.uniforms['frame'].value = this.frame;
    this.crtPass.uniforms['pixelRatio'].value = this.pixelRatio;
    this.crtPass.uniforms['colorBleed'].value = this.colorBleed;
    this.crtPass.uniforms['ghosting'].value = this.ghosting;
    this.crtPass.uniforms['scanlineAmount'].value = this.scanlineIntensity;
    this.crtPass.uniforms['verticalLineAmount'].value = this.verticalLineIntensity;
    
    composer.addPass( this.crtPass );


    // BLOOM
    this.bloomPass = new THREE.BloomPass();
    this.bloomPass.copyUniforms["opacity"].value = this.glowValue;
    composer.addPass(this.bloomPass);

  }
}

var NoisyGlowEffect = function() {
  this.params = [
    {
      "name": "Blur",
      "min": 0,
      "max": 100,
      "type": "range",
      "value": 30,
      "default": 30
    },    
    {
      "name": "Noise",
      "min": 0,
      "max": 100,
      "type": "range",
      "value": 30,
      "default": 30
    },

    {
      "name": "BlurTwo",
      "min": 0,
      "max": 100,
      "type": "range",
      "value": 30,
      "default": 30
    },    

    {
      "name": "Glow",
      "min": 0,
      "max": 100,
      "type": "range",
      "value": 30,
      "default": 30
    }
  ];


  this.blurValue = 0.1;
  this.blur2Value = 0.1;
  this.noiseValue = 0.3;
  this.glowValue = 0.3;
  

}

NoisyGlowEffect.prototype = {
  getName: function() {
    return "Noisy Glow";
  },

  getParams: function() {
    return this.params;
  },

  setParamValue: function(param, value) {
    switch(param) {
      case 'Blur':
        this.blurValue = value / 100;
        this.blurPass.uniforms['amount'].value = this.blurValue;
        break;

      case 'Noise':
        this.noiseValue = value / 100;
        this.noisePass.uniforms['nIntensity'].value = this.noiseValue;
        break;
      case 'BlurTwo':
        this.blur2Value = value / 100;
        this.blur2Pass.uniforms['amount'].value = this.blur2Value;
        break;
  
      case 'Glow':
        this.glowValue = value / 50;
        this.bloomPass.copyUniforms["opacity"].value = this.glowValue;
        break;
    }
  },
  
  // need glow applied to noise, not noise + src
  // need noise variance
  
  setupComposer: function(composer, width, height) {


    BlurShader.uniforms['amount'].value = this.blurValue;
    BlurShader.uniforms['resolution'].value = new THREE.Vector2( width, height );
    this.blurPass = new THREE.ShaderPass( BlurShader );  
    composer.addPass( this.blurPass);

    var effectCopy = new THREE.ShaderPass( THREE.CopyShader );    
    composer.addPass(effectCopy);

    this.noisePass = new THREE.ShaderPass( NoiseShader );     

    this.noisePass.uniforms['nIntensity'].value = this.noiseValue;
    composer.addPass( this.noisePass);
    effectCopy = new THREE.ShaderPass( THREE.CopyShader );    
    composer.addPass(effectCopy);

    this.blur2Pass = new THREE.ShaderPass( BlurShader );  
    composer.addPass( this.blur2Pass);

    this.bloomPass = new THREE.BloomPass();
    this.bloomPass.copyUniforms["opacity"].value = this.glowValue ;//this.effectsList[i].params['opacity'];
    composer.addPass(this.bloomPass);

  }
}

BlurShader = {

  uniforms: {

    "tDiffuse":     { value: null },
    "amount":       { value: 1.0 },
    "resolution":   { value: new THREE.Vector2( 960.0, 600 ) },
  },

  vertexShader: [

    "varying vec2 vUv;",

    "void main() {",

      "vUv = uv;",
      "gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );",

    "}"

  ].join( "\n" ),

  fragmentShader: [
    "uniform sampler2D tDiffuse;",
    "uniform float amount;",
    "uniform vec2 resolution;",
    "varying vec2 vUv;",

    "void main( void )",
        "    {",
        "    vec2 uv = vUv;",
        "    vec2 blur = vec2(amount/resolution.x, amount/resolution.y);",

        "    vec4 sum = texture2D( tDiffuse, uv ) * 0.2270270270;",
        "    sum += texture2D(tDiffuse, vec2( uv.x - 4.0 * blur.x, uv.y - 4.0 * blur.y ) ) * 0.0162162162;",
        "    sum += texture2D(tDiffuse, vec2( uv.x - 3.0 * blur.x, uv.y - 3.0 * blur.y ) ) * 0.0540540541;",
        "    sum += texture2D(tDiffuse, vec2( uv.x - 2.0 * blur.x, uv.y - 2.0 * blur.y ) ) * 0.1216216216;",
        "    sum += texture2D(tDiffuse, vec2( uv.x - 1.0 * blur.x, uv.y - 1.0 * blur.y ) ) * 0.1945945946;",
        "    sum += texture2D(tDiffuse, vec2( uv.x + 1.0 * blur.x, uv.y + 1.0 * blur.y ) ) * 0.1945945946;",
        "    sum += texture2D(tDiffuse, vec2( uv.x + 2.0 * blur.x, uv.y + 2.0 * blur.y ) ) * 0.1216216216;",
        "    sum += texture2D(tDiffuse, vec2( uv.x + 3.0 * blur.x, uv.y + 3.0 * blur.y ) ) * 0.0540540541;",
        "    sum += texture2D(tDiffuse, vec2( uv.x + 4.0 * blur.x, uv.y + 4.0 * blur.y ) ) * 0.0162162162;",
        "    gl_FragColor = sum;",
        "    }   "
  ].join("\n"),

};


