    frame = parseInt(frame, 10);

    if(isNaN(frame) || frame >= this.frameCount || frame < 0) {
      return false;
    }


    this.currentFrame = parseInt(frame, 10);

    this.createFrameData(this.currentFrame);

    this.invalidateAllCells();

