    cell.x = x;
    cell.y = y;
    cell.z = z;

    cell.t = t;
    cell.fc = fc;
    cell.bc = bc;
    cell.fh = fh;
    cell.fv = fv;
    cell.rx = rx;
    cell.ry = ry;
    cell.rz = rz;

    if(!cellExists) {
      gridData[key] = cell;
    }

    this.editor.modified();
