  keyDown: function(event) {
    var keyCode = event.keyCode;
    if(keyCode == 46) {
      // del key
      return;
    }
    var c = String.fromCharCode(keyCode).toUpperCase();

    if(keyCode == 190) {
      c = '.';
    }

    if(keyCode == 188) {
      c = ',';
    }
    switch(c) {
      case keys.textMode.framesNext.key:
        this.nextFrame();
      break;
      case keys.textMode.framesPrev.key:
        this.prevFrame();
      break;
    }


  },

