ColorPaletteEditor.prototype = {
  init: function() {

  },

  buildInterface: function(parentPanel) {
    if(this.uiComponent != null) {
      return;
    }

    this.uiComponent = UI.create("UI.Panel", { "id": "colorPaletteEditor" } );
    parentPanel.add(this.uiComponent);

    this.colorPaletteEdit = new ColorPaletteEdit();
    this.colorPaletteEdit.init(g_app.textModeEditor);
    this.colorPaletteEdit.buildInterface(this.uiComponent);
    

//    var htmlPanel = UI.create("UI.HTMLPanel", { "html": '<div style="color: white; background-color: red">colorpalette editor</div>' });

//    this.uiComponent.add(htmlPanel);

  },

  draw: function() {
    this.load(this.path);
//    this.colorPaletteEdit.drawPalette();
  },

  
  load: function(path) {
    var colorPaletteManager = g_app.textModeEditor.colorPaletteManager;
    this.path = path;

    var record = g_app.doc.getDocRecord(path);
    
    if(record != null) {

      this.doc = record;

      colorPaletteManager.setCurrentColorPaletteFromId(this.doc.id);
      this.colorPaletteEdit.setAutosave(true);
      this.colorPaletteEdit.setToCurrentPalette();

    }


  }
}


// https://medium.com/@bantic/hand-coding-a-color-wheel-with-canvas-78256c9d7d43
// hand code color whee;


// https://twitter.com/beast_pixels/status/1007953732632567808

function xy2polar(x, y) {
  var r = Math.sqrt(x*x + y*y);
  var phi = Math.atan2(y, x);
  return [r, phi];
}

function polar2xy(r, phi) {
  var x = r * Math.cos(phi);
  var y = r * Math.sin(phi);

  return [x,y];
}

// rad in [-Ï€, Ï€] range
// return degree in [0, 360] range
function rad2deg(rad) {
  return ((rad + Math.PI) / (2 * Math.PI)) * 360;
}


// hue in range [0, 360]
// saturation, value in range [0,1]
// return [r,g,b] each in range [0,255]
// See: https://en.wikipedia.org/wiki/HSL_and_HSV#From_HSV

function hsv2rgb(hue, saturation, value) {
  var chroma = value * saturation;
  var hue1 = hue / 60;
  var x = chroma * (1- Math.abs((hue1 % 2) - 1));
  var r1, g1, b1;
  if (hue1 >= 0 && hue1 <= 1) {
    r1 = chroma;
    g1 = x;
    b1 = 0;
//    ([r1, g1, b1] = [chroma, x, 0]);
  } else if (hue1 >= 1 && hue1 <= 2) {
    r1 = x;
    g1 = chroma;
    b1 = 0;
//    ([r1, g1, b1] = [x, chroma, 0]);
  } else if (hue1 >= 2 && hue1 <= 3) {
    r1 = 0;
    g1 = chroma;
    b1 = x;
//    ([r1, g1, b1] = [0, chroma, x]);
  } else if (hue1 >= 3 && hue1 <= 4) {
    r1 = 0;
    g1 = x;
    b1 = chroma;

//    ([r1, g1, b1] = [0, x, chroma]);
  } else if (hue1 >= 4 && hue1 <= 5) {
    r1 = x;
    g1 = 0;
    b1 = chroma;
//    ([r1, g1, b1] = [x, 0, chroma]);
  } else if (hue1 >= 5 && hue1 <= 6) {
    r1 = chroma;
    g1 = 0;
    b1 = x;
//    ([r1, g1, b1] = [chroma, 0, x]);
  }
  
  var m = value - chroma;
//  var [r,g,b] = [r1+m, g1+m, b1+m];
  var r = r1+m;
  var g = g1+m;
  var b = b1+m;
  
  // Change r,g,b values from [0,1] to [0,255]
  return [255*r,255*g,255*b];
}


/**
 * Converts an RGB color value to HSV. Conversion formula
 * adapted from http://en.wikipedia.org/wiki/HSV_color_space.
 * Assumes r, g, and b are contained in the set [0, 255] and
 * returns h, s, and v in the set [0, 1].
 *
 * @param   Number  r       The red color value
 * @param   Number  g       The green color value
 * @param   Number  b       The blue color value
 * @return  Array           The HSV representation
 */
function rgb2hsv(r, g, b) {
  r /= 255, g /= 255, b /= 255;

  var max = Math.max(r, g, b), min = Math.min(r, g, b);
  var h, s, v = max;

  var d = max - min;
  s = max == 0 ? 0 : d / max;

  if (max == min) {
    h = 0; // achromatic
  } else {
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      case b: h = (r - g) / d + 4; break;
    }

    h /= 6;
  }

  return [ h, s, v ];
}

