var EditColorPaletteDialog = function() {
  this.editor = null;
  this.uiComponent = null;

  this.canvas = null;
  this.colorWidth = 16;
  this.colorHeight = 16;
  this.colorSpacing = 2;

  this.colorsAcross = 16;
  this.colorsDown = 16;

  this.colors = [];
}

EditColorPaletteDialog.prototype = {
  init: function(editor) {
    this.editor = editor;
  },

  htmlComponentLoaded: function() {
    this.canvas = document.getElementById('editColorPaletteCanvas')
    this.canvas.width = 16 * (this.colorWidth + this.colorSpacing) + this.colorSpacing;
    this.canvas.height = 16 * (this.colorHeight + this.colorSpacing) + this.colorSpacing;

    this.initColors();
    this.drawPalette();

  },

  initColors: function() {
    var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
    console.log('colour count = ' + colorPalette.getColorCount());

    this.colors = [];
    for(var i = 0; i < 256; i++) {
      this.colors.push({ color: false });
    }

    for(var i = 0; i < colorPalette.getColorCount(); i++) {
      this.colors[i].color = colorPalette.getHex(i);
    }

  },

  show: function() {
    var _this = this;
    if(this.uiComponent == null) {
      this.uiComponent = UI.create("UI.Dialog", 
        { "id": "editColorPalette", "title": "Edit/Create Colour Palette", "width": 810 });

      this.editColorPanel = UI.create("UI.HTMLPanel");
      this.editColorPanel.load('html/textMode/editColorPalette.html', function() {
        _this.htmlComponentLoaded();
      });
      this.uiComponent.add(this.editColorPanel);

      this.okButton = UI.create('UI.Button', { "text": "OK", "color": "primary" });
      this.uiComponent.addButton(this.okButton);
      this.okButton.on('click', function(event) {
        UI.closeDialog();
      });

      this.closeButton = UI.create('UI.Button', { "text": "Cancel", "color": "secondary" });
      this.uiComponent.addButton(this.closeButton);
      this.closeButton.on('click', function(event) {
        UI.closeDialog();
      });

      this.uiComponent.on('mousedown', function(event) {
        _this.mouseDown(event);
      });

      this.uiComponent.on('mouseup', function(event) {
        _this.mouseUp(event);
      });

      this.uiComponent.on('mousemove', function(event) {
        _this.mouseMove(event);
      });
    }

    UI.showDialog("editColorPalette");

  },

  mouseDown: function(event) {
    console.log('mouse down');
  },

  mouseMove: function(event) {
//    console.log(event);
    var x = event.clientX;
    var y = event.clientY;

    var canvasOffset = $('#editColorPaletteCanvas').offset();
//    console.log(canvasOffset);
//    console.log('mouse move' + x + ',' + y);

    if(x > canvasOffset.left && x < canvasOffset.left + this.canvas.width 
        && y > canvasOffset.top && y < canvasOffset.top + this.canvas.height) {
      console.log('in canvas');
    }
  },

  mouseUp: function(event) {
    console.log('mouse up');
  },

  drawPalette: function() {
    this.context = this.canvas.getContext('2d');

    var colorIndex = 0;
    for(var y = 0; y < this.colorsDown; y++) {
      for(var x = 0; x < this.colorsAcross; x++) {
        var xPos = this.colorSpacing + x * (this.colorWidth + this.colorSpacing);
        var yPos = this.colorSpacing + y * (this.colorHeight + this.colorSpacing);

        if(colorIndex < this.colors.length) {
          var color = this.colors[colorIndex].color;
          if(color !== false) {
            var colorHexString = ("000000" + color.toString(16)).substr(-6);

            console.log(this.colors[colorIndex].color);
            console.log('color hex string = ' + colorHexString);
            this.context.fillStyle = '#' + colorHexString;

            this.context.fillRect(xPos, yPos, this.colorWidth, this.colorHeight);
          } else {
            this.context.fillStyle = '#444444';
            this.context.fillRect(xPos, yPos, this.colorWidth, this.colorHeight);

          }
        } else {
//          console.log('color hex string = ' + colorHexString);

          this.context.fillStyle = '#984323';
          this.context.fillRect(xPos, yPos, this.colorWidth, this.colorHeight);
        }

        colorIndex++;

      }

    }

  }
}

var ColorSubPalettes = function() {
  this.editor = null;

  this.html = '';

  this.uiComponent = null;

  this.currentColorSubPalette = 0;
  this.currentColor = 1;
  this.colorSubPaletteCount = 4;
  this.colorPerColorSubPalette = 4;
  this.subPalettes = [];
  this.checking = false;
}


ColorSubPalettes.prototype = {
  setColorSubPaletteCount: function(colorSubPaletteCount) {
    this.colorSubPaletteCount = colorSubPaletteCount;

    if(colorSubPaletteCount == 4) {
      this.subPalettes.push([33, 32, 41, 22]);
      this.subPalettes.push([33, 12, 38, 26]);
      this.subPalettes.push([33, 18, 44, 29]);
      this.subPalettes.push([33, 48, 32, 16]);

    } else { 
      while(this.subPalettes.length < this.colorSubPaletteCount) {
        var subPalette = [33, 32, 41, 22];
        this.subPalettes.push(subPalette);
      }
    }
    this.initHTML();


  },

  initColors: function() {
    var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
    var colorCount = colorPalette.getColorCount();

    var lastColorIndex = -1;

    for(var i = 0; i < this.subPalettes.length; i++) {
      for(var j = 0; j < this.subPalettes[i].length; j++) {
        
        var colorIndex = this.subPalettes[i][j];
        if(colorIndex >= colorCount) {
          lastColorIndex++;
          if(lastColorIndex >= colorCount) {
            lastColorIndex = 0;
          }
          this.subPalettes[i][j] = lastColorIndex;
        }
      }
    }
    this.updateColors();
  },

  updateColors: function() {
    var currentSubPalette = this.currentColorSubPalette;
    for(var i = 0; i < this.subPalettes[currentSubPalette].length; i++) {
      this.setColor(i, this.subPalettes[currentSubPalette][i]);
    }
    
  },

  check: function(callback) {
    var _this = this;

    if(this.checking) {
      return;
    }
    this.checking = true;

    if(this.currentColorSubPalette == 'undefined') {
      this.currentColorSubPalette = 0;
    }
    var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
    var colorCount = colorPalette.getColorCount();

    console.log('colour count = ' + colorCount);

    /*
    if(colorCount !== 52) {
      if(confirm("You are not currently using the NES colour palette, would you like to switch?")) {
        this.editor.colorPaletteManager.choosePreset('nes', { "callback": function() {
          _this.initColors();
          if(typeof callback != 'undefined') {
            callback();
          }
          _this.checking = false;
        } });

        return;
      }
    } 
    */


    this.initColors();
    if(typeof callback != 'undefined') {
      callback();
    }
    this.checking = false;
  },
  initHTML: function() {
    this.html = '';

    this.html += '<div class="colorSubPalettePicker"  style="background-color: #111111; border: 1px solid #444444">';
    for(var i = 0; i < this.colorSubPaletteCount; i++) {

      this.html += '<div class="colorSubPalette" data-palette="' + i + '" style="">';
      this.html += '<div id="colorSubPalettePicker_' + i + '_0" style="position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; background-color: #ffee66"></div>';
      this.html += '<div id="colorSubPalettePicker_' + i + '_1" style="position: absolute; top: 2px; left: 20px; width: 16px; height: 16px; background-color: #66ff66"></div>';
      this.html += '<div id="colorSubPalettePicker_' + i + '_2" style="position: absolute; top: 20px; left: 2px; width: 16px; height: 16px; background-color: #ffee66"></div>';
      this.html += '<div id="colorSubPalettePicker_' + i + '_3" style="position: absolute; top: 20px; left: 20px; width: 16px; height: 16px; background-color: #66ff66"></div>';
      this.html += '<div style="position: absolute; top: 4px; left: 50px; color: #eeeeee">Palette ' + i + '</div>';
      this.html += '</div>';

    }
    this.html += '</div>';
  },

  init: function(editor) {
    this.editor = editor;

    this.subPalettes = [];
    this.setColorSubPaletteCount(4);

    this.initHTML();

  },

  initEvents: function() {
    var _this = this;

    $('.colorSubPalettePicker .colorSubPalette').on('click', function(event) {
      var index = parseInt($(this).attr('data-palette'));
      _this.closePicker();
      _this.selectPalette(index);
    });

  },

  setPickerColors: function() {
    var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();

    for(var i = 0; i < this.subPalettes.length; i++) {
      for(var j = 0; j < this.subPalettes[i].length; j++) {
        var color = this.subPalettes[i][j];
        
        $('#colorSubPalettePicker_' + i + '_' + j).css('background-color', '#' + colorPalette.getHexString(color));
      }
    }
  },

  showPicker: function(x, y, args) {

    if(this.uiComponent == null) {
      this.uiComponent = UI.create("UI.Popup", { "id": "colorSubPalettePickerPopup", "width": 300, "height": 300 });    
      this.htmlComponent = UI.create("UI.HTMLPanel", { "html": this.html });
      this.uiComponent.add(this.htmlComponent);
      this.initEvents();  
    }
    this.setPickerColors();

    var popupWidth = 180;
    var popupHeight = 166;
    this.uiComponent.setDimensions(popupWidth, popupHeight);

    UI.showPopup("colorSubPalettePickerPopup", x, y);
    this.visible = true; 

  },

  closePicker: function() {
    if(this.visible) {
      UI.hidePopup();
    }
    this.visible = false;
  },

  showMobilePicker: function(args) {
    console.log('show mobile picker');
    if(this.colorSubPalettePickerMobile == null) {
      this.colorSubPalettePickerMobile = new ColorSubPalettePickerMobile();
      this.colorSubPalettePickerMobile.init(this.editor);
    }

    this.colorSubPalettePickerMobile.show(args);

  },

  setColor: function(index, color) {
    
    var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();

    $('.colorSubPaletteColor' + index).css('background-color', '#' + colorPalette.getHexString(color));
    $('.colorSubPaletteColor' + index + 'Mobile').css('background-color', '#' + colorPalette.getHexString(color));

    //    $('.c64Multi1ColorDisplay').css('background-color', '#' + colorPalette.getHexString(color));

    if(index === 0) {
      // color 0 is the same for all palettes, and background color
      for(var i = 0; i < this.subPalettes.length; i++) {
        this.subPalettes[i][index] = color;
      }
//      this.editor.frames.setBackgroundColor(color);
      this.editor.setBackgroundColor(color, false);
      
    } else {
      this.subPalettes[this.currentColorSubPalette][index] = color;
    }

    this.editor.colorsUpdated();

    this.editor.colorPalettePanel.updateSubPaletteColors();

    if(this.colorSubPalettePickerMobile) {
      this.colorSubPalettePickerMobile.updateSubPaletteColors();
    }


//    this.editor.tileSetManager.tileSetUpdated();

  },

  getColor: function(index) {
    return this.subPalettes[this.currentColorSubPalette][index];
  },

  getPaletteColor: function(paletteIndex, colorIndex) {
    

    if(paletteIndex >= 4 || paletteIndex < 0 || paletteIndex === false) {
      paletteIndex = 0;
    }

//    console.error(paletteIndex);
    if(paletteIndex >= this.subPalettes.length || colorIndex >= this.subPalettes[paletteIndex].length) {
      return 0;
    }

    return this.subPalettes[paletteIndex][colorIndex];
  },

  getPaletteCount: function() {
    return this.subPalettes.length;
  },

  getPaletteColorCount: function() {
    return this.colorPerColorSubPalette;
  },

  selectPaletteColor: function(paletteColor) {
    this.currentColor = paletteColor;
    this.editor.tileEditor.tileEditorGrid.setColorIndex(paletteColor);
    this.editor.tools.drawTools.pixelDraw.color = paletteColor;

    this.editor.colorPalettePanel.highlightSubPaletteColor();

    if(this.colorSubPalettePickerMobile) {
      this.colorSubPalettePickerMobile.highlightSubPaletteColor();
    }
    this.editor.tileEditor.drawSelectedSubPaletteColor();

    if(this.editor.tileEditorMobile) {
      this.editor.tileEditorMobile.tileEditorMobileGrid.setColorIndex(paletteColor);
      this.editor.tileEditorMobile.drawSelectedSubPaletteColor();
    }


    this.editor.tools.drawTools.pixelDraw.drawSelectedSubPaletteColor();
  },

  getCurrentPalette: function() {
    return this.currentColorSubPalette;
  },

  getCurrentPaletteColor: function() {
    return this.currentColor;
  },

  selectPalette: function(paletteIndex, paletteColor) {
    var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();

    if(typeof paletteIndex != 'undefined') {
      this.currentColorSubPalette = paletteIndex;
    }

    if(typeof paletteColor != 'undefined') {
      this.currentColor = paletteColor;
      this.editor.colorPalettePanel.highlightSubPaletteColor();  
    }

    $('.colorSubPaletteSelectedPaletteName').html('Palette ' + this.currentColorSubPalette);

    for(var j = 0; j < 4; j++) {
      var color = this.subPalettes[this.currentColorSubPalette][j];
      $('.colorSubPaletteColor' + j).css('background-color', '#' + colorPalette.getHexString(color));
    }

    this.editor.currentTile.setColor(this.currentColorSubPalette, { force: true });

  }
}

var ColorSubPalettePickerMobile = function() {
  this.editor = null;

  this.colorPaletteDisplay =  null;
  this.colorType = 'cell';

  this.uiComponent = null;

  this.id = 'Choose';
}

ColorSubPalettePickerMobile.prototype = {
  on: function(eventName, f) {
    if(eventName == 'close') {
      this.closeHandler = f;
    }
  },

  init: function(editor, args) {
    this.editor = editor;

  },


  initEvents: function() {
    var _this = this;

    $('.colorPalettePanelSubPaletteColorMobile').on('click', function() {
      console.log('select colour');
      var subPalette = parseInt($(this).attr('data-subpalette'), 10);
      var subPaletteColor = parseInt($(this).attr('data-color'), 10);

      console.log(subPalette + ',' + subPaletteColor);
      _this.selectSubPaletteColor(subPalette, subPaletteColor);
    });

    this.colorPaletteDisplay.on('colorselected', function(event) {
      _this.colorSelected(event.colorIndex, event.color);
    });    
  },

  show: function(args) {
    var _this = this;

    this.callback = args.colorPickedCallback;
    if(this.uiComponent == null) {
      var width = 500;
      var height = 100;

      var screenWidth = UI.getScreenWidth();
      var screenHeight = UI.getScreenHeight();

      width = screenWidth - 30;
      height = screenHeight - 30;

      this.uiComponent = UI.create("UI.MobilePanel", { "id": "colorSubPalettePickerMobile" + this.id, "title": "Choose Palette", "width": width, "height": height });
      var html = '';


      html += '<h2 style="margin: 0 0 14px 0" id="">Color Palette</h2>';

      /*
      html += '<div style="margin-bottom: 14px">';
      html += '  <div style="display: inline-block; width: 64px; height: 60px; border: 3px solid #333333">';
      html += '    <div style="width: 64px; height: 30px;" id="colorPickerMobileCurrent' + this.id + '"></div>';
      html += '    <div style="width: 64px; height: 30px;" id="colorPickerMobilePreview' + this.id + '"></div>';
      html += '  </div>';
      html += '  <div style="display: inline-block; margin-left: 10px" id="colorPickerMobileInfo' + this.id + '"></div>';
      html += '</div>';
      */

      html += '<div style="text-align: center">';
      html += '<canvas id="colorSubPalettePickerMobileCanvas' + this.id + '"></canvas>';
      html += '</div>';


      var subpaletteCount = 4;
      html += '<div id="colorPalettePanelSubPalettesMobile">';

      for(var i = 0; i < subpaletteCount; i++) {
        html += '    <div class="colorPalettePanelSubPaletteMobile" data-subPalette="' + i + '">';
        html += '      <div class="colorPalettePanelSubPaletteHolderMobile">';
        html += '        <div class="colorPalettePanelSubPaletteLabelMobile">' + i + ':</div>';
        html += '        <div class="colorPalettePanelSubPaletteColorsMobile">';
        html += '          <div class="colorPalettePanelSubPaletteColorMobile" id="colorPalettePanelSubPalette' + i + '-Color0Mobile" data-subPalette="' + i + '" data-color="0"></div>';
        html += '          <div class="colorPalettePanelSubPaletteColorMobile" id="colorPalettePanelSubPalette' + i + '-Color1Mobile" data-subPalette="' + i + '" data-color="1"></div>';
        html += '          <div class="colorPalettePanelSubPaletteColorMobile" id="colorPalettePanelSubPalette' + i + '-Color2Mobile" data-subPalette="' + i + '" data-color="2"></div>';
        html += '          <div class="colorPalettePanelSubPaletteColorMobile" id="colorPalettePanelSubPalette' + i + '-Color3Mobile" data-subPalette="' + i + '" data-color="3"></div>';
        html += '        </div>';
        html += '      </div>';
        html += '    </div>';
      }
      html += '</div>';



      
      var htmlPanel = UI.create("UI.HTMLPanel", { "id": "colorSubPalettePickerMobileHTML" + this.id, "html": html });
      this.uiComponent.add(htmlPanel);


      this.uiComponent.on('close', function() {

      });

      this.colorPaletteDisplay = new ColorPaletteDisplay();
      this.colorPaletteDisplay.init(this.editor, { "canvasElementId": "colorSubPalettePickerMobileCanvas" + this.id, "canSelectMultiple": this.canSelectMultiple, "maxSelectableColors": 1, "canSelectWithRightMouseButton": false   });
      this.colorPaletteDisplay.draw();

      this.initEvents();

    }

    UI.showDialog("colorSubPalettePickerMobile" + this.id);

    var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();


    var colors = [];
    var colorCount = colorPalette.getColorCount();
    for(var i = 0; i < colorCount; i++) {
      colors.push(colorPalette.getHex(i));
    }

    var colorMap = colorPalette.getCurrentColorMap();
    var colorsAcross = 8;
    var colorsDown = 8;
    if(colorMap.length > 0 && colorMap[0].length > 0) {
      colorsAcross = colorMap[0].length;
      colorsDown = colorMap.length;
    }
    var colorWidth = 34;
    var colorHeight = 34;
    var colorSpacing = 4;
    if(colorsAcross > 12 || colorsDown > 12) {
      colorWidth = 20;
      colorHeight = 20;
    }

    if(typeof args.colors != 'undefined') {
      this.colorPaletteDisplay.setSelectedColors(args.colors);
    }
    this.colorPaletteDisplay.setColorSize(colorWidth, colorHeight, colorSpacing);
    this.colorPaletteDisplay.setColors(colors, { colorMap: colorPalette.getCurrentColorMap() });

    var screenWidth = UI.getScreenWidth();
    var screenHeight = UI.getScreenHeight();

    var maxHeight = screenHeight - 111 - 120;

    if(colorsAcross > 6 && screenWidth < 800) {
      this.colorPaletteDisplay.fitToWidth(screenWidth - 24);
    }

    if(this.colorPaletteDisplay.getHeight() > maxHeight) {
      console.log('setting max height');
      colorWidth = 14;
      colorHeight = 14;
      colorSpacing = 3;
      this.colorPaletteDisplay.setColorSize(colorWidth, colorHeight, colorSpacing);
    }




    this.colorPaletteDisplay.draw();

    if(typeof args.currentColor != 'undefined') {
      var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
      if(args.currentColor === false) {
        return;
      }

      var colorHex = colorPalette.getHexString(args.currentColor);
      $('#colorPickerMobileCurrent' + this.id).css('background-color', '#' + colorHex);

    }

    this.updateSubPaletteColors();

  },  

  // colorType is fg or bg
  colorSelected: function(colorType, colorIndex) {
    var colorSubPalettes = this.editor.colorPaletteManager.colorSubPalettes;
    var currentSubPalette = colorSubPalettes.getCurrentPalette();

    var currentSubPaletteColor = colorSubPalettes.getCurrentPaletteColor();
    colorSubPalettes.setColor(currentSubPaletteColor, colorIndex);
    this.editor.currentTile.setColor(currentSubPalette, { force: true});
  },


  selectSubPaletteColor: function(subPalette, subPaletteColor) {

    this.editor.colorPaletteManager.colorSubPalettes.selectPalette(subPalette, subPaletteColor);
    this.editor.colorPaletteManager.colorSubPalettes.selectPaletteColor(subPaletteColor);    
  },

  highlightSubPaletteColor: function() {
    $('.colorPalettePanelSubPaletteColorMobile').removeClass('colorPalettePanelSubPaletteColorMobile-selected');
    var palette = this.editor.colorPaletteManager.colorSubPalettes.getCurrentPalette();
    var paletteColor = this.editor.colorPaletteManager.colorSubPalettes.getCurrentPaletteColor();
    $('#colorPalettePanelSubPalette' + palette + '-Color' + paletteColor + 'Mobile').addClass('colorPalettePanelSubPaletteColorMobile-selected');
    this.updateSubPaletteColors();

    var colorSubPalettes = this.editor.colorPaletteManager.colorSubPalettes;

    console.log('highlight sub palette colours!!!!');
    console.log('palette = ' + palette + ',' + paletteColor);
    var colorIndex = colorSubPalettes.getPaletteColor(palette, paletteColor);
    if(colorIndex !== false) {
      this.colorPaletteDisplay.setSelectedColors([colorIndex]);      
      this.colorPaletteDisplay.draw();
    }
    console.log('colorIndex = ' + colorIndex);
  },

  updateSubPaletteColors: function() {
    var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
    var colorSubPalettes = this.editor.colorPaletteManager.colorSubPalettes;
    var subPaletteCount = colorSubPalettes.getPaletteCount();
    var subPaletteColorCount =  colorSubPalettes.getPaletteColorCount();

    for(var i = 0; i < subPaletteCount; i++) {
      for(var j = 0; j < subPaletteColorCount; j++) {
        var colorIndex = colorSubPalettes.getPaletteColor(i, j);
        var color = colorPalette.getHexString(colorIndex);
        $('#colorPalettePanelSubPalette' + i + '-Color' + j + 'Mobile').css('background-color', '#' + color);
        $('#colorPalettePanelSubPalette' + i + '-Color' + j + 'Mobile').css('border-color', '#' + color);
      }
    }

    $('.colorPalettePanelSubPaletteColorMobile-selected').css('border-color', '#888888');


  },


}


var ColorPaletteSave = function() {
  this.editor = null;
  this.colorPaletteDisplay = null;
  this.colorPalette = null;

  this.sortOrder = 'default';
  this.cellWidth = 8;
  this.cellHeight = 8;

}

ColorPaletteSave.prototype = {
  init: function(editor) {
    this.editor = editor;
  },

  show: function(args) {

    var _this = this;

    if(this.uiComponent == null) {
      this.uiComponent = UI.create("UI.Dialog", { "id": "saveColorPaletteDialog", "title": "Save Colour Palette", "width": 640 });

      this.htmlComponent = UI.create("UI.HTMLPanel");
      this.uiComponent.add(this.htmlComponent);
      this.htmlComponent.load('html/textMode/colorPaletteSave.html', function() {
        _this.initContent(args);
        _this.initEvents();
      });

      this.okButton = UI.create('UI.Button', { "text": "OK", "color": "primary" });
      this.uiComponent.addButton(this.okButton);
      this.okButton.on('click', function(event) {
        _this.save();
        UI.closeDialog();
      });

      this.closeButton = UI.create('UI.Button', { "text": "Cancel", "color": "secondary" });
      this.uiComponent.addButton(this.closeButton);
      this.closeButton.on('click', function(event) {
        UI.closeDialog();
      });
    } else {
      this.initContent(args);
    }

    UI.showDialog("saveColorPaletteDialog");
  },

  initContent: function(args) {
    if(this.colorPaletteDisplay == null) {
      this.colorPaletteDisplay = new ColorPaletteDisplay();
      this.colorPaletteDisplay.init(this.editor, { canvasElementId: 'saveColorPaletteCanvas' });
    }

    if(typeof args != 'undefined' && typeof args.colorPalette != 'undefined') {
      this.colorPalette = args.colorPalette;
    } else {
      this.colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
    }
    var colorPalette = this.colorPalette;
    this.colorsAcross = colorPalette.getColorsAcross();
    var colors = [];
    var colorCount = colorPalette.getColorCount();
    for(var i = 0; i < colorCount; i++) {
      colors.push(colorPalette.getHex(i));
    }

    this.sortOrder = $('#saveColorPaletteSortOrder').val();
    this.saveFormat = $('#saveColorPaletteFormat').val();

    $('#saveColorPaletteColorsAcross').val(this.colorsAcross);

    this.colorPaletteDisplay.setColors(colors, { colorsAcross: this.colorsAcross });

//    this.colorPaletteDisplay.setColorMap(colorPalette.getCurrentColorMap());

    this.setColorsAcross(this.colorsAcross)
    this.setSortOrder(this.sortOrder);
    this.colorPaletteDisplay.fitToWidth(240);

    this.colorPaletteDisplay.draw();

    this.setSaveFormat(this.saveFormat);


  },

  setCellWidth: function(cellWidth) {
    this.cellWidth = cellWidth;
    this.setSortOrder(this.sortOrder);

  },

  setCellHeight: function(cellHeight) {
    this.cellHeight = cellHeight;
    this.setSortOrder(this.sortOrder);

  },

  setColorsAcross: function(colorsAcross) {
    this.colorsAcross = colorsAcross;
    this.colorPaletteDisplay.setColorsAcross(colorsAcross);
    this.setSortOrder(this.sortOrder);
  },

  setSortOrder: function(sortOrder) {
    //var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();

    console.log('get color map');
    this.sortOrder = sortOrder;
    var colorMap = this.colorPalette.getColorMap(this.sortOrder, this.colorsAcross);
    this.colorPaletteDisplay.setColorMap(colorMap);
    this.colorPaletteDisplay.setColorSize(this.cellWidth, this.cellHeight, 0);

    this.colorPaletteDisplay.draw();
  },

  initEvents: function() {
    var _this = this;
    $('#saveColorPaletteSortOrder').on('change', function(event) {
      var sortOrder = $(this).val();
      _this.setSortOrder(sortOrder);
    });

    $('#saveColorPaletteFormat').on('change', function(event) {
      var saveFormat = $(this).val();
      _this.setSaveFormat(saveFormat);
    });

    $('#saveColorPaletteColorsAcross').on('keyup', function(event) {
      var colorsAcross = parseInt($(this).val(), 10);
      if(isNaN(colorsAcross)) {
        return;
      }
      _this.setColorsAcross(colorsAcross);
    });

    $('#saveColorPaletteColorsAcross').on('change', function(event) {
      var colorsAcross = parseInt($(this).val(), 10);
      if(isNaN(colorsAcross)) {
        return;
      }
      _this.setColorsAcross(colorsAcross);
    });


    $('#saveColorPaletteCellWidth').on('keyup', function(event) {
      var cellWidth = parseInt($(this).val(), 10);
      if(isNaN(cellWidth)) {
        return;
      }
      _this.setCellWidth(cellWidth);

    });

    $('#saveColorPaletteCellWidth').on('change', function(event) {
      var cellWidth = parseInt($(this).val(), 10);
      if(isNaN(cellWidth)) {
        return;
      }
      _this.setCellWidth(cellWidth);

    });

    $('#saveColorPaletteCellHeight').on('keyup', function(event) {
      var cellHeight = parseInt($(this).val(), 10);
      if(isNaN(cellHeight)) {
        return;
      }
      _this.setCellHeight(cellHeight);

    });

    $('#saveColorPaletteCellHeight').on('change', function(event) {
      var cellHeight = parseInt($(this).val(), 10);
      if(isNaN(cellHeight)) {
        return;
      }
      _this.setCellHeight(cellHeight);

    });


  },


  setSaveFormat: function(saveFormat) {
    this.saveFormat = saveFormat;
    if(this.saveFormat == 'json') {
      $('#saveColorPaletteSortOrderRow').hide();
    } else {
      $('#saveColorPaletteSortOrderRow').show();
    }

    if(this.saveFormat == 'png') {
      $('#saveColorPaletteColorsAcrossRow').show();
      $('#saveColorPaletteCellWidthRow').show();
      $('#saveColorPaletteCellHeightRow').show();

      //var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
      var colorCount = this.colorPalette.getColorCount();
      $('#saveColorPaletteColorsAcross').attr('max', colorCount);


      this.cellWidth = parseInt($('#saveColorPaletteCellWidth').val(), 10);
      this.cellHeight = parseInt($('#saveColorPaletteCellHeight').val(), 10);
      this.setColorsAcross(colorsAcross);

    } else {
      $('#saveColorPaletteColorsAcrossRow').hide();
      $('#saveColorPaletteCellWidthRow').hide();
      $('#saveColorPaletteCellHeightRow').hide();
      //var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
      var colorsAcross = this.colorPalette.getColorsAcross();
      this.cellWidth = 16;
      this.cellHeight = 16;
      this.setColorsAcross(colorsAcross);


    }
  },

  save: function() {
    var filename = $('#saveColorPaletteAs').val();
    var format = this.saveFormat;//$('#saveColorPaletteFormat').val();

    //var colorPalette = this.editor.colorPaletteManager.getCurrentColorPalette();
    var colorPalette = this.colorPalette;
    var map = this.colorPaletteDisplay.getColorMap();

    switch(format) {
      
      case 'json':
        colorPalette.saveAsJSON(filename);
      break;

      case 'png':
        colorPalette.saveAsPNG(filename, map, this.cellWidth, this.cellHeight);
      break;

      case 'aco':
        colorPalette.saveAsAco(filename, map);
      break;
      case 'ase':
        colorPalette.saveAsAse(filename, map);
      break;

      case 'gpl':
        colorPalette.saveAsGPL(filename, map);
      break;
      case 'txt':
        colorPalette.saveAsTxt(filename, map);
      break;
      case 'hex':
        colorPalette.saveAsHex(filename, map);
      break;
    }

  },

  saveAsGPL: function(filename) {
    var data = '';

  },

  saveAsTxt: function(filename) {

  },

  saveAsHex: function(filename) {

  }
}

var ColorPaletteLoad = function() {
  this.importImage = null;
  this.paletteCanvas = null;

  this.colorPaletteDisplay = null;

  this.colorsAcross = 8;
  this.importColors = 16;

  this.colorMap = [];

  this.editor = null;

  this.loadMap = false;
  this.ase = null;
  this.aco = null;

  this.visible = false;

  this.callback = false;
  this.dialogReadyCallback = false;

  this.parentComponent = null;

  this.colorPaletteLoadFromURL = null;

  this.name = '';
}

ColorPaletteLoad.prototype = {
  init: function(editor, parentComponent) {
    this.editor = editor;

    if(typeof parentComponent != 'undefined') {
      this.parentComponent = parentComponent;
    }
  },

  show: function(args) {
    if(typeof args != 'undefined') {
      if(typeof args.dialogReadyCallback != 'undefined') {
        this.dialogReadyCallback = args.dialogReadyCallback;
      }
    }

    var _this = this;
    if(this.uiComponent == null) {

      if(this.parentComponent == null) {
        this.uiComponent = UI.create("UI.Dialog", 
          { "id": "colourPaletteLoadDialog", "title": "Colour Palette Load", "width": 384 });
      } else {
        this.uiComponent = this.parentComponent;
      }

      this.colorPaletteLoadPanel = UI.create("UI.HTMLPanel");
      this.uiComponent.add(this.colorPaletteLoadPanel);
      this.colorPaletteLoadPanel.load('html/textMode/colorPaletteLoad.html', function() {
        _this.htmlComponentLoaded();
        _this.initContent();
        _this.initEvents();

        if(_this.dialogReadyCallback != false) {
          _this.dialogReadyCallback();
        }
      });

      if(!this.parentComponent) {
        this.okButton = UI.create('UI.Button', { "text": "OK", "color": "primary" });
        this.uiComponent.addButton(this.okButton);
        this.okButton.on('click', function(event) {
          _this.setPalette();
          UI.closeDialog();
        });

        this.closeButton = UI.create('UI.Button', { "text": "Cancel", "color": "secondary" });
        this.uiComponent.addButton(this.closeButton);
        this.closeButton.on('click', function(event) {
          UI.closeDialog();
        });

        this.uiComponent.on('close', function() {
          _this.visible = false;
        });
      }


      if(this.parentComponent == null) {
        UI.showDialog("colourPaletteLoadDialog");
      }
      this.visible = true;
  
    } else {
      this.initContent();

      if(this.parentComponent == null) {
        UI.showDialog("colourPaletteLoadDialog");
      }

      this.visible = true;
  
      if(_this.dialogReadyCallback != false) {
        _this.dialogReadyCallback();
      }
    }

  },

  initContent: function() {
    if(this.colorPaletteDisplay == null) {
      this.colorPaletteDisplay = new ColorPaletteDisplay();
      this.colorPaletteDisplay.init(this.editor, { canvasElementId: 'colorPaletteLoadPreview' });
    }
    this.sortMethod = $('#colorPaletteLoadColorsSortMethod').val();
  },

  htmlComponentLoaded: function() {
    this.paletteCanvas = document.getElementById('colorPaletteLoadPreview');
  },

  initEvents: function() {
    var _this = this;

    $('#colorPaletteLoadURLButton').on('click', function(event) {
      var url = $('#colorPaletteLoadURL').val();
      _this.loadPaletteFromURL(url);
    });


    $('#colorPaletteFileChoose').on('click', function() {
      $('#colourPaletteFile').click();
    });

    $('#colorPaletteLoadLospec').on('click', function() {
      _this.loadLospecPalette();
    });


    $('#colorPaletteLoadColorsAcross').on('keyup', function(event) {
      var colorsAcross = parseInt($('#colorPaletteLoadColorsAcross').val(), 10);
      if(!isNaN(colorsAcross)) {
        _this.setColorsAcross(colorsAcross);
      }
    });

    $('#colorPaletteLoadColorsAcross').on('change', function(event) {
      var colorsAcross = parseInt($('#colorPaletteLoadColorsAcross').val(), 10);
      if(!isNaN(colorsAcross)) {
        _this.setColorsAcross(colorsAcross);
      }
    });

/*
    $('#colorPaletteLoadColorsSortMethod').on('change', function(event) {
      _this.sortMethod = $('#colorPaletteLoadColorsSortMethod').val();
      _this.sortColors();
    });
*/
    $('#colorPaletteLoadUserColorCount').on('change', function(event) {
      var colorCount = parseInt($(this).val(), 10);
      if(!isNaN(colorCount)) {
        _this.setColorCount(colorCount);
      }

    });

    $('#colorPaletteLoadUserColorCount').on('keyup', function(event) {
      var colorCount = parseInt($(this).val(), 10);
      if(!isNaN(colorCount)) {
        _this.setColorCount(colorCount);
      }
    });

    document.getElementById('colourPaletteFile').addEventListener("change", function(e) {
      var file = document.getElementById('colourPaletteFile').files[0];
      _this.setImportFile(file);
    });

  },

  loadLospecPalette: function() {
    if(this.colorPaletteLoadFromURL == null) {
      this.colorPaletteLoadFromURL = new ColorPaletteLoadFromURL();
    }

//    console.log('load palette from url' + url);
    var _this = this;
    this.colorPaletteLoadFromURL.show({
      callback: function(response) {
        _this.createPaletteFromLoSpec(response.response);
      }
    });

  },

  loadPaletteFromURL: function(url) {
    if(this.colorPaletteLoadFromURL == null) {
      this.colorPaletteLoadFromURL = new ColorPaletteLoadFromURL();
    }

    console.log('load palette from url' + url);
    var _this = this;
    this.colorPaletteLoadFromURL.loadURL({
      url: url,
      callback: function(response) {
        _this.createPaletteFromLoSpec(response.response);
      }
    });

  },

  createPaletteFromLoSpec: function(data) {
    this.name = data.name;
    var author = data.author;
    var colors = [];
    
    for(var i = 0; i < data.colors.length; i++) {
      var color = parseInt(data.colors[i], 16);
      if(!isNaN(color)) {
        colors.push(color);
      }
    }
    
    if(colors.length > 0) {
      this.colors = colors;
      this.setAlpha();

      if(this.callback) {
        this.callback(this.colors);
      }

      if(this.visible) {
        this.setColorCount(colors.length);

        this.autoColorsAcross();
        this.updatePreviewPalette();
      }
    }
  },


  setPalette: function(args) {
    var callback = false;
    
    if(typeof args != 'undefined') {
      callback = args.callback;
    }

    var colorPaletteManager = this.editor.colorPaletteManager;

    var colorPaletteCreated = false;
    var colorPalette = colorPaletteManager.getCurrentColorPalette();

    if(colorPalette == null || (typeof args.createColorPalette != 'undefined' && args.createColorPalette)) {
      colorPaletteCreated = true;
      colorPalette = new ColorPalette();
    }

    var colorsDown = Math.ceil(this.colors.length / this.colorsAcross);
    colorPalette.setColors(this.colors, this.colorsAcross, colorsDown);

    if(colorPaletteCreated) {
      if(callback) {
        callback({
          colorPaletteCreated: true,
          colorPalette: colorPalette,          
          presetId: false,
          description: { "name": this.name }
//          description: { "name": tileSet.label },
//          mode: this.importArgs.mode

        });
      }
    } else {
      colorPalette.clearPaletteMaps();
      if(this.loadMap) {
        var colorMapId = colorPalette.setColorPaletteMap('Default Layout', this.colorMap);
        colorPalette.setCurrentColorMap(colorMapId);
      }
      colorPalette.paletteChanged();

      if(g_app.getMode() == 'color palette') {
        g_app.colorPaletteEditor.draw();
      }
    }

  },

  setColorsAcross: function(colorsAcross) {
    this.colorsAcross = colorsAcross;
    this.updatePreviewPalette();
  },

  autoColorsAcross: function() {
    this.colorsAcross = 16;
    if(this.colors.length <= 8) {
      this.colorsAcross = 4;
    } else if(this.colors.length <= 16) {
      this.colorsAcross = 16;
    }
    $('#colorPaletteLoadColorsAcross').val(this.colorsAcross);
  },

  createColorMap: function() {
    var colorsAcross = this.colorsAcross;
    var colorCount = this.importColors;
    var colorsDown = Math.ceil(this.importColors / colorsAcross);
    if(colorCount > this.colors.length) {
      colorCount = this.colors.length;
    }

    var index = 0;
    this.colorMap = [];
    for(var y = 0; y < colorsDown; y++) {
      this.colorMap[y] = [];
      for(var x = 0; x < colorsAcross; x++) {
        if(index < colorCount) {
          this.colorMap[y][x] = index;
        } else {
          this.colorMap[y][x] = this.editor.colorPaletteManager.noColor;
        }
        index++;
      }
    }
  },


  setImportFile: function(file, callback) {
    if(typeof file == 'undefined') {
      return;
    }

    if(typeof callback != 'undefined') {
      this.callback = callback;
    }

    var filename = file.name;
    this.name = filename;
    $('#colorPaletteFileChooseName').html(filename);
    var extension = filename.split('.').pop().toLowerCase();
    this.loadMap = false;

    if(extension == 'png' || extension == 'jpg' || extension == 'gif') {
      this.loadPNG(file);
    }

    if(extension == 'ase') {
      this.loadASE(file);
    }

    if(extension == 'aco') {
      this.loadACO(file);
    }

    if(extension == 'txt' || extension == 'hex') {
      this.loadTXT(file);
    }


    if(extension == 'vpl') {
      this.loadVPL(file);
    }

    if(extension == 'gpl') {
      this.loadGPL(file);
    }

    if(extension == 'act') {
      this.loadBinary(file);
    }

    if(extension == 'json') {
      this.loadJSON(file);
    }

  },

  loadPNG: function(file) {
    if(!this.importImage) {
      this.importImage = new Image();
    }

    var _this = this;
    this.importImage.onload = function() {
      _this.createPaletteFromImage();      
    }

    var url = window.URL || window.webkitURL;
    var src = url.createObjectURL(file);
    this.importImage.src = src;

  },

  loadTXT: function(file) {
    var _this = this;

    var fileReader = new FileReader();
    fileReader.onload = function(e) {
      var colorText = e.target.result;
      _this.createPaletteFromPaintTxt(colorText);

    }
    fileReader.readAsText(file);
  },

  loadVPL: function(file) {
    var _this = this;

    var fileReader = new FileReader();
    fileReader.onload = function(e) {
      var colorText = e.target.result;
      _this.createPaletteFromVPL(colorText);

    }
    fileReader.readAsText(file);

  },

  loadGPL: function(file) {
    var _this = this;

    var fileReader = new FileReader();
    fileReader.onload = function(e) {
      var colorText = e.target.result;
      _this.createPaletteFromGPL(colorText);

    }
    fileReader.readAsText(file);
  },

  loadACO: function(file) {
    var _this = this;

    var fileReader = new FileReader();
    fileReader.onload = function(e) {
      _this.createPaletteFromACO(new Uint8Array(e.target.result));
    }
  //  fileReader.readAsText(file);
    fileReader.readAsArrayBuffer(file);


  },
  loadASE: function(file) {
    if(this.ase == null) {
      this.ase = new ASE();
    }

    var _this = this;

    var fileReader = new FileReader();
    fileReader.onload = function(e) {
      _this.createPaletteFromASE(new Uint8Array(e.target.result));
    }
  //  fileReader.readAsText(file);
    fileReader.readAsArrayBuffer(file);
  },

  loadBinary: function(file) {
    var _this = this;

    var fileReader = new FileReader();
    fileReader.onload = function(e) {
      _this.createPaletteFromBinary(new Uint8Array(e.target.result));
    }
    fileReader.readAsArrayBuffer(file);    
  },


  errorMessage: function(message) {
    $('#colorPaletteLoadError').html(message);
    if(message != '') {
      $('#colorPaletteLoadError').show();
    } else {
      $('#colorPaletteLoadError').hide();
    }

  },


  loadJSON: function(file) {
    var _this = this;

    var fileReader = new FileReader();
    fileReader.onload = function(e) {
      var colorText = e.target.result;
      _this.createPaletteFromJSON(colorText);

    }
    fileReader.readAsText(file);
  },

  setAlpha: function() {
    for(var i = 0; i < this.colors.length; i++) {
      var alpha = (0xff) >>> 0;
      var color = (this.colors[i]) >>> 0;
      this.colors[i] = ((alpha << 24) | color) >>> 0;
    }
  },

  createPaletteFromJSON: function(jsonString) {
    var colorJson = {};
    try {
      colorJson = $.parseJSON(jsonString);
      if(typeof colorJson.colorPalette != 'undefined') {
        colorJson = colorJson.colorPalette;
      }

      var colors = [];
      if(typeof colorJson.data != 'undefined') {
        for(var i = 0; i < colorJson.data.length; i++) {
          colors.push(colorJson.data[i]);
        }
      }

      if(typeof colorJson.across != 'undefined') {
        this.colorsAcross = colorJson.across;
        $('#colorPaletteLoadColorsAcross').val(this.colorsAcross);

      } else {
        this.autoColorsAcross();
      }


      if(typeof colorJson.maps != 'undefined' && colorJson.maps.length > 0) {
        this.loadMap = true;
        this.colorMap = [];
        var srcMap = colorJson.maps[0];


        for(var y = 0; y < srcMap.map.length; y++) {
          this.colorMap[y] = [];
          for(var x = 0; x < srcMap.map[y].length; x++) {
            this.colorMap[y][x] = srcMap.map[y][x];
          }
        }
      } else {
        this.loadMap = false;
      }

      if(colors.length > 0) {
        this.colors = colors;
        this.setColorCount(colors.length);

        if(this.callback) {
          this.callback(this.colors);
        }

        
        if(this.visible) {
          this.updatePreviewPalette();
        }
        this.errorMessage('');
      } else {
        this.errorMessage('No colours found');

      }
    } catch(err) {
      this.errorMessage('Sorry, unable to interpret file');
    }

  },

  createPaletteFromASE: function(data) {
    if(this.ase == null) {
      this.ase = new ASE();
    }

    var colors = this.ase.readPalette(data);
    if(colors === false) {
      //console.log('no colours');
      this.errorMessage('No colours found');
      return;
    }

    this.colors = colors;
    this.setAlpha();

    if(this.callback) {
      this.callback(this.colors);
    }


    if(this.visible) {
      this.setColorCount(colors.length);
      this.autoColorsAcross();
      this.updatePreviewPalette();
      this.errorMessage('');
    }
  },

  createPaletteFromACO: function(data) {
    if(this.aco == null) {
      this.aco = new ACO();
    }
    var colors = this.aco.readPalette(data);
    if(colors === false) {
//      console.log('no colours');
      this.errorMessage('No colours found');
      return;
    }

    this.colors = colors;
    this.setAlpha();

    if(this.callback) {
      this.callback(this.colors);
    }


    if(this.visible) {
      this.setColorCount(colors.length);

      this.autoColorsAcross();    
      this.updatePreviewPalette();
      this.errorMessage('');
    }

  },
  createPaletteFromImage: function() {
    var colorPaletteManager = null;
    if(this.editor) {
      colorPaletteManager = this.editor.colorPaletteManager;
    } else if(g_app && g_app.textModeEditor) {
      colorPaletteManager = g_app.textModeEditor.colorPaletteManager;
    }

    if(!colorPaletteManager) {
      console.log('couldnt find color palette manager');
      return;
    }
 
    var colors = colorPaletteManager.colorPaletteFromPaletteImg(this.importImage);

    this.colors = colors.colors;
    this.setAlpha();

    if(this.callback) {
      this.callback(this.colors);
    }

    if(this.visible) {
      if(colors.map !== false) {
        this.loadMap = true;
        this.colorMap = colors.map;
      } else {
        this.loadMap = false;
      }

      this.setColorCount(this.colors.length);

      this.colorsAcross = colors.colorsAcross;
      this.updatePreviewPalette();
    }
  },

  createPaletteFromVPL: function(data) {
    var colors = [];
    data = data.replace("\r", "");
    var lines = data.split("\n");
    for(var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if(line.length > 0) {
        if(line[0] == '#') {
          // its a comment
        } else {
          parts = line.split(' ');
          if(parts.length >= 3) {
            var red = parseInt(parts[0], 16);
            var green = parseInt(parts[1], 16);
            var blue = parseInt(parts[2], 16);
            if(!isNaN(red) && !isNaN(green) && !isNaN(blue)) {
              var rgb = (red << 16) + (green << 8) + (blue);
              colors.push(rgb);
            }
          }

          /*
          if(line.length == 8) {
            // its ARGB
            var rgb = line.substring(2);
            var color = parseInt(rgb, 16);
            if(!isNaN(color)) {
              colors.push(color);
            }
          } else if(line.length == 6) {
            // its RGB
            var color = parseInt(line, 16);
            if(!isNaN(color)) {
              colors.push(color);
            }
          }
          */
        }
      }
    }
    if(colors.length > 0) {
      this.colors = colors;
      this.setAlpha();

      if(this.callback) {
        this.callback(this.colors);
      }
      
      if(this.visible) {
        this.setColorCount(colors.length);
        if(colors.length == 16) {

          this.colorsAcross = 8;
          $('#colorPaletteLoadColorsAcross').val(this.colorsAcross);

        } else {
          this.autoColorsAcross();
        }
        this.updatePreviewPalette();
      }
    }

  },

  createPaletteFromPaintTxt: function(data) {
    var colors = [];
    data = data.replace("\r", "");
    var lines = data.split("\n");
    for(var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if(line.length > 0) {
        if(line[0] == ';') {
          // its a comment
        } else {
          if(line.length == 8) {
            // its ARGB
            var rgb = line.substring(2);
            var color = parseInt(rgb, 16);
            if(!isNaN(color)) {
              colors.push(color);
            }
          } else if(line.length == 6) {
            // its RGB
            var color = parseInt(line, 16);
            if(!isNaN(color)) {
              colors.push(color);
            }
          }
        }
      }
    }
    if(colors.length > 0) {
      this.colors = colors;
      this.setAlpha();

      if(this.callback) {
        this.callback(this.colors);
      }

      if(this.visible) {
        this.setColorCount(colors.length);

        this.autoColorsAcross();
        this.updatePreviewPalette();
      }
    }
  },

/*
There is no version number written in the file. The file is 768 or 772 bytes long and contains 256 RGB colors. The first color in the table is index zero. There are three bytes per color in the order red, green, blue. If the file is 772 bytes long there are 4 additional bytes remaining. Two bytes for the number of colors to use. Two bytes for the color index with the transparency color to use. If loaded into the Colors palette, the colors will be installed in the color swatch list as RGB colors.
*/
  createPaletteFromBinary: function(data) {
    var colors = [];
    var colorLength = 3;
    for(var i = 0; i < data.length; i += colorLength) {
      var r = data[i];
      var g = data[i + 1];
      var b = data[i + 2];
      if(!isNaN(r) && !isNaN(g) && !isNaN(b)) {
        var color = (r << 16) + (g << 8) + b;
        colors.push(color);
      }
    }

    if(colors.length > 0) {
      this.colors = colors;
      this.setAlpha();

      if(this.callback) {
        this.callback(this.colors);
      }

      if(this.visible) {
        this.setColorCount(colors.length);

        this.autoColorsAcross();
        this.updatePreviewPalette();
      }
    }

  },

  createPaletteFromGPL: function(data) {
    var colors = [];
    data = data.trim().replace("\r", "");
    var lines = data.split("\n");
    // should be magic at the start
    if(lines.length == 0) {
      return;
    }

    if(lines[0] != 'GIMP Palette') {
      //unknown format
      //console.log('unknown palette format: ' + lines[0]);
      this.errorMessage('Unknown palette format: ' + lines[0]);
      return;
    }

    for(var i = 1; i < lines.length; i++) {
      var line = lines[i].trim();
      if(line[0] == '#') {
        // is a comment
      } else {
        var parts = line.split(/[\s,\t\n]+/);
        if(parts.length >= 3) {
          var r = parseInt(parts[0]);
          var g = parseInt(parts[1]);
          var b = parseInt(parts[2]);
          
          if(!isNaN(r) && !isNaN(g) && !isNaN(b)) {
            var color = (r << 16) + (g << 8) + b;
            colors.push(color);
          }
        }
      }
    }

    if(colors.length > 0) {
      this.colors = colors;
      this.setAlpha();

      if(this.callback) {
        this.callback(this.colors);
      }


      if(this.visible) {
        this.autoColorsAcross();
        this.setColorCount(colors.length);

        this.updatePreviewPalette();
      }
    }


  },

  getColors: function() {
    return this.colors;
  },

  setColorCount: function(colorCount) {
    if(colorCount > 256) {
      colorCount = 256;
    }
    this.importColors = colorCount;
    $('#colorPaletteLoadUserColorCount').val(colorCount);

    this.updatePreviewPalette();
  },


  updatePreviewPalette: function() {
    if(!this.loadMap) {
      this.createColorMap();
    }

    $('#colorPaletteLoadColorsAcross').val(this.colorsAcross);
    this.colorPaletteDisplay.setColors(this.colors, { colorCount: this.importColors, colorMap: this.colorMap });
    $('#colorPaletteLoadSettings').show();
    $('#colorPaletteLoadColorCount').html(this.colors.length);    
  }

}

var ColorPaletteLoadFromURL = function() {
  this.uiComponent = null;
  this.visible = false;
  this.callback = false;
}

ColorPaletteLoadFromURL.prototype = {
  init: function() {

  },

  show: function(args) {
    this.callback = args.callback;

    if(this.uiComponent == null) {
      var _this = this;
      this.uiComponent = UI.create("UI.Dialog", 
      { "id": "colorPaletteLoadURLDialog", "title": "Load Lospec Palette", "width": 384, "height": 170 });

      var html = '<div style="padding: 10px">';
      html += '<div style="margin-bottom: 10px">Enter the URL of a <a href="https://lospec.com/palette-list" target="_blank">Lospec palette</a></div>';
      html += '<div style="margin: 6px 0" id="colorPaletteLoadStatus">&nbsp;</div>';
      html += '<input type="text" style="width: 320px" id="colorPaletteLoadURL" placeholder="https://lospec.com/palette-list/palette-slug">';
      html += '</div>';

      var htmlPanel = UI.create("UI.HTMLPanel", { "html": html });
      this.uiComponent.add(htmlPanel);

      this.okButton = UI.create('UI.Button', { "text": "OK", "color": "primary" });
      this.uiComponent.addButton(this.okButton);
      this.okButton.on('click', function(event) {
        _this.submit();
      });

      this.closeButton = UI.create('UI.Button', { "text": "Cancel", "color": "secondary" });
      this.uiComponent.addButton(this.closeButton);
      this.closeButton.on('click', function(event) {
        UI.closeDialog();
      });

      this.uiComponent.on('close', function() {
        _this.visible = false;
      });

      this.visible = true;
      UI.showDialog("colorPaletteLoadURLDialog");
      $('#colorPaletteLoadStatus').html('&nbsp;');
      this.initEvents();
      $('#colorPaletteLoadURL').focus();
    } else {
      this.visible = true;
      $('#colorPaletteLoadStatus').html('&nbsp;');
      UI.showDialog("colorPaletteLoadURLDialog");
      $('#colorPaletteLoadURL').focus();
    }

  },

  initEvents: function() {
    var _this = this;
    $('#colorPaletteLoadURL').on('keypress', function(event) {
      if(event.keyCode == 13) {
        _this.submit();
      }
    });
  },

  submit: function() {
    var _this = this;
    var url = $('#colorPaletteLoadURL').val();

    $('#colorPaletteLoadStatus').html('loading...');
    this.loadURL({
      url: url,
      callback: function(response) {
        if(response.success == false) {
          $('#colorPaletteLoadStatus').html('<div style="color: red; display: inline-block">Error</div> unable to load url');
        } else {
          $('#colorPaletteLoadStatus').html('&nbsp;');
          _this.callback(response);
          UI.closeDialog();
        }
      } 
    });
  },
  loadURL: function(args) {
    var url = args.url;
    var callback = args.callback;
    var slug = url;

    var parts = url.split('/');
    if(parts.length > 0) {
      var next = false;
      for(var i = 0; i < parts.length; i++) {
        if(next && parts[i].trim() != '') {
          slug = parts[i];
        }
        if(parts[i].toLowerCase() == 'palette-list') {
          next = true;
        }
      }
    }
    console.log(parts);

    console.log('slug == ' + slug);

    var pos = slug.indexOf('.csv');
    if(pos !== -1) {
      slug = slug.substring(0, pos);
    }

    if(slug.indexOf('.json') == -1) {
      slug += '.json';
    }

    url = "https://lospec.com/palette-list/" + slug;

    console.log('slug = ' + slug);
    console.log('url = ' + url);

    try {
      $.get({
        url: url,
        error: function() {
          callback({
            success: false,
            message: ''
          });

        },
        success: function(response) {
          try {
            response = $.parseJSON(response);
            callback({
              success: true,
              response: response
            });
          } catch(e) {
            callback({
              success: false,
              message: e.getMessage()
            });
            console.log(response);
          }
        }
      });
    } catch(e) {
      callback({
        success: false,
        message: e.getMessage()
      });

    }
    /*
    console.log("LOAD " + url);
    
      console.log('response:');
      console.log(response);
    });

    */
  }
}

var ColorPaletteDisplay = function() {
  this.canvas = null;
  this.context = null;
  this.canvasScale = 1;

  this.colorWidth = 20;
  this.colorHeight = 20;
  this.colorSpacing = 1;

  this.colorsAcross = 8;
  this.colorsDown = 2;
  this.colorCount = 16;
  this.colors = [];

  this.selectedColors = [];

  this.highlightColor =  false;//this.editor.colorPaletteManager.noColor;

  this.cursorRGB = false;
  this.colorSelected = false;
  this.highlightChanged = false;

  this.touchColorHandler = false;
  this.touchEndColorHandler = false;

  this.buttons = 0;
  // map of x,y to colour

  // should always be true
  this.useColorMap = true;
  this.colorMap = [];
  this.noColor = -1;

  this.lastGridX = false;
  this.lastGridY = false;

  this.gridMouseMove = false;
  this.gridMouseDown = false;
  this.gridMouseUp = false;
  this.gridEndDrag = false;
  this.gridEndMarqueeDrag = false;

  this.gridDoubleClick = false;

  this.marqueeChanged = false;

  this.gridLinesVisible = false;
  this.selectEnabled = true;
  this.highlightEnabled = true;

  this.highlightGridX = false;
  this.highlightGridY = false;

  this.inDragMarquee = false;
  this.dragMarqueeContents = false;

  this.inDragColor = false;
  this.dragColorX = false;
  this.dragColorY = false;
  this.dragColorIndex = false;

  this.dragOffsetX = 0;
  this.dragOffsetY = 0;

  this.maxSelectableColors = 2;
  this.canSelectWithRightMouseButton = false;
  this.canSelectMultiple = false;

  this.touchColorEndHandler = false;

  this.multipleSelectMode = 'add';

  this.marquee = false;
  this.marqueeLeft = 0;//false;
  this.marqueeWidth = 1;//false;
  this.marqueeTop = 0;//false;
  this.marqueeHeight = 2;//false;

  this.type = '';

  this.canvasElementId = false;


  this.maxColorWidth = false;

  this.drawEnabled = true;
  this.drawHighlightInMarquee = true;

}

ColorPaletteDisplay.prototype = {
  init: function(editor, args) {
    this.editor = editor;
    this.canvasElementId = args.canvasElementId;    

    this.selectedColors[0] =  this.editor.colorPaletteManager.noColor;
    this.selectedColors[1] =  this.editor.colorPaletteManager.noColor;
    this.highlightColor = this.editor.colorPaletteManager.noColor;


    if(typeof args != 'undefined') {
      if(typeof args.gridLinesVisible != 'undefined') {
        this.gridLinesVisible = args.gridLinesVisible;
      }

      if(typeof args.selectEnabled != 'undefined') {
        this.selectEnabled = args.selectEnabled;
      }

      if(typeof args.highlightEnabled != 'undefined') {
        this.highlightEnabled = args.highlightEnabled;
      }

      if(typeof args.maxSelectableColors != 'undefined') {
        this.maxSelectableColors = args.maxSelectableColors;
      }

      if(typeof args.canSelectWithRightMouseButton != 'undefined') {
        this.canSelectWithRightMouseButton = args.canSelectWithRightMouseButton;
      }

      if(typeof args.canSelectMultiple != 'undefined') {
        this.canSelectMultiple = args.canSelectMultiple;
      }
    }

    if(this.canSelectMultiple) {
      this.selectedColors = [];
    }

  },

  initEvents: function() {
    var _this = this;
    $('#' + this.canvasElementId).on('mousedown', function(event) {
      _this.mouseDown(event);
    });

    $('#' + this.canvasElementId).on('mousemove', function(event) {
      _this.mouseMove(event);
    });

    $('#' + this.canvasElementId).on('mouseup', function(event) {
      _this.mouseUp(event);
    });

    this.canvas.addEventListener('dblclick', function(event) {
      _this.doubleClick(event);
    }, false);

    this.canvasElement = document.getElementById(this.canvasElementId);

    this.canvasElement.addEventListener('touchstart', function(event) {
      _this.touchStart(event);
    }, false);

    this.canvasElement.addEventListener('touchmove', function(event) {
      _this.touchMove(event);
    }, false);

    this.canvasElement.addEventListener('touchend', function(event) {
      _this.touchEnd(event);
    }, false);


    $('#' + this.canvasElementId).on('contextmenu', function(event) {
      event.preventDefault();
    });


    $('#' + this.canvasElementId).on('mouseenter', function(event) {
      _this.mouseEnter(event);
    });

    $('#' + this.canvasElementId).on('mouseleave', function(event) {
      _this.mouseLeave(event);
    });
  },

  setDrawEnabled: function(enabled) {
    this.drawEnabled = enabled;
  },

  getDrawEnabled: function() {
    return this.drawEnabled;
  },


  // set whether to draw the highlight cursor when it is in the marquee
  setDrawHighlightInMarquee: function(draw) {
    this.drawHighlightInMarquee = draw;
  },

  setup: function() {
    if(this.canvas === null) {
      this.canvas = document.getElementById(this.canvasElementId);
      this.initEvents();
    }

    this.canvasScale = Math.floor(UI.devicePixelRatio);

    var colorsAcross = 1;
    var colorsDown = 1;

    if(this.colorMap.length > 0) {
      colorsAcross = this.colorMap[0].length;
      colorsDown = this.colorMap.length;
    }

    var width = (this.colorWidth + this.colorSpacing) * colorsAcross + this.colorSpacing;
    var height = (this.colorHeight + this.colorSpacing) * colorsDown + this.colorSpacing;


    if(width == 0) {
      width = 1;
    }

    if(height == 0) {
      height = 1;
    }


    this.canvas.width = width * this.canvasScale;
    this.canvas.height = height * this.canvasScale;
    this.canvas.style.width = width + 'px';
    this.canvas.style.height = height + 'px';


    this.context = this.canvas.getContext('2d');
    this.context.scale(this.canvasScale, this.canvasScale);


  },

  getCanvas: function() {
    return this.canvas;
  },

  getCanvasWidth: function() {
    return this.canvas.width;
  },

  getCanvasHeight: function() {
    return this.canvas.height;
  },

  setColorSize: function(width, height, spacing) {
    this.colorWidth = width;
    this.colorHeight = height;
    if(typeof spacing != 'undefined') {
      this.colorSpacing = spacing;
    }

    this.setup();

  },

  getColorsAcross: function() {
    return this.colorsAcross;
  },

  // need to know if its a cell colour in c64 multicolor mode
  setType: function(type) {
    this.type = type;
  },

  setMarqueeBounds: function(left, top, width, height) {
    this.marqueeLeft = left;
    this.marqueeTop = top;
    this.marqueeWidth = width;
    this.marqueeHeight = height;

    if(this.marqueeChanged !== false) {
      this.marqueeChanged(left, top, width, height);
    }

  },



  setMarqueeEnabled: function(enabled) {
    this.marquee = enabled;
  },
  
  getMarqueeEnabled: function() {
    return this.marquee;
  },

  inMarquee: function(gridX, gridY) {
    return gridX >= this.marqueeLeft && gridX < (this.marqueeLeft + this.marqueeWidth) 
        && gridY >= this.marqueeTop && gridY < (this.marqueeTop + this.marqueeHeight);
  },

  getHeight: function() {
    return Math.ceil(this.canvas.height / this.canvasScale);
  },

  getWidth: function() {
    return Math.ceil(this.canvas.width / this.canvasScale);
  },



  setButtons: function(event) {
    if(event.buttons != 'undefined') {
      this.buttons = event.buttons;
    }
    if(event.buttons === 'undefined' && event.nativeEvent !== 'undefined') {
      this.buttons = event.nativeEvent.buttons;
    }

    if(typeof event.touches != 'undefined' && event.touches.length == 1) {
      this.buttons = 1;
    }
    // ctrl click
    if(event.ctrlKey && this.buttons == 1) {
      this.buttons = 2;
    }

    // cmd + click
    if(event.metaKey && this.buttons == 1) {
      this.buttons = 4;
    }

  },

  on: function(eventName, f) {
    if(eventName == 'colorselected') {
      this.colorSelected = f;
    }

    if(eventName == 'highlightchanged') {
      this.highlightChanged = f;
    }

    if(eventName == 'mousemove') {
      this.gridMouseMove = f;
    }

    if(eventName == 'doubleclick') {
      this.gridDoubleClick = f;
    }

    if(eventName == 'mousedown') {
      this.gridMouseDown = f;
    }

    if(eventName == 'mouseup') {
      this.gridMouseUp = f;
    }

    if(eventName == 'mouseenter') {
      this.gridMouseEnter = f;
    }

    if(eventName == 'mouseleave') {
      this.gridMouseLeave = f;
    }

    if(eventName == 'enddrag') {
      this.gridEndDrag = f;
    }

    if(eventName == 'endmarqueedrag') {
      this.gridEndMarqueeDrag = f;
    }

    if(eventName == 'marqueechanged') {
      this.marqueeChanged = f;
    }

    if(eventName == 'touchcolor') {
      this.touchColorHandler = f;
    }

    if(eventName == 'touchcolorend') {
      this.touchColorEndHandler = f;
    }

  },

  mouseEnter: function(event) {
    if(this.gridMouseEnter) {
      this.gridMouseEnter(event);
    }

  },

  mouseLeave: function(event) {
    this.setHighlightColor(this.editor.colorPaletteManager.noColor);
    if(this.gridMouseLeave) {
      this.gridMouseLeave(event);
    }
  },


  multipleSelect: function(color) {
    // see if already selected
    var selectedIndex = false;
    for(var i = 0; i < this.selectedColors.length; i++) {
      if(this.selectedColors[i] === color)  {
        selectedIndex = i;
        break;
      }
    }

    if(selectedIndex !== false) {
      // remove it
      if(this.multipleSelectMode == 'remove') {
        this.selectedColors.splice(selectedIndex, 1);
      }
    } else {
      if(this.multipleSelectMode == 'add') {
        this.selectedColors.push(color);
      }
    }

    this.draw();
  },



  touchStart: function(event) {
    event.preventDefault();

    var touches = event.changedTouches;

    if(touches.length > 0) {
      var x = touches[0].pageX - $('#' + this.canvasElementId).offset().left;
      var y = touches[0].pageY - $('#' + this.canvasElementId).offset().top;

      var color = this.xyToColor(x, y);
      if(color !== false) {
        if(this.touchColorHandler !== false) {
          this.touchColorHandler(color);
        }

        if(this.selectEnabled) {
          // selecting range of colours
          if(color !== this.editor.colorPaletteManager.noColor) {
            if(this.canSelectMultiple) {
              // is already added ?
              this.multipleSelectMode = 'add';
              for(var i = 0; i < this.selectedColors.length; i++) {
                if(this.selectedColors[i] === color) {
                  this.multipleSelectMode = 'remove';
                  break;
                }
              }
              this.multipleSelect(color);
//              this.lastGridY = gridY;
//              this.lastGridX = gridX;
            } else {
              this.selectedColors[0] = color;
            }
            if(this.colorSelected !== false) {
              this.colorSelected({ color: color, colorIndex: 0 });
            }
          }

          if( (this.buttons & 2) && this.canSelectWithRightMouseButton) {
            this.selectedColors[1] = color;
            if(this.colorSelected !== false) {
              this.colorSelected({ color: color, colorIndex: 1 });
            }
          }
          this.draw();
        }


      }

/*
      this.mouseDownOnCharacter =  this.charPaletteXYToChar(x, y);

      if(this.mouseDownOnCharacter !== false) {
        if(this.touchCharacterHandler !== false) {
          this.touchCharacterHandler(this.mouseDownOnCharacter);
        }
      }
*/

    }

  },


  touchMove: function(event) {
    event.preventDefault();

    var touches = event.changedTouches;

    if(touches.length > 0) {
      var x = touches[0].pageX - $('#' + this.canvasElementId).offset().left;
      var y = touches[0].pageY - $('#' + this.canvasElementId).offset().top;


      var color = this.xyToColor(x, y);
      if(color !== false) {
        if(this.touchColorHandler !== false) {
          this.touchColorHandler(color);
        }


        if(this.canSelectMultiple) {
          var color = this.xyToColor(x, y);
          this.multipleSelect(color);
        }


      }

/*
      this.mouseDownOnCharacter =  this.charPaletteXYToChar(x, y);

      if(this.mouseDownOnCharacter !== false) {
        if(this.touchCharacterHandler !== false) {
          this.touchCharacterHandler(this.mouseDownOnCharacter);
        }
      }
*/      
    }

  },

  touchEnd: function(event) {
    event.preventDefault();
    var touches = event.changedTouches;
    if(touches.length > 0) {


      var x = touches[0].pageX - $('#' + this.canvasElementId).offset().left;
      var y = touches[0].pageY - $('#' + this.canvasElementId).offset().top;

      var color = this.xyToColor(x, y);
      if(color !== false) {
        if(this.touchColorEndHandler !== false) {

          this.touchColorEndHandler(color);
        }
      }

/*
      var character =  this.charPaletteXYToChar(x, y);

      if(character !== false) {
        if(this.touchEndCharacterHandler !== false) {
          this.touchEndCharacterHandler(character);
        }
      }
      */
    }
    
  },

  doubleClick: function(event) {
    if(this.gridDoubleClick) {
      this.gridDoubleClick();
    }
  },


  mouseDown: function(event) {
    var x = event.pageX - $('#' + this.canvasElementId).offset().left;
    var y = event.pageY - $('#' + this.canvasElementId).offset().top;

    var gridX = Math.floor((x - this.colorSpacing) / (this.colorWidth + this.colorSpacing));
    var gridY = Math.floor((y - this.colorSpacing) / (this.colorHeight + this.colorSpacing));

    var button = 0;
    this.buttons = 1;
    if(!UI.isMobile.any()) {
      button = event.button;
      this.setButtons(event);
    }

    if(this.lastGridX !== false && this.lastGridY !== false) {
      if(this.gridMouseDown) {
        this.gridMouseDown(event, this.lastGridX, this.lastGridY);
      }

    }

    var color = this.xyToColor(x, y);

    if(this.selectEnabled) {
      
      // selecting range of colours
      if(color !== this.editor.colorPaletteManager.noColor) {
        if(this.buttons & 1) {
          if(this.canSelectMultiple) {
            // is already added ?
            this.multipleSelectMode = 'add';
            for(var i = 0; i < this.selectedColors.length; i++) {
              if(this.selectedColors[i] === color) {
                this.multipleSelectMode = 'remove';
                break;
              }
            }
            this.multipleSelect(color);
            this.lastGridY = gridY;
            this.lastGridX = gridX;
          } else {
            this.selectedColors[0] = color;
          }
          if(this.colorSelected !== false) {
            this.colorSelected({ color: color, colorIndex: 0 });
          }
        }

        if( (this.buttons & 2) && this.canSelectWithRightMouseButton) {
          this.selectedColors[1] = color;
          if(this.colorSelected !== false) {
            this.colorSelected({ color: color, colorIndex: 1 });
          }
        }
        this.draw();
      }
    } else {


    }

    event.preventDefault();
  },

  mouseMove: function(event) {

    var button = 0;
    this.buttons = 1;
    if(!UI.isMobile.any()) {
      button = event.button;
      this.setButtons(event);
    }

    var x = event.pageX - $('#' + this.canvasElementId).offset().left;
    var y = event.pageY - $('#' + this.canvasElementId).offset().top;

    var gridX = Math.floor((x - this.colorSpacing) / (this.colorWidth + this.colorSpacing));
    var gridY = Math.floor((y - this.colorSpacing) / (this.colorHeight + this.colorSpacing));

    this.lastX = x;
    this.lastY = y;


    if(gridX < 0) {
      gridX = false;
    }

    if(gridY < 0) {
      gridY = false;
    }

    if(gridX !== this.lastGridX || gridY !== this.lastGridY) {
      if(gridX !== false && gridY !== false) {
        if(this.gridMouseMove) {
          this.gridMouseMove(event, gridX, gridY);
        }
      }
      this.lastGridY = gridY;
      this.lastGridX = gridX;

    }

    if(this.canSelectMultiple) {
      if(this.buttons & 1) {        
        var color = this.xyToColor(x, y);
        this.multipleSelect(color);
      }

    }

    if(this.highlightEnabled) {
      var color = this.xyToColor(x, y);

//      if(this.buttons == 0) {
        if(this.highlightColor !== color) {
          this.setHighlightColor(color);

        }
//      }
    }

    if(this.inDragColor) {
      this.draw();
    }

    if(this.inDragMarquee) {
      this.draw();
    }

  },

  mouseUp: function(event) {
    var x = event.pageX - $('#' + this.canvasElementId).offset().left;
    var y = event.pageY - $('#' + this.canvasElementId).offset().top;

    this.buttons = 0;
    var gridX = Math.floor((x - this.colorSpacing) / (this.colorWidth + this.colorSpacing));
    var gridY = Math.floor((y - this.colorSpacing) / (this.colorHeight + this.colorSpacing));

    if(this.gridMouseUp) {

      this.gridMouseUp(event, gridX, gridY);

    }

    if(this.inDragColor) {
      this.inDragColor = false;
      this.endDragColor(gridX, gridY);
    }

    if(this.inDragMarquee) {
      this.inDragMarquee = false;
      this.endDragMarquee();
    }

    this.draw();
  },

  setColorsAcross: function(colorsAcross) {
    this.colorsAcross = colorsAcross;
    this.draw();
  },

  setHighlightColor: function(color) {
    this.highlightColor = color;
    this.draw();
    if(this.highlightChanged !==  false) {
      this.highlightChanged({ color: color });
    }
  },

  setHighlightGrid: function(gridX, gridY) {
    this.highlightGridX = gridX;
    this.highlightGridY = gridY;
  },

  setGridVisible: function(visible) {
    this.gridLinesVisible = visible;
    this.draw();
  },


  getHighlightColor: function() {
    return this.highlightColor;
  },

  setSelectedColor: function(index, color) {
    //if(index < this.selectedColors.length) {
    if(index < this.maxSelectableColors) {
      this.selectedColors[index] = color;
      this.draw();
    }


    // dont want to cause infinite loop so dont trigger events?
  },

  getSelectedColor: function(index) {
    if(index < this.selectedColors.length) {
      return this.selectedColors[index];
    } 

    return false;
  },

  setSelectedColors: function(selectedColors) {
    this.selectedColors = [];
    for(var i = 0; i < selectedColors.length; i++) {
      this.selectedColors.push(selectedColors[i]);
    }
  },

  getSelectedColors: function() {
    return this.selectedColors;
  },

  setColors: function(colors, args) {
    this.colorCount = colors.length;    

    if(typeof args != 'undefined') {
      if(typeof args.colorMap != 'undefined') {
        this.setColorMap(args.colorMap);
      }

      if(typeof args.colorCount != 'undefined') {
        this.colorCount = args.colorCount;
      }
    }


    this.colors = [];

    for(var i = 0; i < this.colorCount; i++) {
      this.colors.push(colors[i]);
    }

    this.setup();
    this.draw();
  },

  setColorMap: function(colorMap) {
    this.useColorMap = true;
    this.colorMap = colorMap;
  },


  setMaxColorWidth: function(maxColorWidth) {
    this.maxColorWidth = maxColorWidth;
  },


  fitToWidthHeight: function(width, height) {
    var canvasWidth = 0;
    var canvasHeight = height;
    if(typeof width == 'undefined') {
      canvasWidth = Math.floor(this.canvas.width / this.canvasScale);
    } else {
      canvasWidth = width;
    }

    var colorsAcross = 1;
    var colorsDown = 1;
    if(this.colorMap.length > 0) {
      colorsAcross = this.colorMap[0].length;
      colorsDown = this.colorMap.length;
    }

    this.colorWidth = Math.floor(((canvasWidth - this.colorSpacing) / colorsAcross) - this.colorSpacing);
    this.colorHeight = Math.floor(((canvasHeight - this.colorSpacing) / colorsDown) - this.colorSpacing);


    if(this.maxColorWidth !== false && this.colorWidth > this.maxColorWidth) {
      this.colorWidth = this.maxColorWidth;
    }

    if(this.colorHeight < this.colorWidth) {
      this.colorWidth = this.colorHeight;
    }

    this.colorHeight = this.colorWidth;


    this.setup();
    this.draw();

  },


  fitToWidth: function(width) {
    var canvasWidth = 0;
    if(typeof width == 'undefined') {
      canvasWidth = Math.floor(this.canvas.width / this.canvasScale);
    } else {
      canvasWidth = width;
    }

    var colorsAcross = 1;
    var colorsDown = 1;
    if(this.colorMap.length > 0) {
      colorsAcross = this.colorMap[0].length;
      colorsDown = this.colorMap.length;
    }

    this.colorWidth = Math.floor(((canvasWidth - this.colorSpacing) / colorsAcross) - this.colorSpacing);

    if(this.maxColorWidth !== false && this.colorWidth > this.maxColorWidth) {
      this.colorWidth = this.maxColorWidth;
    }
    this.colorHeight = this.colorWidth;


    this.setup();
    this.draw();

  },
/*
  getHeight: function() {
    return this.canvas.height;
  },
*/

  moveSelection: function(dx, dy) {

    if(this.useColorMap) {
      var colorIndex = this.selectedColors[0];
      var mapXY = this.colorToGridXy(colorIndex);
      if(dx != 0 || dy != 0 && mapXY.x !== false && mapXY.y !== false) {
        var y = mapXY.y;
        var x = mapXY.x;
        while(1) {
          x += dx;
          y += dy;
          if(y < 0 || y >= this.colorMap.length || x < 0 || x >= this.colorMap[y].length ) {
            return;
          }


          if(this.colorMap[y][x] != this.noColor) {
            this.selectedColors[0] = this.colorMap[y][x];
            if(this.colorSelected !== false) {
              this.colorSelected({ color: this.selectedColors[0], colorIndex: 0 });
            }
            this.draw();
            return;
          }
        }

      }

    } else {
      for(var y = 0; y < this.colorsDown; y++) {
        for(var x = 0; x < this.colorsAcross; x++) {
          var colorIndex = x + y * this.colorsAcross;
          if(this.sortOrder !== false && this.colors.length == this.sortOrder.length) {
            colorIndex = this.sortOrder[colorIndex];
          }

          if(colorIndex == this.selectedColors[0]) {
            var nextX = x + dx;
            var nextY = y + dy;
            if(nextX < 0 || nextX >= this.colorsAcross || nextY < 0 || nextY >= this.colorsDown) {
              return;
            }
            var colorIndex = nextX + nextY * this.colorsAcross;
            if(this.sortOrder !== false && this.colors.length == this.sortOrder.length) {
              colorIndex = this.sortOrder[colorIndex];
            }
            // set the new colour
  //          var newColor = this.sortOrder[colorIndex];
            this.selectedColors[0] = colorIndex;
            if(this.colorSelected !== false) {
              this.colorSelected({ color: colorIndex, colorIndex: 0 });
            }
            this.draw();

            return;
          }

        }
      }
    }


  },

  gridXYToCell: function(gridX, gridY) {
    var x = gridX * (this.colorWidth + this.colorSpacing);
    var y = gridY * (this.colorHeight + this.colorSpacing);

    return {
      centerX: x + (this.colorWidth / 2),
      centerY: y + (this.colorHeight / 2)
    };

  },


  xyToColor: function(x, y) {
    x -= this.colorSpacing * 2;
    y -= this.colorSpacing * 2;

    if(x < 0 || y < 0) {
      return this.noColor;
    }

    var colorX = Math.floor(x / (this.colorWidth + this.colorSpacing));
    var colorY = Math.floor(y / (this.colorHeight + this.colorSpacing));

    if(this.useColorMap) {
      if(colorY < this.colorMap.length && colorX < this.colorMap[colorY].length) {
        return this.colorMap[colorY][colorX];
      }

    } else {
      if(colorX >= this.colorsAcross || colorX < 0) {
        return  this.editor.colorPaletteManager.noColor;
      }

      if(colorY >= this.colorsDown || colorY < 0) {
        return  this.editor.colorPaletteManager.noColor;
      }

      var color = colorY * this.colorsAcross + colorX;

      if(this.sortOrder !== false && this.colors.length == this.sortOrder.length) {
        color = this.sortOrder[color];
      }

      return color;
    }

    return this.noColor;
  },

  colorToGridXy: function(color) {
    var colorIndex = color;

    if(color === this.noColor) {
      return {x: false, y: false};
    }

    if(this.useColorMap) {
      for(var y = 0; y < this.colorMap.length; y++) {
        for(var x = 0; x < this.colorMap[y].length; x++) {
          if(this.colorMap[y][x] == colorIndex) {
            return { x: x, y: y};

          }

        }
      }

    } else {
      if(this.sortOrder !== false && this.colors.length == this.sortOrder.length) {
        for(var i = 0; i < this.sortOrder.length; i++) {
          if(this.sortOrder[i] == colorIndex) {
            colorIndex = i;
            break;
          }
        }
      }

      var x = colorIndex % this.colorsAcross;
      var y = Math.floor(colorIndex / this.colorsAcross);
      return {x: x, y: y};
    }

    return { x: false, y: false };
  },


  startDragColor: function(gridX, gridY) {
    var colorIndex = this.getColorAtMapXY(gridX, gridY);
    if(colorIndex === this.noColor) {
      return;
    }

    this.inDragColor = true;
    this.dragColorX = gridX;
    this.dragColorY = gridY;
    this.dragColorIndex = colorIndex;

    // get the mouse offset into the grid cell
    var xPos = this.colorSpacing + gridX * (this.colorWidth + this.colorSpacing);
    var yPos = this.colorSpacing + gridY * (this.colorHeight + this.colorSpacing);
    this.dragOffsetX = xPos - this.lastX;
    this.dragOffsetY = yPos - this.lastY;

    UI.captureMouse(this);
  },

  endDragColor: function(gridX, gridY) {
    if(this.gridEndDrag) {
      this.gridEndDrag(this.dragColorX, this.dragColorY, gridX, gridY);
    }
  },

  startDragMarquee: function(dragMarqueeContents) {

    this.inDragMarquee = true;
    this.dragMarqueeContents = dragMarqueeContents;

    // get the mouse offset into the marquee
    var xPos = this.colorSpacing + this.marqueeLeft * (this.colorWidth + this.colorSpacing);
    var yPos = this.colorSpacing + this.marqueeTop * (this.colorHeight + this.colorSpacing);
    this.dragOffsetX = xPos - this.lastX;
    this.dragOffsetY = yPos - this.lastY;

    UI.captureMouse(this);

  },

  getInDragMarquee: function() {
    return this.inDragMarquee;
  },

  endDragMarquee: function() {
    var xPos = this.lastX + this.dragOffsetX;
    var yPos = this.lastY + this.dragOffsetY;

    
    var left = xPos; //this.colorSpacing + this.marqueeLeft * (this.colorWidth + this.colorSpacing);
    var top = yPos; //this.colorSpacing + this.marqueeTop * (this.colorHeight + this.colorSpacing);

    var gridX = Math.floor(  (xPos / (this.colorWidth + this.colorSpacing)) - this.colorSpacing );
    var gridY = Math.floor(  (yPos / (this.colorHeight + this.colorSpacing)) - this.colorSpacing );
    //var width = this.marqueeWidth * (this.colorWidth + this.colorSpacing);
    //var height = this.marqueeHeight * (this.colorHeight + this.colorSpacing);

    if(this.gridEndMarqueeDrag) {
      this.gridEndMarqueeDrag(this.marqueeLeft, this.marqueeTop, this.marqueeWidth, this.marqueeHeight, gridX, gridY);
    }


    this.marqueeLeft = gridX;
    this.marqueeTop = gridY;
  },

  getColorMap: function() {
    return this.colorMap;
  },

  getColorAtMapXY: function(x, y) {
    if(y < this.colorMap.length && x < this.colorMap[y].length) {
      return this.colorMap[y][x];
    }

    return this.noColor;
  },

  setColorAtMapXY: function(x, y, color) {
    if(x >= 0 && y >= 0 && y < this.colorMap.length && x < this.colorMap[y].length) {
      this.colorMap[y][x] = color;
    }
  },

  drawGridLines: function() {


    var colorsAcross = 1;
    var colorsDown = 1;
    if(this.colorMap.length > 0) {
      colorsAcross = this.colorMap[0].length;
      colorsDown = this.colorMap.length;
    }


    this.context.beginPath();

    for(var x = 0; x < colorsAcross; x++) {
      var xPos = this.colorSpacing + x * (this.colorWidth + this.colorSpacing);
//      var yPos = this.colorSpacing + y * (this.colorHeight + this.colorSpacing);
//      var xPosition = gridX;

      this.context.moveTo(xPos, 0);
      this.context.lineTo(xPos, this.canvas.height);

    }


    for(var y = 0; y < colorsDown; y++) {
      var yPos = this.colorSpacing + y * (this.colorHeight + this.colorSpacing); 
      this.context.moveTo(0, yPos + 0.5);
      this.context.lineTo(this.canvas.width, yPos + 0.5);          
    }

    this.context.strokeStyle = styles.textMode.gridView2dGridLine;
    this.context.lineWidth = styles.textMode.gridView2dGridLineWidth;
    this.context.stroke();
  },


  setCursorRGB: function(cursorRGB) {
    if(this.cursorRGB === cursorRGB) {
      return;
    }
    if(cursorRGB === false) {
      this.cursorRGB = false;
    } else {
      this.cursorRGB = '#' +  ("000000" + cursorRGB.toString(16)).substr(-6);
    }
  },


  getContext: function() {
    return this.context;
  },


  draw: function() {

    if(!this.drawEnabled) {
      return;
    }

//    this.context.clearRect(0, 0, this.canvas.width, this.canvas.height);
    if(this.colorMap.length == 0) {
      return;
    }


    //console.log('draw color palette display');
    // draw in the stipple
    var imageData = this.context.getImageData(0, 0, this.canvas.width, this.canvas.height);      
    var index = 0;

    for(var y = 0; y < this.canvas.height; y++) {
      for(var x = 0; x < this.canvas.width; x++) {
        if( (x + y) % (2 * this.canvasScale))  {
          imageData.data[index++] = 30;
          imageData.data[index++] = 30;
          imageData.data[index++] = 30;
        } else {          
          imageData.data[index++] = 70;
          imageData.data[index++] = 70;
          imageData.data[index++] = 70;
        }
        imageData.data[index++] = 255;
      }
    }

    this.context.putImageData(imageData, 0, 0);

    var colorsAcross = 1;
    var colorsDown = 1;

    if(this.colorMap.length > 0) {
      colorsAcross = this.colorMap[0].length;
      colorsDown = this.colorMap.length;
    }

    this.colorsAcross = colorsAcross;
    this.colorsDown = colorsDown;

    var screenMode = this.editor.getScreenMode();


    for(var y = 0; y < colorsDown; y++) {
      for(var x = 0; x < colorsAcross; x++) {

        var xPos = this.colorSpacing + x * (this.colorWidth + this.colorSpacing);
        var yPos = this.colorSpacing + y * (this.colorHeight + this.colorSpacing);

        var colorIndex = x + y * this.colorsAcross;

        if(this.useColorMap) {
          colorIndex = this.colorMap[y][x];
        }

        if(colorIndex < this.colors.length && colorIndex >= 0) {

          var multicolorMode = false;

          if(screenMode === TextModeEditor.Mode.C64MULTICOLOR && this.type == 'cellcolor') {

            if(this.editor.graphic.getType() == 'sprite') {
              multicolorMode = true;
            } else if(colorIndex >= 8) {
              colorIndex -= 8;
              multicolorMode = true;
            }
          }
          var alpha = (this.colors[colorIndex] >>> 24) & 0xff;
          var color = this.colors[colorIndex] & 0xffffff;

          var colorHexString = ("000000" + color.toString(16)).substr(-6);

          this.context.fillStyle = '#' + colorHexString;
          this.context.fillRect(xPos, yPos, this.colorWidth, this.colorHeight);


          if(multicolorMode && this.editor.graphic.getType() !== 'sprite') {
            this.context.font = "8px Verdana";
            this.context.fillStyle = "#eeeeee";
            this.context.fillText("M",  xPos + 2, yPos + 8); 

          }


        }
      }
    }

    // draw grid lines
    if(this.gridLinesVisible) {
      this.drawGridLines();
    }



    // draw selected colour outlines
    for(var i = 0; i < this.selectedColors.length; i++) {
      var colorPosition = { x: false, y: false };

      if(this.selectedColors[i] !== this.editor.colorPaletteManager.noColor) {
        colorPosition = this.colorToGridXy(this.selectedColors[i]);

        if(colorPosition.x !== false) {
          // should check 
          this.context.fillStyle = "#ffff00";
          this.context.strokeStyle = "#ffff00";

          var xPos = this.colorSpacing + (colorPosition.x) * (this.colorWidth + this.colorSpacing);
          var yPos = this.colorSpacing + colorPosition.y * (this.colorHeight + this.colorSpacing);

          this.context.beginPath();
          if(i % 2 == 0 || this.canSelectMultiple) {
            this.context.moveTo(xPos, yPos);
            this.context.lineTo(xPos + this.colorWidth / 3, yPos);
            this.context.lineTo(xPos, yPos + this.colorHeight / 3);
          } else {
            this.context.moveTo(xPos + this.colorWidth, yPos + this.colorHeight);
            this.context.lineTo(xPos + this.colorWidth - this.colorWidth / 3, yPos + this.colorHeight);
            this.context.lineTo(xPos + this.colorWidth, yPos + this.colorHeight - this.colorHeight / 3);

          }
          this.context.fill();

          this.context.beginPath();
          this.context.lineWidth = 2;
          this.context.rect(xPos, yPos, this.colorWidth, this.colorHeight);
          this.context.stroke();
        }

      }
    }


    // draw highlight colour outline

    if(this.highlightColor !== false) {
      var colorPosition = this.colorToGridXy(this.highlightColor);

      if(colorPosition.x !== false) {
        this.context.strokeStyle = styles.colorPalette.highlightOutline;
        var xPos = this.colorSpacing + colorPosition.x * (this.colorWidth + this.colorSpacing);
        var yPos = this.colorSpacing + colorPosition.y * (this.colorWidth + this.colorSpacing);


        this.context.beginPath();
        this.context.lineWidth = 1;
        this.context.rect(xPos, yPos, this.colorWidth, this.colorHeight);
        this.context.stroke();
      }
    }


    // fill highlight colour

    if(!this.inDragMarquee && (this.drawHighlightInMarquee|| !this.inMarquee(this.highlightGridX, this.highlightGridY)) ) {
      if(this.highlightGridX !== false && this.highlightGridY !== false) {
        var xPos = this.colorSpacing + this.highlightGridX * (this.colorWidth + this.colorSpacing);
        var yPos = this.colorSpacing + this.highlightGridY * (this.colorWidth + this.colorSpacing);

        if(this.cursorRGB !== false) {
          this.context.fillStyle = this.cursorRGB;
          this.context.globalAlpha = 0.5;
          this.context.fillRect(xPos, yPos, this.colorWidth, this.colorHeight);
          this.context.globalAlpha = 1;
        }

        this.context.beginPath();
        this.context.lineWidth = 1;
        this.context.rect(xPos, yPos, this.colorWidth, this.colorHeight);
        this.context.stroke();

      }
    }


    // draw marquee
    if(this.marquee && this.marqueeLeft !== false && this.marqueeTop !== false) {
      var left = this.colorSpacing + this.marqueeLeft * (this.colorWidth + this.colorSpacing);
      var top = this.colorSpacing + this.marqueeTop * (this.colorHeight + this.colorSpacing);
      var width = this.marqueeWidth * (this.colorWidth + this.colorSpacing);
      var height = this.marqueeHeight * (this.colorHeight + this.colorSpacing);


      if(this.editor.lastDashOffset == 0) {
        this.context.setLineDash([5, 5]);
      } else {
        this.context.setLineDash([0,5,5,0]);
      }


      this.context.beginPath();
      this.context.lineWidth = 1;
      this.context.rect(left, top, width, height);
      this.context.stroke();

      this.context.setLineDash([]); 

    }


    if(this.inDragMarquee) {
      var xPos = this.lastX + this.dragOffsetX;
      var yPos = this.lastY + this.dragOffsetY;
      
      var left = xPos; //this.colorSpacing + this.marqueeLeft * (this.colorWidth + this.colorSpacing);
      var top = yPos; //this.colorSpacing + this.marqueeTop * (this.colorHeight + this.colorSpacing);
      var width = this.marqueeWidth * (this.colorWidth + this.colorSpacing);
      var height = this.marqueeHeight * (this.colorHeight + this.colorSpacing);

      if(this.dragMarqueeContents) {
        for(var y = 0; y < this.marqueeHeight; y++) {
          for(var x = 0; x < this.marqueeWidth; x++) {
            xPos = left + x * (this.colorWidth + this.colorSpacing);
            yPos = top + y * (this.colorHeight + this.colorSpacing);

            var colorIndex = this.colorMap[y + this.marqueeTop][x + this.marqueeLeft]

            if(colorIndex < this.colors.length && colorIndex >= 0) {
              var color = this.colors[colorIndex] & 0xffffff;
              var colorHexString = ("000000" + color.toString(16)).substr(-6);

              this.context.fillStyle = '#' + colorHexString;
              this.context.fillRect(xPos, yPos, this.colorWidth, this.colorHeight);
            }



            ;
          }
        }
      }

      if(this.editor.lastDashOffset == 0) {
        this.context.setLineDash([5, 5]);
      } else {
        this.context.setLineDash([0,5,5,0]);
      }


      this.context.beginPath();
      this.context.lineWidth = 1;
      this.context.rect(left, top, width, height);
      this.context.stroke();

      this.context.setLineDash([]); 


    }


    // draw drag colour
    if(this.inDragColor) {

      var xPos = this.colorSpacing + this.dragColorX * (this.colorWidth + this.colorSpacing);
      var yPos = this.colorSpacing + this.dragColorY * (this.colorWidth + this.colorSpacing);


      this.context.strokeStyle = "#ffff00";
      this.context.beginPath();
      this.context.lineWidth = 1;
      this.context.rect(xPos, yPos, this.colorWidth, this.colorHeight);
      this.context.stroke();


      var xPos = this.lastX + this.dragOffsetX;
      var yPos = this.lastY + this.dragOffsetY;

      var color = this.colors[this.dragColorIndex];

      var colorHexString = ("000000" + color.toString(16)).substr(-6);
      this.context.fillStyle = '#' + colorHexString;
      this.context.fillRect(xPos, yPos, this.colorWidth, this.colorHeight);


    }

  }

}

