      this.imageDataLABA[i] = color.values[0];
      this.imageDataLABA[i + 1] = color.values[1];
      this.imageDataLABA[i + 2] = color.values[2];
      this.imageDataLABA[i + 3] = imageData.data[i + 3];;//color.values[3];
