//https://github.com/mikolalysenko/detect-pitch
//https://developer.microsoft.com/en-us/microsoft-edge/testdrive/demos/webaudiotuner/
PitchDetect.prototype = {
  init: function(music) {
    this.music = music;

    var MediaStream = window.MediaStream;

    if (typeof MediaStream === 'undefined' && typeof webkitMediaStream !== 'undefined') {
        MediaStream = webkitMediaStream;
    }

    // http://stackoverflow.com/questions/11642926/stop-close-webcam-which-is-opened-by-navigator-getusermedia
    /*global MediaStream:true */
    if (typeof MediaStream !== 'undefined' && !('stop' in MediaStream.prototype)) {
        MediaStream.prototype.stop = function() {
            this.getAudioTracks().forEach(function(track) {
                track.stop();
            });

            this.getVideoTracks().forEach(function(track) {
                track.stop();
            });
        };
    }


  },


  isGetUserMediaSupported: function () {
    navigator.getUserMedia = navigator.getUserMedia || navigator.webkitGetUserMedia || navigator.mozGetUserMedia;
    if ((navigator.mediaDevices && navigator.mediaDevices.getUserMedia) || navigator.getUserMedia) {
      return true;
    }

    return false;
  },

  start: function() {

    if (!this.isGetUserMediaSupported()) {
      alert('no access to microphone');
      return false;
    }
    if(this.audioContext == null) {
      this.audioContext = new AudioContext();
      this.MAX_SIZE = Math.max(4,Math.floor(this.audioContext.sampleRate/5000));  // corresponds to a 5kHz signal

    }

    var constraints = {
        "audio": {
            "mandatory": {
                "googEchoCancellation": "false",
                "googAutoGainControl": "false",
                "googNoiseSuppression": "false",
                "googHighpassFilter": "false"
            },
            "optional": []
        },
    };

//    navigator.getUserMedia = navigator.getUserMedia || navigator.webkitGetUserMedia || navigator.mozGetUserMedia;


    var error = function(message) {
      alert('error!' + message);
    }

    var pitchDetect = this;

    var callback = function(stream) {
      // Create an AudioNode from the stream.
      pitchDetect.mediaStreamSource = pitchDetect.audioContext.createMediaStreamSource(stream);

      // Connect it to the destination.
      pitchDetect.analyser = pitchDetect.audioContext.createAnalyser();
      pitchDetect.analyser.fftSize = 2048;
      pitchDetect.mediaStreamSource.connect( pitchDetect.analyser );
      pitchDetect.active = true;
      //updatePitch();
    };

//    navigator.getUserMedia(constraints, callback, error);    


    var getUserMedia = navigator.mediaDevices && navigator.mediaDevices.getUserMedia ?
      navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices) :
      function (constraints) {
        return new Promise(function (resolve, reject) {
          navigator.getUserMedia(constraints, resolve, reject);
        });
      };

    getUserMedia({audio: true}).then(callback).catch(error);



  },

  stop: function() {
    this.active = false;

    if (this.mediaStreamSource && this.mediaStreamSource.mediaStream && this.mediaStreamSource.mediaStream.stop) {
      this.mediaStreamSource.mediaStream.stop();
    }
    this.mediaStreamSource = null;  
    this.analyser = null;    

  },

  noteFromPitch: function( frequency ) {
    var noteNum = 12 * (Math.log( frequency / 440 )/Math.log(2) );
    return Math.round( noteNum ) + 69;
  },

  frequencyFromNoteNumber: function( note ) {
    return 440 * Math.pow(2,(note-69)/12);
  },

  centsOffFromPitch: function( frequency, note ) {
    return Math.floor( 1200 * Math.log( frequency / this.frequencyFromNoteNumber( note ))/Math.log(2) );
  },


  autoCorrelate: function( buf, sampleRate ) {
    var SIZE = buf.length;
    var MAX_SAMPLES = Math.floor(SIZE/2);
    var best_offset = -1;
    var best_correlation = 0;
    var rms = 0;
    var foundGoodCorrelation = false;
    var correlations = new Array(MAX_SAMPLES);

    for (var i=0;i<SIZE;i++) {
      var val = buf[i];
      rms += val*val;
    }
    rms = Math.sqrt(rms/SIZE);
    if (rms<0.01) // not enough signal
      return -1;

    var lastCorrelation=1;
    for (var offset = this.MIN_SAMPLES; offset < MAX_SAMPLES; offset++) {
      var correlation = 0;

      for (var i=0; i<MAX_SAMPLES; i++) {
        correlation += Math.abs((buf[i])-(buf[i+offset]));
      }
      correlation = 1 - (correlation/MAX_SAMPLES);
      correlations[offset] = correlation; // store it, for the tweaking we need to do below.
      if ((correlation>this.GOOD_ENOUGH_CORRELATION) && (correlation > lastCorrelation)) {
        foundGoodCorrelation = true;
        if (correlation > best_correlation) {
          best_correlation = correlation;
          best_offset = offset;
        }
      } else if (foundGoodCorrelation) {
        // short-circuit - we found a good correlation, then a bad one, so we'd just be seeing copies from here.
        // Now we need to tweak the offset - by interpolating between the values to the left and right of the
        // best offset, and shifting it a bit.  This is complex, and HACKY in this code (happy to take PRs!) -
        // we need to do a curve fit on correlations[] around best_offset in order to better determine precise
        // (anti-aliased) offset.

        // we know best_offset >=1, 
        // since foundGoodCorrelation cannot go to true until the second pass (offset=1), and 
        // we can't drop into this clause until the following pass (else if).
  //      var shift = (correlations[best_offset+1] - correlations[best_offset-1])/correlations[best_offset];  
   //     return sampleRate/(best_offset+(8*shift));
      }
      lastCorrelation = correlation;
    }
    if (best_correlation > 0.01) {
      // console.log("f = " + sampleRate/best_offset + "Hz (rms: " + rms + " confidence: " + best_correlation + ")")
      return sampleRate/best_offset;
    }
    return -1;
  //  var best_frequency = sampleRate/best_offset;
  },


  updatePitch: function(time) {
    this.analyser.getFloatTimeDomainData( this.buf );
    var ac = this.autoCorrelate( this.buf, this.audioContext.sampleRate );

    var note = false;
    var pitch = false;
    var noteString = "";
    var octave = false;
    if (ac == -1) {
    } else {
      pitch = ac;
      note =  this.noteFromPitch( pitch );
      octave = Math.floor(note/12);
      noteString = this.noteStrings[note%12];
    }
    $('#sidPitch').html(pitch + ',' + note + ',' + noteString);
  },





  findFundamentalFreq: function (buffer, sampleRate) {
    // We use Autocorrelation to find the fundamental frequency.

    // In order to correlate the signal with itself (hence the name of the algorithm), we will check two points 'k' frames away.
    // The autocorrelation index will be the average of these products. At the same time, we normalize the values.
    // Source: http://www.phy.mty.edu/~suits/autocorrelation.html
    // Assuming the sample rate is 48000Hz, a 'k' equal to 1000 would correspond to a 48Hz signal (48000/1000 = 48),
    // while a 'k' equal to 8 would correspond to a 6000Hz one, which is enough to cover most (if not all)
    // the notes we have in the notes.json file.
    var n = 1024;
    var bestK = -1;
    var bestR = 0;
    for (var k = 8; k <= 1000; k++) {
      var sum = 0;

      for (var i = 0; i < n; i++) {
        sum += ((buffer[i] - 128) / 128) * ((buffer[i + k] - 128) / 128);
      }

      var r = sum / (n + k);

      if (r > bestR) {
        bestR = r;
        bestK = k;
      }

      if (r > 0.9) {
        // Let's assume that this is good enough and stop right here
        break;
      }
    }

    if (bestR > 0.0025) {
      // The period (in frames) of the fundamental frequency is 'bestK'. Getting the frequency from there is trivial.
      var fundamentalFreq = sampleRate / bestK;
      return fundamentalFreq;
    }
    else {
      // We haven't found a good correlation
      return -1;
    }
  },

  findClosestNote: function (freq, notes) {
    // Use binary search to find the closest note
    var low = -1;
    var high = notes.length;
    while (high - low > 1) {
      var pivot = Math.round((low + high) / 2);
      if (notes[pivot].frequency <= freq) {
        low = pivot;
      } else {
        high = pivot;
      }
    }

    if (Math.abs(notes[high].frequency - freq) <= Math.abs(notes[low].frequency - freq)) {
      // notes[high] is closer to the frequency we found
      this.currentNote = high;
      return notes[high];
    }

    this.currentNote = low;
    return notes[low];
  },

  findCentsOffPitch: function (freq, refFreq) {
    // We need to find how far freq is from baseFreq in cents
    var log2 = 0.6931471805599453; // Math.log(2)
    var multiplicativeFactor = freq / refFreq;

    // We use Math.floor to get the integer part and ignore decimals
    var cents = Math.floor(1200 * (Math.log(multiplicativeFactor) / log2));
    return cents;
  },




  detectPitch: function(time) {
    if(!this.active) {
      return;
    }
    var buffer = new Uint8Array(this.analyser.fftSize);
    this.analyser.getByteTimeDomainData(buffer);

    var fundamentalFreq = this.findFundamentalFreq(buffer, this.audioContext.sampleRate);

    if (fundamentalFreq !== -1) {
      var note = this.findClosestNote(fundamentalFreq, this.notes["440"]);
      var cents = this.findCentsOffPitch(fundamentalFreq, note.frequency);

      var offset = parseInt($('#sidPitchDetectOffset').val());
      if(offset != 0) {
        this.currentNote += offset;
        if(this.currentNote >= 0 && this.currentNote < this.notes["440"].length) {
          note = this.notes["440"][this.currentNote];
        }
      }
      this.currentCentsOff = cents;
      this.currentFrequency = fundamentalFreq;
      this.currentNoteString = note.note;
//      updateNote(note.note);
//      updateCents(cents);
      $('#sidPitch').html(this.currentNoteString);
      $('#sidPitchCents').html(cents + ' cents');
      $('#sidPitchFrequency').html(fundamentalFreq);
    }
    else {
      $('#sidPitch').html("--");
      $('#sidPitchCents').html('--' + ' cents');
      $('#sidPitchFrequency').html('--');

      this.currentNote = -1;
      this.currentFrequency = -1;
      this.currentNoteString = "--";

//      updateNote('--');
//      updateCents(-50);
    }
/*

    this.analyser.getFloatTimeDomainData( this.buf );
    var ac = this.autoCorrelate( this.buf, this.audioContext.sampleRate );

    var note = false;
    var pitch = false;
    var noteString = "";
    var octave = false;
    if (ac == -1) {
    } else {
      pitch = ac;
      note =  this.noteFromPitch( pitch );
      octave = Math.floor(note/12);
      noteString = this.noteStrings[note%12];
    }
    $('#sidPitch').html(pitch + ',' + note + ',' + noteString);
    */
  },





}

var Notes = {};

Notes.centsOffFromPitch = function( frequency, noteFrequency ) {
    return Math.floor( 1200 * Math.log( frequency / noteFrequency )/Math.log(2) );
},

Notes.findClosestNote = function (freq) {
  var notes = Notes.notes["440"];
  // Use binary search to find the closest note
  var low = -1;
  var high = notes.length;
  while (high - low > 1) {
    var pivot = Math.round((low + high) / 2);
    if (notes[pivot].frequency <= freq) {
      low = pivot;
    } else {
      high = pivot;
    }
  }

  if(low < 0 || high < 0 || low > notes.length - 1 || high > notes.length - 1) {
    return { "note": "-", frequency: 0, index: 0 };
  }
//    console.log("low = " + low + "high = " + high);

  if (Math.abs(notes[high].frequency - freq) <= Math.abs(notes[low].frequency - freq)) {
    // notes[high] is closer to the frequency we found
    this.currentNote = high;
    notes[high].index = high;
    return notes[high];
  }

  this.currentNote = low;
  notes[low].index = low;
  return notes[low];
}


