  this.applyAccents = false;
  this.saveLoopCurrentPattern = false;

  this.patternDataBackup = [];

  this.bassPatterns = [
    {
      "name": "Bass pattern 1"
    },
    {
      "name": "Bass pattern 2"
    }
  ];
