var Oscilloscope = function() {
  this.visible = true;

  this.sampleCount = 800;
  this.track1 = null;

  this.width = 0;
  this.height = 0;
  this.left = 0;
  this.bottom = 0;

  this.waveformMeshes = [];
}

Oscilloscope.prototype = {
  init: function(music, channel, uiComponent) {

    this.music = music;
    this.channel = channel;
    this.canvas = uiComponent.getCanvas();
  },


  outputData: function(data) {
    if(!this.visible) {
      return;
    }
    this.width = Math.floor(this.canvas.width / this.music.doc.data.tracks.length);
    this.height = this.canvas.height;
    var xOffset = this.width * this.channel;

    this.context = this.canvas.getContext("2d");    

    var scaleY = 0.002;
    var dataWindowSize = data.length / 5.2;//2.8;

    this.context.fillStyle= styles.music.oscilloscopeBackground;
    this.context.fillRect(xOffset, 0, this.width, this.height);

    this.context.beginPath();    
    this.context.strokeStyle = styles.music.oscilloscopeLines;
    this.context.lineWidth = 2;

    if(data === false) {

      var x = xOffset;
      var y = this.height / 2;
      this.context.moveTo(x, y);
      this.context.lineTo(xOffset + this.width, y);
      this.context.stroke();
      return
    }  

    var triggerOffset = 0;
    while(data[triggerOffset] < 6000 && triggerOffset < 1000) {
      triggerOffset++;
    }
    while(data[triggerOffset] >= 5990 && triggerOffset < 1000) {
      triggerOffset++;
    }

    var sample = 0;
    var pos = Math.floor(triggerOffset + sample) % 2048;
    var x = xOffset;
    var y = this.height / 2 - data[pos] * scaleY;
    this.context.moveTo(x, y);


    var sampleStep = dataWindowSize / this.width;
    var midpoint = this.height / 2;

    for(var x = 1; x < this.width; x++) {
      sample += sampleStep;
      pos = Math.floor(triggerOffset + sample) % 2048;
      y = midpoint - data[pos] * scaleY;
      this.context.lineTo(xOffset + x, y);
    }
    this.context.stroke();
  },

  resize: function() {
    this.canvas.width = this.width;
    this.canvas.height = this.height;

    this.context = this.canvas.getContext("2d");    
  },
  render: function(left, bottom, width, height) {

    if(!this.visible) {
      return;
    }

    // reposition if needed
    if(this.left != left) {
      this.left = left;
      this.canvas.style.left = left + 'px';
    }

    if(this.bottom != bottom) {
      this.bottom = bottom;
      this.canvas.style.bottom =  bottom + 'px';
    }

    // resize if needed
    if(width != this.width || height != this.height) {
      this.width = width;
      this.height = height;
      this.resize();
    }

  }
}


var HistoryGraph = function() {
  this.visible = false;
  this.segments = 512;
  this.maximumValue = 0xff;
  this.data = [];
  this.waveformMeshes = [];
  this.historyLine = null;
  this.cursor = 0;

  this.canvas = null;
  this.context = null;

  this.width = 10;
  this.height = 10;
  this.left = 0;
  this.bottom = 0;

}

HistoryGraph.prototype = {

  init: function(music, args) {
    if(typeof args != 'undefined') {
      if(typeof args.max != 'undefined') {
        this.maximumValue = args.max;
      }
      if(typeof args.segments != 'undefined') {
        this.segments = args.segments;
      }

    }

    this.music = music;

return;
//TODO: !!!

    this.canvas = document.createElement('canvas');
    document.body.appendChild(this.canvas);
    this.canvas.style.zIndex = 100;
    this.canvas.style.position = 'absolute';
    this.canvas.style.display = 'none';
    this.canvas.className += ' historyGraph';
    this.resize();

    for(var i = 0; i < this.segments; i++) {
      this.data.push(0);
    }
  },

  setVisible: function(visible) {
    if(visible != this.visible) {
      this.visible = visible;
      if(visible) {
        this.canvas.style.display = 'block';
      } else {
        this.canvas.style.display = 'none';

      }
    }
  },

  setMaximumValue: function(maximumValue) {
    this.maximumValue = maximumValue;
  },



  addValue: function(value) {
    this.data[this.cursor++] = value;
    if(this.cursor >= this.segments) {
      this.cursor = 0;
    }

  },  

  outputData: function() {
    if(!this.visible) {
      return;
    }

    this.context.fillStyle= '#060606';
    this.context.fillRect(0, 0, this.width, this.height);

    this.context.beginPath();    
    this.context.strokeStyle = '#e6e6e6';    


    var scaleY = 1;
    var scaleX = this.width / this.segments;

    var drawAt = this.segments ;//Math.floor(this.segments / 2);
    var cursor = this.cursor - drawAt;
    if(cursor < 0) {
      cursor += this.segments;
    }

    var x = 0;
    var y = this.height - scaleY * (this.data[cursor++]  / this.maximumValue * this.height);

    this.context.moveTo(x, y);

    for(var i = 1; i < drawAt; i++) {
      var x = i * scaleX;
      var y = this.height - scaleY * (this.data[cursor++]  / this.maximumValue * this.height);

      this.context.lineTo(x, y);

      if(cursor >= this.segments) {
        cursor = 0;
      }
    }

    for(var i = drawAt; i < this.segments; i++) {
      console.log("HEREEEEE!!!");
      var x = i * scaleX;
      var y = this.height - 0;

      this.context.lineTo(x, y);
    }

    this.context.lineWidth = 2;
    this.context.stroke();

  },





  resize: function() {
    this.canvas.width = this.width;
    this.canvas.height = this.height;

    this.context = this.canvas.getContext("2d");    
  },  

  render: function(left, bottom, width, height) {

    if(!this.visible) {
      return;
    }


    // reposition if needed
    if(this.left != left) {
      this.left = left;
      this.canvas.style.left = left + 'px';
    }

    if(this.bottom != bottom) {
      this.bottom = bottom;
      this.canvas.style.bottom =  bottom + 'px';
    }

    // resize if needed
    if(width != this.width || height != this.height) {
      this.width = width;
      this.height = height;
      this.resize();
    }

  }
}

