 this.setMemory = function(data, subt, speed) {

  if(typeof speed == 'undefined') {
    speed = 1;
  }

  loaded=0; 
  this.pause(); 
  initSID(); 
  subtune=subt; //stop playback before loading new tune

  loadaddr = 0x1000;
  initaddr = 0x1000;
  playaddr = 0x1003;
  playaddf = 0x1003;
  subtune_amount= 1;
  for (i=0; i<32; i++) {
    timermode[31-i] = 0;
  }
  for(i=0;i<memory.length;i++) {
    memory[i]=0;
  }
  for(var i = 0x1000; i < data.length; i++) {
    memory[i] = data[i];
  }

  preferred_SID_model[0] = 8580;//: 6581; 
  SIDamount=1;
  loaded=1;  
  init(subtune, speed); 
      console.log('frame sample period ==== ' +frame_sampleperiod);

 }

 this.initFromData = function(filedata) {
   var i,strend, offs=filedata[7]; 

   loadaddr=filedata[8]+filedata[9]? filedata[8]*256+filedata[9] : filedata[offs]+filedata[offs+1]*256;
   for (i=0; i<32; i++) {
     timermode[31-i] = filedata[0x12+(i>>3)] & Math.pow(2,7-i%8); 
   }

//   console.log(timermode);

   for(i=0;i<memory.length;i++) {
     memory[i]=0;
   }

   for (i=offs+2; i<filedata.byteLength; i++) { 
     if (loadaddr+i-(offs+2)<memory.length) 
       memory[loadaddr+i-(offs+2)]=filedata[i]; 
   } 

   strend=1; 
   for(i=0; i<32; i++) { 
    if(strend!=0) 
      strend=SIDtitle[i]=filedata[0x16+i]; else strend=SIDtitle[i]=0; 
   } 
   strend=1; 
   for(i=0; i<32; i++) { if(strend!=0) strend=SIDauthor[i]=filedata[0x36+i]; else strend=SIDauthor[i]=0; } 
   strend=1; for(i=0; i<32; i++) { if(strend!=0) strend=SIDinfo[i]=filedata[0x56+i]; else strend=SIDinfo[i]=0; } 
   initaddr=filedata[0xA]+filedata[0xB]? filedata[0xA]*256+filedata[0xB] : loadaddr; 
   playaddr=playaddf=filedata[0xC]*256+filedata[0xD]; 
   subtune_amount=filedata[0xF]; 

   console.log('subtune amounr = ' + subtune_amount);

   preferred_SID_model[0] = (filedata[0x77]&0x30)>=0x20? 8580 : 6581; 
   preferred_SID_model[1] = (filedata[0x77]&0xC0)>=0x80 ? 8580 : 6581; 
   preferred_SID_model[2] = (filedata[0x76]&3)>=3 ? 8580 : 6581; 
   SID_address[1] = filedata[0x7A]>=0x42 && (filedata[0x7A]<0x80 || filedata[0x7A]>=0xE0) ? 0xD000+filedata[0x7A]*16 : 0;
   SID_address[2] = filedata[0x7B]>=0x42 && (filedata[0x7B]<0x80 || filedata[0x7B]>=0xE0) ? 0xD000+filedata[0x7B]*16 : 0;
   SIDamount=1+(SID_address[1]>0)+(SID_address[2]>0);
   loaded=1;  if (loadcallback!==null) loadcallback(); 

   init(subtune); 

 }



