var audioContext = null;
var scriptNode = null;

var SidPlayer2 = function() {
  this.music = null;

  this.musicPlayer = null;
  this.instrumentPlayer = null;
  this.bufferLength = 2048 * 2;//4096;

  this.exportGoatTracker = null;
  this.exportSID = null;
}


SidPlayer2.prototype = {

  init: function(music) {
    this.music = music;

    this.musicPlayer = new SidPatternPlayer();
    this.musicPlayer.init(music);

    this.instrumentPlayer = new SidPatternPlayer();
    this.instrumentPlayer.init(music);

    this.songData = new SongData();
    this.songData.init();

  },

  setupAudioContext: function() {
    if(audioContext != null) {
      return;
    }

    audioContext = null;
    if ( typeof AudioContext !== 'undefined') { 
      audioContext = new AudioContext(); 
    } else { 
      audioContext = new webkitAudioContext(); 
    }

    this.musicPlayer.setup(audioContext.sampleRate, this.bufferLength);
    this.instrumentPlayer.setup(audioContext.sampleRate, this.bufferLength);

    scriptNode = null;

    // createJavaScriptNode is obsolete, renamed to createScriptProcessor
    // createScriptProcessor is to be replaced by AudioWorklet
    // var scriptProcessor = audioCtx.createScriptProcessor(bufferSize, numberOfInputChannels, numberOfOutputChannels);
    if (typeof audioContext.createJavaScriptNode === 'function') { 
      scriptNode = audioContext.createJavaScriptNode(this.bufferLength,0,1); 
    } else { 
      scriptNode = audioContext.createScriptProcessor(this.bufferLength,0,1); 
    }

    var _this = this;
    scriptNode.onaudioprocess = function(e) { 
      var outBuffer = e.outputBuffer; 
      var outData = outBuffer.getChannelData(0); 

      _this.musicPlayer.sid.resetChannelDataPos();
      _this.instrumentPlayer.sid.resetChannelDataPos();


      if(_this.musicPlayer.playing && !_this.instrumentPlayer.playing) {
        var sample = 0;
        for (sample = 0; sample < outBuffer.length; sample++) { 
          outData[sample] = _this.musicPlayer.nextSample();
        }                 
      } else if( (!_this.musicPlayer.playing) && _this.instrumentPlayer.playing) {
        for (var sample = 0; sample < outBuffer.length; sample++) { 
          outData[sample] = _this.instrumentPlayer.nextSample();
        }                 
      } else if(_this.musicPlayer.playing && _this.instrumentPlayer.playing) {
        for (var sample = 0; sample < outBuffer.length; sample++) { 
          outData[sample] = _this.musicPlayer.nextSample() + _this.instrumentPlayer.nextSample();
        }                 
      } else {
        for (var sample = 0; sample < outBuffer.length; sample++) { 
          outData[sample] = 0;
        }
      }

      /*
      outData[]
      if(_this.playing) {
        for (var sample = 0; sample < outBuffer.length; sample++) { 
          outData[sample] = _this.nextSample();//Math.sin(sample / 2);// SIDplayer.play(); 
        }         
      } else {
        for (var sample = 0; sample < outBuffer.length; sample++) { 
          outData[sample] = 0;
        }         
      }
      */
    }

    if(!UI.isMobile) {
      this.tuna = new Tuna(audioContext);

      this.convolver = new this.tuna.Convolver({
          highCut: 22050,                         //20 to 22050
          lowCut: 20,                             //20 to 22050
          dryLevel: 0.8,                            //0 to 1+
          wetLevel: 0.7,                            //0 to 1+
          level: 1,                               //0 to 1+, adjusts total output of both wet and dry
          impulse: "impulses/impulse_rev.wav",    //the path to your impulse response
          bypass: 0
      });  

      this.chorus = new this.tuna.Chorus({
          rate: 1.5,         //0.01 to 8+
          feedback: 0.2,     //0 to 1+
          delay: 0.0045,     //0 to 1
          bypass: 1          //the value 1 starts the effect as bypassed, 0 or 1
      });


      this.overdrive = new this.tuna.Overdrive({
          outputGain: 0.1,         //0 to 1+
          drive: 0.7,              //0 to 1
          curveAmount: 1,          //0 to 1
          algorithmIndex: 0,       //0 to 5, selects one of our drive algorithms
          bypass: 1
      });


      this.filter = new this.tuna.Filter({
        frequency: 440, // 20 to 22050
        Q: 1, // 0.001 to 100
        gain: 0, // -40 to 40
        b5: "lowpass", //lowpass, highpass, bandpass, lowshelf, highshelf, peaking
        bypass: 0
      });

      this.cabinet = new this.tuna.Cabinet({
        makeupGain: 1,
        impulsePath: "impulses/impulse_guitar.wav", // path to speaker impulse
        bypass: 0
      });

      this.moog = new this.tuna.MoogFilter({
        cutoff: 0.765, // 0 to 1
        resonance: 0.5, // 0 to 4

        /*
        cutoff: 0.065, // 0 to 1
        resonance: 3.5, // 0 to 4
        */
        bufferSize: 4096 // 256 to 16384
      });

      this.convolver.wetLevel = 0;

/*
      scriptNode.connect(this.overdrive);
      this.overdrive.connect(this.chorus);
      this.chorus.connect(this.convolver);

      //jsSID_scriptNode.connect(this.convolver);
      this.convolver.connect(audioContext.destination);
*/
      scriptNode.connect(this.moog);
      this.moog.connect(audioContext.destination);      
    } else {
      scriptNode.connect(audioContext.destination);    
    }
  },

  setPlayheadPosition: function(position) {
    return this.musicPlayer.setPlayheadPosition(position);
  },

  getPlayheadPosition: function() {
    return this.musicPlayer.getPlayheadPosition();
  },


  setMute: function(channel, mute) {
    this.musicPlayer.setMute(channel, mute);
  },

  getMute: function(channel) {
    return this.musicPlayer.getMute(channel);
  },

  getPlayheadPositionFraction: function() {
    var tick = this.musicPlayer.getTick();
    var tempo = this.musicPlayer.getTempo();

    return tick / (tempo + 1);

  },

  getInstrumentChannelData: function() {
    return this.instrumentPlayer.getChannelData();
  },
  getChannelData: function() {

    return this.musicPlayer.getChannelData();
  },

  isPlayingInstrument: function() {
    return this.instrumentPlayer.isPlaying();
  },
  
  isPlaying: function() {
    return this.musicPlayer.isPlaying();
  },

  play: function(startAtPosition) {
    this.musicPlayer.play(startAtPosition);
  },

  stop: function() {
    this.musicPlayer.stop();
  },

  playTestInstrument: function(pitch, instrument, ch) {
    this.setupAudioContext();
    this.instrumentPlayer.playTestInstrument(pitch, instrument, ch);
  },

  stopTestInstrument: function() {
    this.instrumentPlayer.stopTestInstrument();
  },

  getBlankPatternData: function(duration) {

    if(duration == 0) {
      return;
    }
    var patternData = [];

    for(var i = 0; i < duration; i++) {
      patternData.push(0xbe);
      patternData.push(0);
      patternData.push(0);
      patternData.push(0);

    }

    return patternData;
  },

  getC64PatternData: function(patternId) {
    this.maxc64PatternLength = 64;

    //var patternData = this.music.patterns.getPatternData(patternId);
    var patternData = [];

    var notes = this.music.patterns.getNotes(patternId);
    var patternDuration = this.music.patterns.getDuration(patternId);

    // initialise pattern data
    var patternData = [];
    for(var i = 0; i < patternDuration; i++) {
      patternData.push({
        instrument: 0,
        start: false,
        duration: 0,
        pitch: 0,
        effect: 0,
        effectParam: 0,
        effectParam2: 0        
      });
    }

    // fill in pattern data with the instruments
    for(var i = 0; i < notes.length; i++) {
      var note = notes[i];
      for(var j = note.pos; j < note.pos+note.dur; j++) {

        if(j < patternData.length) {
          patternData[j].instrument = note.ins;
          patternData[j].start = j == note.pos;
          patternData[j].duration = note.dur;
          patternData[j].pitch = note.pit;
        }
      }
    }

    var effects = this.music.patterns.getParams(patternId, "effects");

    for(var i = 0; i < effects.length; i++) {
      var position = effects[i].pos;
      if(position < patternData.length) {
        patternData[position].effect = effects[i].values.effect;
        patternData[position].effectParam = effects[i].values.value1;
        patternData[position].effectParam2 = effects[i].values.value2;
      }

    }

    var c64PatternData = [];
    var c64Patterns = [];

    var lastInstrument = -1;
    var currentInstrument = 0;
    var i = 0;

    var startPosition = 0;

    while(i < patternData.length) {

      var instrument = parseInt(patternData[i].instrument);

      var pitch = 0;
      var duration = 0;   
      if(instrument == 0) {
        // silence
        var totalDuration = 0;
        var first = true;
        lastInstrument = 0;

        while(i < patternData.length && patternData[i].instrument == 0) {
          var effect = 0;
          var effectParam = 0;
          if(patternData[i].effect) {
            effect = parseInt(patternData[i].effect);
            effectParam = parseInt(patternData[i].effectParam);
            effectParam2 = parseInt(patternData[i].effectParam2);

            if(effect == 16) {
              // cant have legato here
              effect = 11;
              effectParam = 0;
              effectParam2 = 0;
            }

            if(effect == 17) {
              // cant have legato here
              effect = 0;
            }
          }

          i++;
          totalDuration++;

          if(first) {
            c64PatternData.push(0xbe);
          } else {
            c64PatternData.push(0xbd);
          }
          c64PatternData.push(0x00);

          c64PatternData.push(effect);
          c64PatternData.push(effectParam);

          if(c64PatternData.length >= this.maxc64PatternLength * 4) {
            // length has gone over the max allowed, split this up into multiple patterns
//            patternData.push(0xff);
//            patternData.push(0x00);
//            patternData.push(0x00);
//            patternData.push(0x00);    
            c64Patterns.push(c64PatternData);
            c64PatternData = [];
          }


        }


      } else if(patternData[i].start) {

        // note start
        var totalDuration = patternData[i].duration;

        var effect = 0;
        var effectParam = 0;
        var effectParam2 = 0;
        pitch = patternData[i].pitch;

        if(patternData[i].effect) {
          effect = parseInt(patternData[i].effect);
          effectParam = parseInt(patternData[i].effectParam);
          effectParam2 = parseInt(patternData[i].effectParam2);

/*
          if(effect == 4) {  // vibrato, need to stick these in speed table
            effectParam = effectParam2 + (effectParam << 8);
          }
          if(effect == 14) {  // funktempo, need to stick these in speed table
            effectParam = effectParam2 + (effectParam << 8);
          }
*/          

          if(effect == 16) {
            // stop filter
            effect = 11;
            effectParam = 0;
            effectParam2 = 0;
          }


          if(effect == 17) {
            if(lastInstrument == instrument) {
              // can only do legato if last instrument was same
              effect = 3;
              effectParam = 0;
              effectParam2 = pitch;
            } else {
              effect = 0;
            }
          }
        }

        i++;

//        i += totalDuration;
/*
                1st byte: Notenumber
                          Values $60-$BC are the notes C-0 - G#7
                          Value $BD is rest
                          Value $BE is keyoff
                          Value $BF is keyon
                          Value $FF is pattern end
*/
        if(effect == 3) {
          //portamento to effect
          c64PatternData.push(effectParam2 + 0x60);
        } else {
          c64PatternData.push(pitch + 0x60);
        }
        c64PatternData.push(instrument);
        c64PatternData.push(effect);
        c64PatternData.push(effectParam);

//        patternData.push(0x00);
//        patternData.push(0x00);
        totalDuration--;

        if(c64PatternData.length >= this.maxc64PatternLength * 4) {
          // length has gone over the max allowed, split this up into multiple patterns
/*
          patternData.push(0xff);
          patternData.push(0x00);
          patternData.push(0x00);
          patternData.push(0x00);    
*/          
          c64Patterns.push(c64PatternData);
          c64PatternData = [];
        }


        lastInstrument = instrument;

        while(totalDuration >0){

          var effect = 0;
          var effectParam = 0;
          var effectParam2 = 0;
          if(patternData[i].effect) {
            effect = parseInt(patternData[i].effect);
            effectParam = parseInt(patternData[i].effectParam);
            effectParam2 = parseInt(patternData[i].effectParam2);

/*
            if(effect == 4) {  // vibrato, need to stick these in speed table
              effectParam = effectParam2 + (effectParam << 8);
            }

            if(effect == 14) {  // funktempo, need to stick these in speed table
              effectParam = effectParam2 + (effectParam << 8);
            }
*/
            if(effect == 16) {
              // stop filter
              effect = 11;
              effectParam = 0;
              effectParam2 = 0;
            }

            if(effect == 17) {
              // cant have legato here
              effect = 0;
            }
          }

          if(effect == 3) {
            //portamento to effect
            c64PatternData.push(effectParam2 + 0x60);
          } else {
            c64PatternData.push(0xbd);
          }
          c64PatternData.push(0x00);
          c64PatternData.push(effect);
          c64PatternData.push(effectParam);
//          patternData.push(0x00);
//          patternData.push(0x00);
          totalDuration--;          
          i++;

          if(c64PatternData.length >= this.maxc64PatternLength * 4) {
            // length has gone over the max allowed, split this up into multiple patterns
/*            
            patternData.push(0xff);
            patternData.push(0x00);
            patternData.push(0x00);
            patternData.push(0x00);    
*/            
            c64Patterns.push(c64PatternData);
            c64PatternData = [];
          }


        }

      } else {
        c64PatternData.push(0xbd);
        c64PatternData.push(0x00);
        c64PatternData.push(0x00);
        c64PatternData.push(0x00);

        i++;
        totalDuration++;

      }

         
    }

    if(c64PatternData.length > 0) {
/*      
      patternData.push(0xff);
      patternData.push(0x00);
      patternData.push(0x00);
      patternData.push(0x00);    
*/      
      c64Patterns.push(c64PatternData);
    }
    return c64Patterns;
  },

  exportAsType: function(type) {
    switch(type) {
      case 'goattracker':
//        this.createSid();
//        this.songData.downloadGoat('untitled', 'title', 'author', 'released');
        if(this.exportGoatTracker == null) {
          this.exportGoatTracker = new ExportGoatTracker();
          this.exportGoatTracker.init(this);
        }

        this.exportGoatTracker.start();

      break;
      case 'prg':
        if(this.exportPRG == null) {
          this.exportPRG = new ExportSIDPRG();
          this.exportPRG.init(this);
        }

        this.exportPRG.start();
      break;
      case 'sid':

        if(this.exportSID == null) {
          this.exportSID = new ExportSID();
          this.exportSID.init(this);
        }

        this.exportSID.start();
  
//        this.createSid();
//        this.songData.downloadSID('untitled', 'title', 'author', 'released');
      break;
      case 'wav':
      break;
    }

  },

  createSid: function() {
    this.songData.patterns = [];

    this.c64PatternMap = [];
    this.patternMap = [];

    var tracks = this.music.doc.data.tracks;

    // get the length of the song (max track length)
    var songLength = 0;
    for(var i = 0; i < tracks.length; i++) {
      var trackId = tracks[i].trackId;
      var trackLength = this.music.tracks.getLength(trackId);
      if(trackLength > songLength) {
        songLength = trackLength;
      }
    }

    var patternCount = this.music.patterns.getPatternCount();
    for(var i = 0; i < patternCount; i++) {
      var patternId = this.music.patterns.getPatternId(i);      
      var patternDuration = this.music.patterns.getDuration(patternId);

      // split the pattern up into patterns of max length 64
      // convert patterns into an array of bytes
      var patternData = this.getC64PatternData(patternId);

      this.patternMap[i] = [];

      var offset = 0;

      // each pattern might be made up of 1 or more c64 patters (max length 64)
      for(var j = 0; j < patternData.length; j++) {
        this.patternMap[i].push(this.songData.patterns.length);
        this.c64PatternMap.push({ "pattern": i, "offset": offset, "length": patternData[j].length });

        this.songData.patterns.push(patternData[j]);
        offset += patternData[j].length / 4;
      }
    }

    var blankPatternMap = {};

    // make empty patterns to space out the tracks
    for(var i = 0; i < this.music.doc.data.tracks.length; i++) {
      var patternInstances = this.music.doc.data.tracks[i].patternInstances;

      var lastPosition = 0;
      for(var j = 0; j < patternInstances.length; j++) {
        var patternInstanceStart = patternInstances[j].position;
        var patternId = patternInstances[j].patternId;
        var patternInstanceEnd = patternInstanceStart + this.music.patterns.getDuration(patternId) ;

        var gap = patternInstanceStart - lastPosition;
        lastPosition = patternInstanceEnd;

        if(gap > 64) {
          var extraGap = gap % 64;

          if(typeof blankPatternMap[64] == 'undefined') {
            var blankData = this.getBlankPatternData(64);
            var blankIndex = this.songData.patterns.length;
            this.songData.patterns.push(blankData);

            blankPatternMap[64] = blankIndex;
          }

          if(extraGap > 0 && typeof blankPatternMap[extraGap] == 'undefined') {
            var blankData = this.getBlankPatternData(extraGap);
            var blankIndex = this.songData.patterns.length;
            this.songData.patterns.push(blankData);

            blankPatternMap[extraGap] = blankIndex;
          }
        } else {
          if(gap != 0 && typeof blankPatternMap[gap] == 'undefined') {
            var blankData = this.getBlankPatternData(gap);
            var blankIndex = this.songData.patterns.length;
            this.songData.patterns.push(blankData);

            blankPatternMap[gap] = blankIndex;
          }
        }
      }


      var gapAtEnd = songLength - lastPosition;
      if(gapAtEnd > 64) {
        var extraGap = gapAtEnd % 64;

        if(typeof blankPatternMap[64] == 'undefined') {
          var blankData = this.getBlankPatternData(64);
          var blankIndex = this.songData.patterns.length;
          this.songData.patterns.push(blankData);

          blankPatternMap[64] = blankIndex;
        }

        if(extraGap > 0 && typeof blankPatternMap[extraGap] == 'undefined') {
          var blankData = this.getBlankPatternData(extraGap);
          var blankIndex = this.songData.patterns.length;
          this.songData.patterns.push(blankData);

          blankPatternMap[extraGap] = blankIndex;
        }
      } else {
        if(gapAtEnd != 0 && typeof blankPatternMap[gapAtEnd] == 'undefined') {
          var blankData = this.getBlankPatternData(gapAtEnd);
          var blankIndex = this.songData.patterns.length;
          this.songData.patterns.push(blankData);

          blankPatternMap[gapAtEnd] = blankIndex;
        }

      }
    }



    this.songData.tracks = [];
    for(var i = 0; i < this.music.doc.data.tracks.length; i++) {
      var patternInstances = this.music.doc.data.tracks[i].patternInstances;

//      this.a8Map[i] = [];

      var trackPatterns = [];

      var lastPosition = 0;
      for(var j = 0; j < patternInstances.length; j++) {
        var patternInstanceStart = patternInstances[j].position;
        var patternId = patternInstances[j].patternId;
        var patternInstanceEnd = patternInstanceStart + this.music.patterns.getDuration(patternId) ;

        var gap = patternInstanceStart - lastPosition;
        lastPosition = patternInstanceEnd;

        var blank64Count = Math.floor(gap / 64);
        var blankRemaining = gap % 64;
        for(var k = 0; k < blank64Count; k++) {
          var blankIndex = blankPatternMap[64];
          trackPatterns.push(blankIndex);
        }

        if(blankRemaining > 0) {
          var blankIndex = blankPatternMap[blankRemaining];
          trackPatterns.push(blankIndex);
        }

        var patterns = this.patternMap[patternInstances[j].patternId];

        for(var k = 0; k < patterns.length; k++) {
          trackPatterns.push(patterns[k]);
//          this.a8Map[i].push(j);
        }
      }

      var gapAtEnd = songLength - lastPosition;
      var blank64Count = Math.floor(gapAtEnd / 64);
      var blankRemaining = gapAtEnd % 64;
      for(var k = 0; k < blank64Count; k++) {
        var blankIndex = blankPatternMap[64];
        trackPatterns.push(blankIndex);
      }

      if(blankRemaining > 0) {
        var blankIndex = blankPatternMap[blankRemaining];
        trackPatterns.push(blankIndex);
      }

      
      this.songData.tracks.push(trackPatterns);
    }


    this.songData.instruments = [];
    for(var i = 1; i < this.music.doc.data.instruments.length; i++) {
      this.songData.instruments.push(this.music.instruments.getInstrument(i));
    }

    this.songData.filters = [];
    for(var i = 1; i < this.music.doc.data.filters.length; i++) {
      this.songData.filters.push(this.music.doc.data.filters[i]);
    }

    return this.songData.writeSid();


  }
}


var g_tick = 0;

// prob not the best name, but can't think of anything better
var SidPatternPlayer = function() {
  this.music = null;

  this.playing = false;

  this.channels = [];
  this.channelCount = 3;

  this.b5 = 0;
  this.filterCommand = 0;
  this.a0 = 0;

  this.b9 = [6, 6];

  this.sampleRate = 0;

  this.sid = null;
  this.c2 = null;


  this.framecnt = 0;
//  this.finished = 1;
  this.a4 = 0x0f00;

  this.playheadPosition = 0;
  this.newPlayheadPosition = 0;

  this.testInstrument = null;

  this.testInstrumentChannel = false;

}

SidPatternPlayer.prototype = {
  init: function(music) {
    this.music = music;
    this.initChannels();    
  },

  initChannels: function() {
    this.channels = [];

    for(var i = 0; i < this.channelCount; i++) {
      var channel = {};
      channel.instrument = 1;
      channel.mute = false;
      this.channels.push(channel);
    }
  },

  setMute: function(channel, mute) {
    //this.sid.setMute(channel, mute);
    this.channels[channel].mute = mute;
  },

  getMute: function(channel) {
    return this.channels[channel].mute;
   // return this.sid.getMute(channel);
  },

  setup: function(sampleRate, bufferLength) {

    this.sampleRate = sampleRate;
    this.bufferLength = bufferLength;
    var factor = 1;
    var speed = 1;

    // CIA Timer clock rate 0.985248MHz (PAL) 

    this.C64_PAL_CPUCLK = 985248 * factor; //Hz
    this.PAL_FRAMERATE = 50 * factor; //NTSC_FRAMERATE = 60;
    this.clk_ratio = this.C64_PAL_CPUCLK / this.sampleRate;

    this.sid = new jsSID2(bufferLength, 0.0005, this.sampleRate);
    this.c2 = this.sid.getMemory();



    // number of samples per frame
    this.frame_sampleperiod = this.sampleRate / (this.PAL_FRAMERATE * speed); //Vsync timing



    this.c9 = 0xD400;

    this.debugData = [];
    this.lastTime = getTimestamp();
    this.sampleCount = 0;
    this.lastCalledPlay = 0;
  },

  nextSample: function() {
/*
    var time = getTimestamp();
    var timeDiff = time - this.lastTime;
    this.debugData.push(timeDiff);
    this.lastTime = time;
*/  
    this.sampleCount++;
    // framecnt is number of samples per frame.
    this.framecnt--; 
    if(this.framecnt <= 0) { 
      this.framecnt = this.frame_sampleperiod; 
      this.playRoutine();
    }

    /*
      this.finished = 0; 
    }

    if(this.finished == 0) {
      // tick..
      this.playRoutine();
      this.finished = 1;
    }

    */

/*
    this.debugData.push([
      this.c2[this.c9 + 0x0],
      this.c2[this.c9 + 0x1],
      this.c2[this.c9 + 0x2],
      this.c2[this.c9 + 0x3],
      this.c2[this.c9 + 0x4],
      this.c2[this.c9 + 0x5],
      this.c2[this.c9 + 0x6]    
    ]);
*/

    return this.sid.play();
  },

  getPlayheadPosition: function() {
    var position =  this.playheadPosition;// - 2;
    if(position < 0) {
      return 0;
    }

    return position;
  },

  getTick: function() {

    if(this.channels.length == 0) {
      return 0;
    }

    return this.channels[0].tick;
  },

  getTempo: function() {
    if(this.channels.length == 0) {
      return 0;
    }
    return this.channels[0].tempo;
  },
  /*
  getPlayheadPositionPositionFraction: function() {
    var position = ((this.channel[0].tempo - 1) - this.channel[0].tick) / (this.channel[0].tempo - 1);
  }
  */

  getChannelData: function() {

    return this.sid.getData();
  },
  isPlaying: function() {
    return this.playing;
  },
  play: function(startAtPosition) {

    this.debugData = [];
    this.startSong(startAtPosition);
    this.playing = true;
  },

  stop: function() {
    this.playing = false;
//    var data = JSON.stringify(this.debugData);
//    download(data, "test.json", "application/json");
  },



  setPlayheadPosition: function(globalPosition) {

    // find pattern number, pattern position for each channel
    for(var ch = 0; ch < 3; ch++) {
      if(ch < this.music.doc.data.tracks.length) {
        var chPatternNumber = 0;
        var chPatternPosition = 0;
        var position = 0;

        var patternId = this.music.tracks.getPatternAt(ch, globalPosition);

        this.channels[ch].a8 = globalPosition;
        this.channels[ch].patternPosition = this.music.tracks.getPatternPositionAt(ch, globalPosition);        
      }
    }

    this.playheadPosition = globalPosition;//- 2;
    this.newPlayheadPosition = globalPosition;
  },

  playTestInstrument: function(pitch, instrument, ch) {

//return;
//    this.setupAudioContext();


    this.startSong();

    this.testInstrumentChannel = ch;

    if(typeof this.testInstrumentChannel == 'undefined') {
      this.testInstrumentChannel = 0;
    }


    this.testInstrument = instrument;
    this.channels[this.testInstrumentChannel].newNote = pitch + 0x60;

    if(this.testInstrument.gateTimer & 0x40) {
      this.channels[this.testInstrumentChannel].gate = 0xfe; // Keyoff
      if (!(instrument.gateTimer & 0x80))
      {
        this.c2[this.c9 + 0x5 + this.testInstrumentChannel * 7] = this.a4 >> 8; // Hardrestart
        this.c2[this.c9 + 0x6 + this.testInstrumentChannel * 7] = this.a4 & 0xff;
      }
    }

    this.channels[this.testInstrumentChannel].gate = 0xff;
    this.channels[this.testInstrumentChannel].tick = 1;

//    this.channels[channel].tick = (this.testInstrument.gateTimer & 0x3f)+1;
//    this.channels[channel].gateTimer = this.testInstrument.gateTimer & 0x3f;

    this.playing = true;
    this.b2 = 0xf;

  },

  stopTestInstrument: function() {
    // todo, should prob stop playing as well at some point
    if(this.testInstrumentChannel !== false) {
      this.channels[this.testInstrumentChannel].gate = 0xfe;
    }
  },



  startSong: function(startAtPosition) {
    if(typeof startAtPosition == 'undefined') {
      startAtPosition = 0;
    }

    var multiplier = 1;

    this.playheadPosition = 0;

    this.sid.initSID();
    for(var i = 0; i < this.channelCount; i++) {

      // reset the sid chip..
      this.c2[this.c9 + 0x0 + 7*i] = 0;
      this.c2[this.c9 + 0x1 + 7*i] = 0;
      this.c2[this.c9 + 0x2 + 7*i] = 0;
      this.c2[this.c9 + 0x3 + 7*i] = 0;
      this.c2[this.c9 + 0x4 + 7*i] = 0;
      this.c2[this.c9 + 0x5 + 7*i] = 0;
      this.c2[this.c9 + 0x6 + 7*i] = 0;


//      this.channels[i].songptr = 0;

      // position in channel's track
      this.channels[i].a8 = 0;

      // position in current pattern
      this.channels[i].patternPosition = 0;

      // next note from the pattern
      this.channels[i].newNote = 0;


//      this.channels[i].noteStart = false;

      // the number of ticks before note start that note fetch, gate off happen
      // usually set to 2
      this.channels[i].gateTimer = this.music.instruments.getInstrument(1).gateTimer & 0x3f;
      this.channels[i].gate = 0xfe;

      // current
      this.channels[i].command = 0;
      this.channels[i].b3 = 0;

      // new command and new command data are set when tick is equal to gate timer
      // copied over on tick = 0
      this.channels[i].b6 = 0;
      this.channels[i].a6 = 0;

      this.channels[i].instrument = 0;
      this.channels[i].a2 = 0;


//      this.channels[i].advance = 1;

      // wave settings for the channel
      this.channels[i].wave = 0;
      this.channels[i].c4 = 0;
      this.channels[i].a3 = 0;

      // pulse settings for the channel
      this.channels[i].pulse = 0;
      this.channels[i].b7 = 0;
      this.channels[i].a1 = 0;


      this.channels[i].speedtablePosition = 0;


      this.channels[i].c8 = 0;
      this.channels[i].c3 = 0;
      this.channels[i].c6 = 0;
      this.channels[i].c7 = 0;

//      this.channels[i].ptr[0] = 0;
//      this.channels[i].repeat = 0;

      this.channels[i].tempo = this.music.getTempo() - 1;

      // tick counts down from tempo - 1 to zero
      this.channels[i].tick = this.channels[i].tempo - 1;

      this.channels[i].finished = false;


    }

    this.b1 = 0;
    this.a7 = 0;
    this.b5 = 0;

    this.a0 = 0;
    this.filtertable = [];
    this.filterTime = 0;

    this.b2 = 0xf;

    this.testInstrument = null;

    this.setPlayheadPosition(startAtPosition);

  },


/*
tick starts at tempo and counts down

on tick = gatetimer, 
- get the next note, put into new note,
- turn gate off, set adsr for current instrument to hard restart values

on tick 0, 
- new note is copied to current note, 
- gate is turned on
- wave table, filter table, pulse table, etc is set
- wave exec doesn't happen
*/
  playRoutine: function() {


    // first process filter table
    if(this.a0 > 0 && this.a0 <= this.filtertable.length 
      && this.filtertable[this.a0 - 1][0] == 0xff) {
      // filter table jump
      this.a0 = this.filtertable[this.a0 - 1][1];
    }


    if(this.a0 && this.a0 <= this.filtertable.length) {
      var filterLeft = (this.filtertable[this.a0 - 1][0] & 0xff);
      var filterRight = (this.filtertable[this.a0 - 1][1] & 0xff);


//      not sure what this is..
//      if(filterLeft > 0x80) {
//        filterLeft = ((filterLeft & 0x70) >> 1) | 0x80;
//      }      


      if(this.filterTime == 0) {
        // Filter set
        if (filterLeft >= 0x80)
        {
          this.b5 = filterLeft & 0x70;
          this.a7 = filterRight;
          this.a0++;

          // Can be combined with cutoff set
          if (this.a0 < this.filtertable.length && this.filtertable[this.a0 - 1][0] == 0x00)
          {
            this.b1 = this.filtertable[this.a0 - 1][1];
            this.a0++;
          }
        } else {
          // New modulation step
          if (filterLeft) {
            this.filterTime = filterLeft;
          } else {
            // Cutoff set
            this.b1 = filterRight;
            this.a0++;
          }
        }
      }

      // Filter modulation
      if (this.filterTime)
      {
        this.b1 += (filterRight & 0xff);
        this.filterTime--;
        if (this.filterTime == 0) {
          this.a0++;
        }
      }
    }

    // set filter/mastervolume
    this.c2[this.c9 + 0x15] = 0x00;
    this.c2[this.c9 + 0x16] = this.b1;//filtercutoff;
    this.c2[this.c9 + 0x17] = this.a7;//filterctrl;
    this.c2[this.c9 + 0x18] = this.b5 | this.b2;//filtertype | masterfader;

    var playheadUpdated = false;

    for(var c = 0; c < this.channels.length; c++) {//this.channelCount; c++) {
      var channel = this.channels[c];

      // what to execute this time around
      var doWaveExec = true;
      var doTickNEffects = true;
      var doPulseExec = true;
      var doGetNewNotes = true;

      if(true) {//!channel.finished) {
        var instrument = null;

        // if this is the test instrument player, the current instrument is the test instrument
        // only play it on the test instrument channel
        if(this.testInstrument != null) {
          doGetNewNotes = false;

          if(c == this.testInstrumentChannel) {
            instrument = this.testInstrument;
          } else {
            continue;
          }
        } else {
          instrument = this.music.instruments.getInstrument(channel.instrument);
        }

        // next tick
        channel.tick -= 1;

        // Tick N
        // Reload counter
        if(channel.tick < 0) {
          // tick has gone below zero, so reset it.

          if (channel.tempo >= 2) {
            channel.tick = channel.tempo;
          } else {
            // Set funktempo, switch between 2 values
            channel.tick = this.b9[channel.tempo];
            channel.tempo ^= 1;
          }
          // Check for illegally high gatetimer and stop the song in this case
          if (channel.gateTimer > channel.tick) {
            console.log('illegal gatetimer!!');
            //stopsong();
            // uh oh.
          }


          // update pattern position, track position, playhead, etc
          channel.a8++;

          // update the playhead..
          if(!playheadUpdated) {
            this.playheadPosition = this.newPlayheadPosition;
            this.newPlayheadPosition = this.playheadPosition + 1;
            playheadUpdated = true;
          }


          var track = this.music.doc.data.tracks[c];

          // TODO: track.getLength maybe not efficient
          if(channel.a8 >= this.music.tracks.getLength(c)) {

            channel.finished = true;
          } else {
            channel.finished = false;

            if(this.testInstrument == null) {

              var patternIndex = this.music.tracks.getPatternIndexAt(c, channel.a8);
              if(patternIndex !== false) {
                var patternId = this.music.tracks.getPatternIdAtIndex(c, patternIndex); 


                if(patternId !== false) {
                  if(patternId >= this.music.doc.data.patterns.length) {
                    channel.finished = true;
                  } else {                
                    channel.patternPosition = this.music.tracks.getPatternPositionAtIndex(c, patternIndex, channel.a8); 

                  }
                }
              }
            }
          }

        } else if(channel.tick == 0) {
          // Tick 0
          // TICK0:


          // Get gatetimer compare-value
          channel.gateTimer = instrument.gateTimer & 0x3f;

          if(channel.newNote) {
            // need to set up a new note

            channel.note = channel.newNote - 0x60;

            channel.command = 0;
            channel.c3 = instrument.vibratoDelay + 1;
            channel.c6 = instrument.vibratoSpeed;
            channel.c7 = instrument.vibratoDepth;

            channel.b3 = instrument.speedtable[0];

            if (channel.b6 != 3) {
              if (instrument.firstWave) {
                // set channel wave to the first wave
                // Values $00, $FE and $FF have special meaning:
                // leave waveform unchanged and additionally set gate off
                // ($FE), gate on ($FF), or gate unchanged ($00).
                if (instrument.firstWave >= 0xfe) {
                  channel.gate = instrument.firstWave;
                } else {
                  channel.wave = instrument.firstWave;
                  channel.gate = 0xff;
                }
              }

              // set the wavetable for the channel
              channel.wavetable = instrument.wavetable;
              channel.a3 = 0;
              if(channel.wavetable.length > 0) {
                channel.a3 = 1;
              }

              // set the pulsetable for the channel
              channel.pulsetable = instrument.pulsetable;
              channel.a1 = 0;
              if(channel.pulsetable.length > 0) {
                channel.a1 = 1;
              }
              channel.b7 = 0;

              channel.speedtable = instrument.speedtable;
              channel.speedtablePosition = 0;

              if(instrument.filtertable.length > 0) {
                this.filtertable = instrument.filtertable;
                this.a0 = 0;
                if(this.filtertable.length > 0) {
                  this.a0 = 1;
                }
              }

              // set adsr registers
              this.c2[this.c9 + 0x5 + 7*c] = (instrument.attack << 4) + instrument.decay;
              this.c2[this.c9 + 0x6 + 7*c] = (instrument.sustain << 4) + instrument.release;
            }
          }

          // still on tick 0
          // Tick 0 effects

          switch (channel.b6) {
            case 0:
              channel.command = 0;
              channel.b3 = 0;
              // TODO: check this
//              channel.b3 = instrument.speedtable[0];
              break;        


            case 1:
            case 2:
              channel.c8 = 0;
              channel.command = channel.b6;
              channel.b3 = channel.a6;

              channel.speed = channel.newSpeed;
              channel.b8 = channel.b0;
              channel.b4 = channel.a9;
            break;

            case 3:
            case 4:
              channel.command = channel.b6;
              channel.b3 = channel.a6;

              channel.speed = channel.newSpeed;
              channel.b8 = channel.b0;
              channel.b4 = channel.a9;


            break;

            case 5:
              this.c2[this.c9 + 0x5 + 7*c] = channel.a6;
            break;

            case 6:
              this.c2[this.c9 + 0x6 + 7*c] = channel.a6;
            break;

            case 7:
              channel.wave = channel.a6;
            break;



            case 10:
              // start a new filter.
              var filterIndex = channel.a6;
              if(filterIndex < this.music.doc.data.filters.length) {
                this.filtertable = this.music.doc.data.filters[filterIndex].filtertable;
                if(this.filtertable.length > 0) {
                  this.a0 = 1;
                  this.filterTime = 0;
                }
              }
            break;

            case 16:
              // stop current filter
              this.filtertable = [];
              this.a0 = 0;
              this.b5 = 0;
              this.fitlerTime = 0;
              this.a7 = 0;
              this.b1 = 0;
            break;

            case 11:
              // set filter resonance and channel bitmask
              this.a7 = channel.a6;
              if (!this.a7) {
                this.a0 = 0;
              }
            break;

            case 12:
              this.b1 = channel.a6;
//              console.log('set filter cutoff');

            break;

/*
            case 8:
            cptr->ptr[0] = cptr->newcmddata;
            cptr->wavetime = 0;
            if (cptr->ptr[0])
            {
              // Stop the song in case of jumping into a jump
              if (ltable[0][cptr->ptr[0]-1] == 0xff)
                stopsong();
            }
            break;

            case 9:
            cptr->ptr[1] = cptr->newcmddata;
            cptr->pulsetime = 0;
            if (cptr->ptr[1])
            {
              // Stop the song in case of jumping into a jump
              if (ltable[1][cptr->ptr[1]-1] == 0xff)
                stopsong();
            }
            break;


*/

            case 13:
              if (channel.a6 < 0x10) {
                this.b2 = channel.a6;
              }
            break;

            case 14:
              channel.speed = channel.newSpeed;
              channel.b8 = channel.b0;
              channel.b4 = channel.a9;

              for(var ch = 0; ch < this.channels.length; ch++) {
                this.channels[ch].tempo = 0;
              }

              this.b9[0] = channel.b8 - 1;
              this.b9[1] = channel.b4 - 1;
//              console.log('funk table = ' + this.b9);
            break;

            case 15:
            {
              var newTempo = channel.a6 & 0x7f;
              if(newTempo >= 3) {
                newTempo--;
              }

              if (channel.a6 >= 0x80) {
                channel.tempo = newTempo;
              } else {
                for(var ch = 0; ch < this.channels.length; ch++) {
                  this.channels[ch].tempo = newTempo;
                }

              }
            }
            break;                
          }

          if(channel.newNote) {

            // new note has been processed, so set it to zero
            channel.newNote = 0;

            if (channel.b6 != 3) {              
            // goto NEXTCHN;
              doWaveExec = false;
              doTickNEffects = false;
              doPulseExec = false;
              doGetNewNotes = false;            
            }
          }

        } // end if tick == 0


  //      WAVEEXEC:

        if(doWaveExec) {
        
          if(channel.a3 !== 0 && channel.a3 <= channel.wavetable.length) {
            var wave = channel.wavetable[channel.a3 - 1][0];
            var note = channel.wavetable[channel.a3 - 1][1];

/*
Wavetable left side:   00    Leave waveform unchanged
                       01-0F Delay this step by 1-15 frames
                       10-DF Waveform values
                       E0-EF Inaudible waveform values $00-$0F
                       F0-FE Execute command 0XY-EXY. Right side is parameter.
                       FF    Jump. Right side tells position ($00 = stop)

Wavetable right side:  00-5F Relative notes
                       60-7F Negative relative notes (lower pitch)
                       80    Keep frequency unchanged
                       81-DF Absolute notes C#0 - B-7
*/


            if(wave > 0xf) {
              // its not a delay command

              if (wave < 0xe0) {
                // set channel wave to a normal value
                // wave is between 0x10 and 0xdf
                channel.wave = wave;
              } 

              // Values without waveform selected
              if ((wave >= 0xe0) && (wave <= 0xef)) {
                // set channel wave to silent value
                // between 0xeo and 0xef
                channel.wave = wave & 0xf;
              }

              // Command execution from wavetable
              if ((wave >= 0xf0) && (wave <= 0xfe)) {
                // its a wavetable command

                //unsigned char param = rtable[0][cptr->ptr[0]-1];
                var param = channel.wavetable[channel.a3 - 1][1];

                switch (wave & 0xf)
                {
                  case 0:
                  case 8:
                  case 14:
                    //stopsong();
                  break;

                  case 1:
                  {

                    var speed = 0;
                    if (param && param <= channel.speedtable.length)
                    {
                      //speed = (ltable[3][param-1] << 8) | rtable[3][param-1];
                      speed = (channel.speedtable[param - 1][0] << 8) + channel.speedtable[param - 1][1];
                    }

                    if (speed >= 0x8000)
                    {
                      speed = SidPlayer.c0[channel.c5 + 1] | (SidPlayer.c1[channel.c5 + 1] << 8);
                      speed -= SidPlayer.c0[channel.c5] | (SidPlayer.c1[channel.c5] << 8);
                      speed >>= channel.speedtable[param - 1][1];
                    }
                    channel.freq += speed;
                  }
                  break;

                  case 2:
                  {
                    var speed = 0;
                    if (param && param <= channel.speedtable.length)
                    {
                      //speed = (ltable[3][param-1] << 8) | rtable[3][param-1];
                      speed = (channel.speedtable[param - 1][0] << 8) + channel.speedtable[param - 1][1];
                    }

                    if (speed >= 0x8000)
                    {
                      speed = SidPlayer.c0[channel.c5 + 1] | (SidPlayer.c1[channel.c5 + 1] << 8);
                      speed -= SidPlayer.c0[channel.c5] | (SidPlayer.c1[channel.c5] << 8);
                      speed >>= channel.speedtable[param - 1][1];
                    }
                    channel.freq -= speed;
                  }
                  break;

                  case 3:
                  {

                    var targetfreq = SidPlayer.c0[channel.note] | (SidPlayer.c1[channel.note] << 8);
                    var speed = 0;

                    if (!param)
                    {
                      channel.freq = targetfreq;
                      channel.c8 = 0;
                    } else {
                      speed = (channel.speedtable[param - 1][0] << 8) + channel.speedtable[param - 1][1];

                      if (speed >= 0x8000)
                      {
                        speed = SidPlayer.c0[channel.c5 + 1] | (SidPlayer.c1[channel.c5 + 1] << 8);
                        speed -= SidPlayer.c0[channel.c5] | (SidPlayer.c1[channel.c5] << 8);
                        speed >>= channel.speedtable[param - 1][1];;//rtable[3][param-1];
                      }
                      if (channel.freq < targetfreq)
                      {
                        channel.freq += speed;
                        if (channel.freq > targetfreq)
                        {
                          channel.freq = targetfreq;
                          channel.c8 = 0;
                        }
                      }
                      if (channel.freq > targetfreq)
                      {
                        channel.freq -= speed;
                        if (channel.freq < targetfreq)
                        {
                          channel.freq = targetfreq;
                          channel.c8 = 0;
                        }
                      }
                    }
                  }
                  break;

                  case 4:
                  {
                    var speed = 0;
                    var cmpvalue = 0;

                    if (param)
                    {
                      cmpvalue = (channel.speedtable[param - 1][0] & 0xff);
                      speed = channel.speedtable[param - 1][1];
                    }
                    if (cmpvalue >= 0x80)
                    {
                      cmpvalue &= 0x7f;
                      speed = SidPlayer.c0[channel.c5 + 1] | (SidPlayer.c1[channel.c5 + 1] << 8);
                      speed -= SidPlayer.c0[channel.c5] | (SidPlayer.c1[channel.c5] << 8);
                      speed >>= channel.speedtable[param - 1][1];//rtable[3][param-1];
                    }

                    if ((channel.c8 < 0x80) && (channel.c8 > cmpvalue)) {
                      channel.c8 ^= 0xff;
                    }

                    channel.c8 += 0x02;

                    if (channel.c8 & 0x01) {
                      channel.freq -= speed;
                    } else {
                      channel.freq += speed;
                    }
                  }
                  break;

                  case 5:
                    this.c2[this.c9 + 0x5+7*c] = param;
                  break;

                  case 6:
                    this.c2[this.c9 + 0x6+7*c] = param;;
                  break;

                  case 7:
                    channel.wave = param;
                  break;

/*
                  case 9:
                    cptr->ptr[1] = param;
                    cptr->pulsetime = 0;
                    if (cptr->ptr[1])
                    {
                      // Stop the song in case of jumping into a jump
                      if (ltable[1][cptr->ptr[1]-1] == 0xff)
                        stopsong();
                    }
                  break;

                  case 10:
                    filterptr = param;
                    filtertime = 0;
                    if (filterptr)
                    {
                      // Stop the song in case of jumping into a jump
                      if (ltable[2][filterptr-1] == 0xff)
                      stopsong();
                    }
                  break;
*/
                  case 11:
                    this.a7 = param;
                    if (!a7) {
                      this.filterPointer = 0;
                    }
                  break;

                  case 12:
//              console.log('set filter cutoff =param');

                    this.b1 = param;
                  break;

                  case 13:
                  if (channel.a6 < 0x10)
                    this.b2 = param;
                  break;
                }
              }

            } else {
              // Wavetable delay
              if (channel.c4 != wave)
              {
                // haven't finished delay yet
                channel.c4++;
                doWaveExec = false;
    //            goto TICKNEFFECTS;
              }
            }

            if(doWaveExec) {
              // dont want to do this if still in a delay..

              channel.c4 = 0;

              channel.a3++;

              if(channel.wavetable[channel.a3 - 1][0] == 0xff) {
                // wavetable jump.
                channel.a3 = channel.wavetable[channel.a3 - 1][1];
              }

              if ((wave >= 0xf0) && (wave <= 0xfe)) {
                // this wavetable entry was a command, so dont want to set the freq
                doWaveExec = false;
                doTickNEffects = false;
      //          goto PULSEEXEC;
              }

              // check if continuing with wave exec
              if(doWaveExec) {
                if (note != 0x80) {
                  if (note < 0x80) {
                    // relative note
                    note += channel.note;
                  }

                  note &= 0x7f;
                  channel.freq = SidPlayer.c0[note] | (SidPlayer.c1[note]<<8);
                  channel.c8 = 0;
                  channel.c5 = note;
                  doTickNEffects = false;
                  //goto PULSEEXEC;
                }
              }
            }
          }
        }

        // Tick N command
  //      TICKNEFFECTS:
        if(doTickNEffects && channel.tick) {
          switch(channel.command) {
            case 1:
            {
              var speed = 0;
              if (channel.speed)
              {
                speed = channel.speed;//(ltable[3][cptr->cmddata-1] << 8) | rtable[3][cptr->cmddata-1];
              }

              if (speed >= 0x8000)
              {
                speed = SidPlayer.c0[channel.c5 + 1] | (SidPlayer.c1[channel.c5 + 1] << 8);
                speed -= SidPlayer.c0[channel.c5] | (SidPlayer.c1[channel.c5] << 8);
                speed >>= channel.b4;//rtable[3][cptr->cmddata-1];
              }
              channel.freq += speed;
            }
            break;

            case 2:
            {
              var speed = 0;
              if (channel.speed)
              {
                speed = channel.speed;//(ltable[3][cptr->cmddata-1] << 8) | rtable[3][cptr->cmddata-1];
              }
              if (speed >= 0x8000)
              {
                speed = SidPlayer.c0[channel.c5 + 1] | (SidPlayer.c1[channel.c5 + 1] << 8);
                speed -= SidPlayer.c0[channel.c5] | (SidPlayer.c1[channel.c5] << 8);
                speed >>= channel.b4;//rtable[3][cptr->cmddata-1];

                /*
                speed = c0[cptr->c5 + 1] | (c1[cptr->c5 + 1] << 8);
                speed -= c0[cptr->c5] | (c1[cptr->c5] << 8);
                speed >>= rtable[3][cptr->cmddata-1];
                */
              }
              channel.freq -= speed;
            }
            break;


            case 0:
                // TODO: check this
//              if ((!channel.b3) || (!channel.c3)) {
              if (!channel.c3) {
                break;
              }
              if (channel.c3 > 1) {
                channel.c3--;
                break;
              }
              // falls through if c3 is 1
              case 4:
              {
                var speed = channel.c6;
                var depth = channel.c7;

                if(channel.command == 4) {
                  speed = (channel.b8 & 0xff);
                  depth = (channel.b4 & 0xff);
                }

//                unsigned short speed = 0;
//                unsigned char cmpvalue = 0;

                if(speed == 0 || depth ==0) {
                  // vibrato not set
                  break;
                }

                // if speed is negative
                if (speed >= 0x80)
                {
                  var tmp = depth;
                  speed &= 0x7f;
                  depth = SidPlayer.c0[channel.c5 + 1] | (SidPlayer.c1[channel.c5 + 1] << 8);
                  depth -= SidPlayer.c0[channel.c5] | (SidPlayer.c1[channel.c5] << 8);
                  depth >>= depth;//channel.b4;
                }


                if( (channel.c8 < 0x80) && (channel.c8 > speed)) {
                  channel.c8 ^= 0xff;
                }

                channel.c8 = (channel.c8 + 0x02) & 0xff;
                if(channel.c8 & 0x01) {
                  channel.freq -= depth;
                } else {
                  channel.freq += depth;

                }

              }
            break;            

            case 3:
            {

              var targetfreq = SidPlayer.c0[channel.note] | (SidPlayer.c1[channel.note] << 8);
              var speed = 0;

              if (!channel.speed)
              {
                channel.freq = targetfreq;
                channel.c8 = 0;
              }
              else
              {
                speed = channel.speed;//(ltable[3][cptr->cmddata-1] << 8) | rtable[3][cptr->cmddata-1];

                if (speed >= 0x8000)
                {
                  speed = SidPlayer.c0[channel.c5 + 1] | (SidPlayer.c1[channel.c5 + 1] << 8);
                  speed -= SidPlayer.c0[channel.c5] | (SidPlayer.c1[channel.c5] << 8);
                  speed >>= channel.b4;//rtable[3][cptr->cmddata-1];
                }
                if (channel.freq < targetfreq)
                {
                  channel.freq += speed;
                  if (channel.freq > targetfreq)
                  {
                    channel.freq = targetfreq;
                    channel.c8 = 0;
                  }
                }
                if (channel.freq > targetfreq)
                {
                  channel.freq -= speed;
                  if (channel.freq < targetfreq)
                  {
                    channel.freq = targetfreq;
                    channel.c8 = 0;
                  }
                }

              }
            }
            break;

          }

        }


  //      PULSEEXEC:
        if(doPulseExec && channel.tick) {
          if(channel.a1 > 0 && channel.a1 <= channel.pulsetable.length) {

            var left = channel.pulsetable[channel.a1 - 1][0];
            var right = channel.pulsetable[channel.a1 - 1][1];

            // Pulsetable jump
            if (left == 0xff)
            {
              channel.a1 = right;
              if(channel.a1 != 0) {
                left = channel.pulsetable[channel.a1 - 1][0];
                right = channel.pulsetable[channel.a1 - 1][1];
              } else {
                doPulseExec = false;
              }


//              cptr->ptr[1] = rtable[1][cptr->ptr[1]-1];
//              if (!cptr->ptr[1]) goto PULSEEXEC;
            }
/*
Pulsetable left side:  01-7F Pulse modulation step. Left side indicates time
                             and right side the speed (signed 8-bit value).
                       8X-0x40 Set pulse width. X is the high 4 bits, right
                             side tells the 8 low bits.
                       FF    Jump. Right side tells position ($00 = stop)
*/                       

            if(doPulseExec) {
              if(channel.b7 == 0) {
                // Set pulse
                if (left >= 0x80)
                {
                  channel.pulse = (left & 0xf) << 8;//(ltable[1][cptr->ptr[1]-1] & 0xf) << 8;
                  channel.pulse |= right;//rtable[1][cptr->ptr[1]-1];
                  channel.a1++;
                } else {
                  channel.b7 = left;
                }
              }

              // pulse modulation
              if(channel.b7 != 0) {
                var speed = right & 0xff;
                if (speed < 0x80)
                {
                  channel.pulse += speed;
                  channel.pulse &= 0xfff;
                } else {
                  channel.pulse += speed;
                  channel.pulse -= 0x100;
                  channel.pulse &= 0xfff;
                }
                channel.b7--;

                if (channel.b7 == 0) {
                  channel.a1++;
                }
              }
            }
          }
        }



        var track = this.music.doc.data.tracks[c];
        var patternId = this.music.tracks.getPatternAt(c, channel.a8);
        var patternDuration = 0;

        if(patternId !== false) {
          patternDuration = this.music.patterns.getDuration(patternId);
        } else {
          if(channel.tick == 0) {
            // no current pattern, so set the gate to off?
            channel.gate = 0xfe;          
          }
        }


        // New notes processing
        if(patternId !== false && doGetNewNotes) {

          if(channel.tick == channel.gateTimer && channel.patternPosition < patternDuration) {
      //      GETNEWNOTES:
              // tick has reached gate timer value, so get the new note data

            if(channel.patternPosition < patternDuration) {
              var effect = this.music.patterns.getParamAt(patternId, "effects", channel.patternPosition);
              if(effect != null) {
                channel.b6 = effect.values.effect;
                channel.a6 = effect.values.value1;
                channel.a5 = effect.values.value2;

              } else {
                channel.b6 = 0;
                channel.a6 = 0;
                channel.a5 = 0;
              }


              if(typeof channel.b6 == 'undefined') {
                channel.b6 = 0;
              }
              if(typeof channel.a6 == 'undefined') {
                channel.a6 = 0;
              }

              var patternNote = this.music.patterns.getNoteAt(patternId, channel.patternPosition);

              if(patternNote !== null) {
                // its a new note

                channel.newNote = patternNote.pit + 0x60;

                if(channel.b6 == 17 && channel.instrument == patternNote.ins) {
                  channel.b6 = 3;
                  channel.a6 = 0;
                }

                channel.instrument = patternNote.ins;
                channel.a2 = patternNote.dur;


                // keyoff = 0xbe
                // only want key off if the instrument is '0'
                /*
                if (channel.newNote == 0xbe) {
                  channel.gate = 0xfe;
                }
                */

                // keyon = 0xbf
                // never want keyon??
                /*
                if (channel.newNote == 0xbf) {
                  channel.gate = 0xff;
                }
                */
                //channel.gate = 0xff;
                // last note is 0xbc
                if(channel.newNote <= 0xbc) {
                  if ((channel.b6) != 3) {
                    // its not a portamento note
                    // ff is gate on, fe is gate off
                    // 0x40 for gatetimer disables gateoff
                    // 0x80 for gatetimer disables hard restart

                    if (!(this.music.instruments.getInstrument(channel.instrument).gateTimer & 0x40)) {

                      channel.gate = 0xfe;

                      if (!(this.music.instruments.getInstrument(channel.instrument).gateTimer & 0x80)) {
                        // hard restart
                        /*
                          The hard restart ADSR parameter will especially affect how rapid passages of
                          notes will sound like. 0000 is probably too hard to be useful, except perhaps
                          with gateoff timer value 1. 0F00 (default) is a lot softer, and 0F01 adds also
                          a little bit of release to the gateoff phase for even softer sound. 000F makes
                          the note start very pronounced.
                        */                      
                        this.c2[this.c9 + 0x5 + 7*c] = (this.a4 >> 8) & 0xff;
                        this.c2[this.c9 + 0x6 + 7*c] = this.a4 & 0xff;                                        
                      }
                    }
                  }
                }
              } else {

                if(channel.a2 > 0) {
                  // instrument currently playing
                  channel.a2--;
                  if(channel.a2 == 0) {
                    // instrument is over..
                    // 0xbe

                    channel.gate = 0xfe;

                  } else {
                    // instrument still going
                    // REST
                    if(channel.b6 == 3) {
                      channel.newNote = effect.values.value2 + 0x60;
                    }
                  }
                } else {
                  // REST
                  // no instrument playing..
                }

              }

              // store values here instead of speed table
              if(  channel.b6 == 1
                || channel.b6 == 2
                || channel.b6 == 3
                || channel.b6 == 4
                || channel.b6 == 14) {

  //              console.log('channel new command: ' + channel.b6 + ':' + channel.a6);
  /*
                if(channel.b6 == 4) {
                  channel.b0 = channel.a6;
                  channel.a9 = channel.a5;

                } else {
  */                
                  channel.newSpeed = channel.a6;
                  channel.b0 = (channel.newSpeed >> 8);
                  channel.a9 = (channel.newSpeed & 0xff);

                  if(channel.b6 == 14) {
//                    console.log('funk tempo: ' + channel.b0 + ',' + channel.a9);
                  }
  //              }
              }
            
            }
          }
        } else {
          // no current pattern, but check if instrument is over


        }

        // TODO: where to place this block?
        if(channel.tick == 0) {
          /*

          channel.patternPosition++;

          // update the playhead..
          this.playheadPosition = this.newPlayheadPosition;

          if(c == this.channels.length - 1) {
            this.newPlayheadPosition = this.playheadPosition + 1;
          }
          if(channel.patternPosition >= pattern.duration) {
            channel.patternPosition = 0;
            channel.a8++;
            if(channel.a8 >= this.music.doc.data.tracks[c].length) {
              channel.finished = true;
            }
          }

          */
        }


  //      NEXTCHN:
        if (channel.mute) {
          this.c2[this.c9 + 0x4 + 7*c] = 0x08;
          this.sid.setWave(this.c9 + 0x4);          
        } else {

          this.c2[this.c9 + 0x0 + 7*c] = channel.freq & 0xff;
          this.c2[this.c9 + 0x1 + 7*c] = channel.freq >> 8;

          this.c2[this.c9 + 0x2 + 7*c] = channel.pulse & 0xfe;
          this.c2[this.c9 + 0x3 + 7*c] = channel.pulse >> 8;

          var prev = this.c2[this.c9 + 0x4 + 7*c];

          if(channel.gate == 255 || channel.gate == 254) {
            this.c2[this.c9 + 0x4 + 7*c] = channel.wave & channel.gate;
          }
          
          if(prev != this.c2[this.c9 + 0x4 + 7*c]) {

//            console.log(channel.gate);
            this.sid.setWave(this.c9 + 0x4 + 7*c);
          
          }
        }




      }
    }


//    console.log(this.channels[0].tick + ',' + this.channels[1].tick + ',' + this.channels[2].tick + '   ' +
//      this.channels[0].patternPosition + ',' + this.channels[1].patternPosition + ',' + this.channels[2].patternPosition);

    var songFinished = true;

    for(var i = 0; i < this.channels.length; i++) {
      if(!this.channels[i].finished) {
        songFinished = false;  
      }
    }

    if(songFinished) {
      // reset to beginning?
//      console.log("RESET PLAYHEAD POSITION!!!!");

      this.playheadPosition = 0;
      this.newPlayheadPosition = 0;
      for(var i = 0; i < this.channels.length; i++) {
        this.channels[i].a8 = 0;
        this.channels[i].patternPosition = 0
        this.channels[i].finished = false;
        this.channels[i].tick = this.channels[i].tempo - 1;
      }
    }
  }
}

var SidEffectsChooser = function() {

  this.patternView = null;
  this.patternId = false;
  this.uiComponent = null;

  this.currentEffects = [];


  this.newEffects = [];

  this.effectStart = false;
  this.effectEnd = false;

  this.paramCanvas = null;

  this.mouseInBar = false;
  this.mouseDownInParams = false;


  this.paramMaxValue = 255;
  this.paramMinValue = 0;

  this.effect = 0;
  this.editingParam = 1;

}

SidEffectsChooser.prototype = {
  init: function(patternView) {
    this.patternView = patternView;
    this.music = this.patternView.music;
  },

  chooseEffect: function(start, end) {
    var _this = this;

    this.effectStart = start;
    this.effectEnd = end;

    this.currentEffects = [];
    this.newEffects = [];

    this.patternId = this.patternView.getPatternId();
    
    // save the current effects
    for(var i = this.effectStart; i <= this.effectEnd; i++) {
      var param = this.music.patterns.getParamAt(this.patternId, "effects", i);
      var effect = 0;
      var value1 = 0;
      var value2 = 0;

      if(param) {
        effect = param.values.effect;
        value1 = param.values.value1;
        value2 = param.values.value2;
      }

      this.currentEffects.push({
        "effect": effect,
        "param":  value1,
        "param2": value2
      });

      switch(effect) {
        case 4: // vibrato
          value2 = value1 & 0xff;
          value1 = (value1 >> 8) & 0xff;
        break;

        case 5: // attack/decay
          value2 = value1 & 0xf;
          value1 = (value1 >> 4) & 0xf;
        break;

        case 6: // sustain/release
          value2 = value1 & 0xf;
          value1 = (value1 >> 4) & 0xf;
        break;
        case 11: // set resonance/channels
          if(i == this.effectStart) {
            // just take channel from first one
            $('#sidEffectFilterChannel_1').prop('checked', (value1 & 0x1) != 0);
            $('#sidEffectFilterChannel_2').prop('checked', (value1 & 0x2) != 0);
            $('#sidEffectFilterChannel_3').prop('checked', (value1 & 0x4) != 0);
          }

          value1 = (value1 >> 4) & 0xff;
        break;
      }

      this.newEffects.push({
        "param":  value1,
        "param2": value2
      });
    }

    if(this.uiComponent == null) {
      this.uiComponent = UI.create("UI.Dialog", { "id": "sidEffectsChooser", "title": "Effect", "width": 640 });

/*
      this.uiComponent.on('mousedown', function(event) {
        _this.mouseDown(event);
      });

      this.uiComponent.on('mouseup', function(event) {
        _this.mouseUp(event);
      });
      this.uiComponent.on('mousemove', function(event) {
        _this.mouseMove(event);
      });
*/

      this.htmlComponent = UI.create("UI.HTMLPanel");
      this.uiComponent.add(this.htmlComponent);
      this.htmlComponent.load('html/music/sid/sidEffectsChooser.html', function() {
        _this.initContent();
        _this.initEvents();

        UI.showDialog("sidEffectsChooser");

      });

      this.okButton = UI.create('UI.Button', { "text": "OK", "color": "primary" });
      this.uiComponent.addButton(this.okButton);
      this.okButton.on('click', function(event) {
        _this.ok();
      });

      this.closeButton = UI.create('UI.Button', { "text": "Cancel" });
      this.uiComponent.addButton(this.closeButton);
      this.closeButton.on('click', function(event) {
        _this.cancel();
      });
    } else {
      this.initContent();
      UI.showDialog("sidEffectsChooser");
    }

  },




  ok: function() {



    UI.closeDialog();
  },

  cancel: function() {
    UI.closeDialog();
  },


  setEffect: function() {
    this.effect = parseInt($('#sidEffect').val());
    var param = 0;
    var param2 = 0;

    this.editingParam = 1;

    switch(this.effect) {
      case 1:  // portamento up
      case 2:  // portamento down
        param = parseInt($('#sidEffectPortamentoSpeed').val());
        this.paramMinValue = 0;
        this.paramMaxValue = 65535;
        this.paramMaxValue = 1024;
        this.editingParam = 1;
      break;
      case 3:  // portamento to
        param = parseInt($('#sidEffectPortamentoSpeed').val());
        param2 = parseInt($('#sidEffectPortamentoTo').val());

        this.paramMinValue = 0;
        this.paramMaxValue = 92;

        this.editingParam = 2;

      break;
      case 4: // vibrato
        this.paramMinValue = 0;
        this.paramMaxValue = 127;

//        var speed = parseInt($('#sidEffectVibratoSpeed').val());
//        var depth = parseInt($('#sidEffectVibratoDepth').val());  
//        param = (speed << 8) + (depth & 0xff);
      break;      
      case 5: // set attack/decay

        this.paramMinValue = 0;
        this.paramMaxValue = 15;
        var attack = parseInt($('#sidEffectAttack').val());
        var decay = parseInt($('#sidEffectDecay').val());
        param = (attack << 4) + decay;
      break;
      case 6: // set sustain/release
        this.paramMinValue = 0;
        this.paramMaxValue = 15;

        var sustain = parseInt($('#sidEffectSustain').val());
        var release = parseInt($('#sidEffectRelease').val());
        param = (sustain << 4) + release;
      break;
      case 10: //start filter
        param = parseInt($('#sidEffectFilter').val());
      break;
      case 16: // stop filter
        this.effect = 16;
        param = 0;
      break;

      case 11: // set filter resonance/channels

        this.paramMinValue = 0;
        this.paramMaxValue = 15;

        param = parseInt($('#sidEffectFilterResonance').val());
        param = (param << 4);
        if($('#sidEffectFilterChannel_1').is(':checked')) {
          param = param + 0x01;
        }
        if($('#sidEffectFilterChannel_2').is(':checked')) {
          param = param + 0x02;
        }
        if($('#sidEffectFilterChannel_3').is(':checked')) {
          param = param + 0x04;
        }
      break;

      case 12: // filtercutoff
        this.effect = 12;
        param = parseInt($('#sidEffectFilterCutoff').val());
        this.editingParam = 1;
        this.paramMinValue = 0;
        this.paramMaxValue = 255;
      break;

      case 13: // master volume
        this.effect = 13;
        this.paramMinValue = 0;
        this.paramMaxValue = 15;
      break;
      case 14:
        this.effect = 14;
        param = parseInt($('#sidEffectTempo1').val()) << 8;        
        param += parseInt($('#sidEffectTempo2').val()) & 0xff;        
      break;
      case 15: // set tempo
        this.effect = 15;
        param = parseInt($('#sidEffectTempo').val());        
      break;
      case 17: // legato
        this.effect = 17;
      break;  
    }


    this.updatePattern();
    this.patternView.drawPattern();
    this.drawParamCanvas();
  },


  updatePattern: function() {
    var patternDuration = this.music.patterns.getDuration(this.patternId);

    for(var i = this.effectStart; i <= this.effectEnd; i++) {
      if(i >= 0 && i < patternDuration) {
        var param = this.newEffects[i - this.effectStart].param;
        var param2 = this.newEffects[i - this.effectStart].param2;

        switch(this.effect) {
          case 3: // param to note
            param = parseInt($('#sidEffectPortamentoSpeed').val(), 10);
            param2 = this.newEffects[i - this.effectStart].param2;
          break;
          case 4: // vibrato
//            var speed = parseInt($('#sidEffectVibratoSpeed').val());
//            param2 = parseInt($('#sidEffectVibratoDepth').val());  

            //combine params into one
            param = (param << 8) + (param2 & 0xff);
            param2 = 0;

//            param2 = $('#sidEffectVibratoDepth').val();
          break;

          case 5: // attack/decay
            var attack = param;
            var decay = param2;
            param = (attack << 4) + decay;    
          break;      

          case 6: // sustain/release
            var sustain = param;
            var release  = param2;

            param = (sustain << 4) + release;    
          break;      




          case 10: //start filter
            param = parseInt($('#sidEffectFilter').val());
          break;


          case 11: //set resonance
            param = (param << 4);
            if($('#sidEffectFilterChannel_1').is(':checked')) {
              param = param + 0x01;
            }
            if($('#sidEffectFilterChannel_2').is(':checked')) {
              param = param + 0x02;
            }
            if($('#sidEffectFilterChannel_3').is(':checked')) {
              param = param + 0x04;
            }
          break;
          case 14: // funk tempo
            param = parseInt($('#sidEffectTempo1').val()) << 8;        
            param += parseInt($('#sidEffectTempo2').val()) & 0xff;        
          break;
          case 15: // tempo
            param = parseInt($('#sidEffectTempo').val());        
          break;

        }

        if(typeof param == 'undefined') {
          param = 0;
        }

        if(typeof param2 == 'undefined') {
          param2 = 0;
        }

        this.music.patterns.addParam(this.patternId, "effects", i, 
          { "effect": this.effect, "value1": param, "value2": param2 } );

//        this.music.patterns.addEffect(this.patternId, i, this.effect,param, param2);        
      }
    }
  },
  initEvents: function() {
    var _this = this;

    $('#sidEffect').on('change', function() {
      var effect = $('#sidEffect').val();
      _this.setEffectParamVisible();
      _this.setEffect();
      UI('sidEffectsChooser').fitContent();
    });



    // vibrato
    $('input[name=sidEffectVibratoEditParam]').on('click', function() {
      _this.setVibratoEditParam();
    });


    // attack/decay
    $('input[name=sidEffectAttackDecayEditParam]').on('click', function() {
      _this.setAttackDecayEditParam();
    });


    // sustain/release
    $('input[name=sidEffectSustainReleaseEditParam]').on('click', function() {
      _this.setSustainReleaseEditParam();
    });


    $('#sidEffectTempo1').on('change', function() {
      _this.updatePattern();
    });

    $('#sidEffectTempo2').on('change', function() {
      _this.updatePattern();
    });

    $('#sidEffectTempo').on('change', function() {
      _this.updatePattern();

    });


    var element = document.getElementById('sidEffectsChooser');

    element.addEventListener('mousedown', function(event) {
      _this.mouseDown(event);
    }, false);

    element.addEventListener('mousemove', function(event) {
      _this.mouseMove(event);
    }, false);

    element.addEventListener('mouseup', function(event) {
      _this.mouseUp(event);
    }, false);


  },

  initContent: function() {

    var _this = this;
    this.drawParamCanvas();

    // create the notes dropdown
    this.noteMap = [];
    for(var j = 0; j < 92; j++) {
      this.noteMap[j] = '';
    }

    var notes = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

    var html = '';
    html = '<select name="sidEffectPortamentoTo" class="formControl" id="sidEffectPortamentoTo">';
    for(var j = 92; j >=0; j--) {
      var noteIndex = j % 12;
      var octave = Math.floor(j / 12);
      var note = notes[noteIndex] + octave;
      this.noteMap[j] = note;

      html += '<option value="' + j + '" >' + note + '</option>';
    }

    html += '</select>';

    $('#sidEffectPortamentoToControl').html(html);



    // create the filters dropdown
    var filterHTML = '';
    filterHTML = '<select id="sidEffectFilter" class="formControl">';
    var filterID = 1;
    for(var i = 1; i < this.music.doc.data.filters.length; i++) {
      filterID = i;
      filterHTML += '<option value="' + filterID + '">' + this.music.doc.data.filters[i].name + '</option>';
      filterID += this.music.doc.data.filters[i].filtertable.length;
    }
    filterHTML += '</select>';
    $('#sidEffectFilterControl').html(filterHTML);
    $('#sidEffectFilter').on('change', function() {
      _this.updatePattern();
    });

    // set to current effect
    if(this.currentEffects.length == 0) {
      return;
    }

    $('#sidEffect').val(this.currentEffects[0].effect);
    this.setEffectParamVisible();


  },


  setVibratoEditParam: function() {
    var param = $('input[name=sidEffectVibratoEditParam]:checked').val();


    if(param == 'speed') {
      $('#sidEffectParamSetVibratoSpeed').hide();
      $('#sidEffectParamSetVibratoDepth').hide();
      this.paramMaxValue = 127;
      this.editingParam = 1;
    }

    if(param == 'depth') {
      $('#sidEffectParamSetVibratoSpeed').hide();
      $('#sidEffectParamSetVibratoDepth').hide();
      this.paramMaxValue = 255;

      this.editingParam = 2;
    }

    this.drawParamCanvas();
  },


  setAttackDecayEditParam: function() {
    var param = $('input[name=sidEffectAttackDecayEditParam]:checked').val();

    if(param == 'attack') {
      $('#sidEffectParamAttack').hide();          
      $('#sidEffectParamDecay').hide();          
      this.editingParam = 1;
    }

    if(param == 'decay') {
      $('#sidEffectParamAttack').hide();          
      $('#sidEffectParamDecay').hide();                
      this.editingParam = 2;
    }

    this.drawParamCanvas();
  },


  setSustainReleaseEditParam: function() {
    var param = $('input[name=sidEffectSustainReleaseEditParam]:checked').val();

    if(param == 'sustain') {
      $('#sidEffectParamSustain').hide();          
      $('#sidEffectParamRelease').hide();          
      this.editingParam = 1;
    }

    if(param == 'release') {
      $('#sidEffectParamSustain').hide();          
      $('#sidEffectParamRelease').hide();                
      this.editingParam = 2;
    }

    this.drawParamCanvas();
  },

  setEffectParamVisible: function() {
    var effect = parseInt($('#sidEffect').val());

    $('.sidEffectParam').hide();
    $('#sidEffectsParamGraph').hide();

    switch(effect) {
      case 1:  // portamento up
      case 2:  // portamento down
//        $('#sidEffectParamPortamentoSpeed').show();
        $('#sidEffectsParamGraph').show();
      break;
      case 3:  // portamento to
//        $('#sidEffectParamPortamentoSpeed').show();
//        $('#sidEffectParamPortamentoTo').show();          
        $('#sidEffectsParamGraph').show();
      break;
      case 4: // set vibrato
//        $('#sidEffectParamSetVibratoSpeed').show();
//        $('#sidEffectParamSetVibratoDepth').show();
        $('#sidEffectVibrato').show();
        $('#sidEffectVibratoEditParam_speed').prop('checked', true);
        $('#sidEffectsParamGraph').show();
        this.setVibratoEditParam();
        
        break;
      case 5: // set attack/decay
        $('#sidEffectAttackDecay').show();
//        $('#sidEffectParamAttack').show();          
//        $('#sidEffectParamDecay').show();          
        $('#sidEffectAttackDecayEditParam_attack').prop('checked', true);
        $('#sidEffectsParamGraph').show();
        this.setAttackDecayEditParam();
      break;

      case 6: // set sustain/release
//        $('#sidEffectParamSustain').show();          
//        $('#sidEffectParamRelease').show();          
        $('#sidEffectSustainRelease').show();

        $('#sidEffectSustainReleaseEditParam_sustain').prop('checked', true);
        $('#sidEffectsParamGraph').show();
        this.setSustainReleaseEditParam();
      break;
      case 10: //start filter
        $('#sidEffectParamFilter').show();          
      break;
      case 11: // set filter resonance/channels
        $('#sidEffectParamFilterResonance').show();          
        $('#sidEffectParamFilterChannels').show();          
        $('#sidEffectsParamGraph').show();
      break;
      case 12: // filter cutoff
        //$('#sidEffectParamFilterCutoff').show();
        $('#sidEffectsParamGraph').show();
      break;

      case 13: // volume
        //$('#sidEffectParamVolume').show();
        $('#sidEffectsParamGraph').show();
      break;
      case 14: // set funk tempo
        $('#sidEffectParamTempo1').show();
        $('#sidEffectParamTempo2').show();      
      break;
      case 15: // set tempo
        $('#sidEffectParamTempo').show();
      break;
      case 17:  // legato

      break;
    }
  },

  setParamValueFromMouse: function() {
    var max = this.paramMaxValue;
    var height = this.paramCanvas.height;
    var value = Math.ceil(((height - this.mouseBarY) / height) * max);
    if(this.editingParam == 1) {
      this.newEffects[this.mouseInBar].param = value;
    } else {
      this.newEffects[this.mouseInBar].param2 = value;
    }
    this.updatePattern();

    this.drawParamCanvas();
    this.updateEffectParamInfo();
  },

  mouseDown: function(event) {
    var x = event.clientX;
    var y = event.clientY;

    var canvasOffset = $('#sidEffectParamCanvas').offset();

    if(x >= canvasOffset.left && x < canvasOffset.left + this.paramCanvas.width &&
       y >= canvasOffset.top && y < canvasOffset.top + this.paramCanvas.height) {

      /*
      var xOffset = x - canvasOffset.left;
      var yOffset = this.paramCanvas.height - (y - canvasOffset.top);
      var bar = Math.floor(xOffset / this.barHolderWidth);

      this.mouseInBar = bar;
      this.mouseBarY = (y - canvasOffset.top);
      */

      this.setParamValueFromMouse();

      this.mouseDownInParams = true;
    }


  },

  updateEffectParamInfo: function() {
    var html = '';
    var highlightedBar = this.mouseInBar;
    var bars = this.effectEnd - this.effectStart + 1;
    if(this.mouseInBar !== false && this.mouseInBar < bars) {
      var patternPosition = this.effectStart + this.mouseInBar;
      html += '<div>';
      html += 'Position: ' + patternPosition;
      html += '</div>';

      var value = 0;
      if(this.editingParam == 1) {
        value = this.newEffects[this.mouseInBar].param;
      } else {
        value = this.newEffects[this.mouseInBar].param2;
      }



      if(typeof value == 'undefined') {
        value = '';
      } else {
        value = parseInt(value, 10);
        if(isNaN(value)) {
          value = '';
        } else {
          if(this.effect == 3) {
            if(value >= 0 && value <= this.noteMap.length) {
              value = this.noteMap[value];
            }
          }
        }
      }


      html += '<div>';
      html += 'Value:' + value;
      html += '</div>';
    } else {
      html = '';
    }

    $('#sidEffectsParamGraphInfo').html(html);

  },

  drawParamCanvas: function() {
    if(this.paramCanvas == null) {
      this.paramCanvas = document.getElementById('sidEffectParamCanvas');
      this.paramContext = this.paramCanvas.getContext('2d');
    }

    this.paramContext.fillStyle = '#000000';
    this.paramContext.fillRect(0, 0, this.paramCanvas.width, this.paramCanvas.height);


    var width = this.paramCanvas.width;
    var height = this.paramCanvas.height;
    var bars = this.effectEnd - this.effectStart + 1;
    this.barHolderWidth = width / bars;
    this.barGap = 2;//barHolderWidth 

    var barMaxHeight = height;

    for(var i = 0; i < bars; i++) {
      var x = i * this.barHolderWidth + this.barGap;

      var max = this.paramMaxValue;
      var value = 0;
      if(this.editingParam == 1) {
        value = this.newEffects[i].param;
      } else {
        value = this.newEffects[i].param2;
      }
      var barHeight = barMaxHeight * value / max;


      var y = 100;// + i * 20;
      if(i === this.mouseInBar) {

        this.paramContext.beginPath();    
        this.paramContext.strokeStyle = styles.music.oscilloscopeLines;
        this.paramContext.lineWidth = 1;        
        this.paramContext.moveTo(x, this.mouseBarY + 0.5);
        this.paramContext.lineTo(x + this.barHolderWidth - (2 * this.barGap), this.mouseBarY + 0.5);
        this.paramContext.stroke();


        this.paramContext.fillStyle = '#eeeeee';
      } else {
        this.paramContext.fillStyle = '#aaaaaa';
      }
      this.paramContext.fillRect(x, height - barHeight, this.barHolderWidth - (2 * this.barGap) , barHeight);
    }
  },

  mouseMove: function(event) {

    var x = event.clientX;
    var y = event.clientY;

    var canvasOffset = $('#sidEffectParamCanvas').offset();

    if(x >= canvasOffset.left && x < canvasOffset.left + this.paramCanvas.width &&
       y >= canvasOffset.top && y < canvasOffset.top + this.paramCanvas.height) {
      var xOffset = x - canvasOffset.left;
      var yOffset = this.paramCanvas.height - (y - canvasOffset.top);
      var bar = Math.floor(xOffset / this.barHolderWidth);

      if(bar != this.mouseInBar || this.mouseBarY != (y - canvasOffset.top)) {

        this.mouseInBar = bar;
        this.mouseBarY = (y - canvasOffset.top);
        this.updateEffectParamInfo();

        if(this.mouseDownInParams) {
          // mouse is currently down
          this.setParamValueFromMouse();
        } else {
          this.drawParamCanvas();
        }

      }
    }
  },

  mouseUp: function(event) {
    this.mouseDownInParams = false;

  }


}


function LightenDarkenColor(col,amt) {

  var r = (col >> 16) + amt;

  if ( r > 255 ) r = 255;
  else if  (r < 0) r = 0;

  var b = ((col >> 8) & 0x00FF) + amt;

  if ( b > 255 ) b = 255;
  else if  (b < 0) b = 0;

  var g = (col & 0x0000FF) + amt;

  if ( g > 255 ) g = 255;
  else if  ( g < 0 ) g = 0;

  //return (usePound?"#":"") + (g | (b << 8) | (r << 16)).toString(16);

  return g | (b << 8) | (r << 16);
}


