          html += '</label>';

          html += '&nbsp;&nbsp;';

          html += '<label>';
          html += 'Depth';
          html += '<input size="4" class="number editInstrumentWavetableParam" min="0" max="255" value="' + vibratoDepth + '" id="row' + i + '_vibratoDepth"/> / Tick (0-255)';
          html += '</label>';

          html += '</span>';

          // attack/decay
          var attack = 0;
          var decay = 0;
