var formatNumber = function(num, n, s) {
  var newString = '';
  var numLength = num.length;
  for(var i = 0; i < numLength; i++) {
    var c = num[numLength - 1 - i];
    if(i % n == 0 && i != 0) {
      newString = s + newString;
    }
    newString = c + newString ;
  }
  return newString;
};


